/*
 * TOPIK I usage notes — the part-of-speech-aware layer over word-notes.js.
 *
 * word-notes.js is keyed by Hangul alone, which cannot serve this bank: 이 is
 * four separate rows here (tooth, this one, this, two) and 있다 is three
 * (verb, adjective, auxiliary). Every note below is keyed "korean|partOfSpeech"
 * and wins over the shared file. The page falls back to word-notes.js only for
 * a spelling that appears exactly once in the bank.
 *
 * Each note carries:
 *   note    - how the word is actually used, and the distinction learners get
 *             wrong (안 the position noun vs 안 the negation adverb)
 *   example - { ko, en, form }, where form says what happened to the headword,
 *             e.g. "크다 → 커요 (ㅡ drops before -어요; present, polite casual)"
 *
 * Browser: <script src="./topik-i-notes.js"></script> -> window.TopikINotes
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.TopikINotes = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";

  const NOTES = {
    // ================================================================= day 1
    "때|noun": { korean: "때", note: "The time or occasion when something happens, almost always as modifier + 때: 어릴 때 (when I was young), 방학 때 (during the holidays). It is not a clock time — that is 시간 — and it never stands alone as a subject.", example: { ko: "학교에 갈 때 버스를 타요.", en: "I take the bus when I go to school.", form: "가다 → 갈 (future/prospective modifier -ㄹ) + 때; 타다 → 타요 (present, polite casual)" } },
    "말|noun": { korean: "말", note: "Speech, words, or what someone said — 말이 많다 is 'talks a lot', not 'has many horses'. The identical 말 meaning horse exists but is rare at this level. 말하다 is the verb; 말씀 is the honorific noun.", example: { ko: "그 말이 맞아요.", en: "That is right. (Those words are correct.)", form: "말 + 이 (subject particle after a batchim); 맞다 → 맞아요 (present, polite casual)" } },
    "일|noun": { korean: "일", note: "Work or a matter to deal with. 일하다 means to work; 일이 있다 means 'something has come up'. The Sino-Korean number 일 (one) and the day counter 일 are separate entries in this bank.", example: { ko: "오늘 일이 많아요.", en: "I have a lot of work today.", form: "일 + 이 (subject particle); 많다 → 많아요 (present, polite casual)" } },
    "있다|verb": { korean: "있다", note: "The 'stay, remain' sense: 집에 있다 = to stay home. It conjugates as an action verb here, so the imperative 있으세요 and 있자 are possible, which the existence sense does not allow.", example: { ko: "오늘은 집에 있어요.", en: "I am staying home today.", form: "있다 → 있어요 (present, polite casual); 집 + 에 (location particle)" } },
    "있다|adjective": { korean: "있다", note: "The existence sense — 'there is' or 'to have'. The thing that exists takes 이/가: 책이 있어요. Its negative is the separate word 없다, never 안 있다.", example: { ko: "시간이 있어요?", en: "Do you have time?", form: "시간 + 이 (subject particle); 있다 → 있어요 (present, polite casual, question)" } },
    "있다|auxiliary verb": { korean: "있다", note: "-고 있다 makes an action ongoing, the closest Korean gets to English '-ing'. Attach 고 to the verb stem: 먹다 → 먹고 있다. For a state that resulted from an action use -어 있다 instead (앉아 있다 = to be seated).", example: { ko: "지금 밥을 먹고 있어요.", en: "I am eating right now.", form: "먹다 → 먹고 있다 → 먹고 있어요 (progressive, present, polite casual)" } },
    "하나|numeral": { korean: "하나", note: "Native Korean 'one', used for counting aloud and when the number stands alone: 하나, 둘, 셋. Before a counter it shortens to 한 — 한 개, never 하나 개.", example: { ko: "사과 하나 주세요.", en: "Please give me one apple.", form: "하나 standing alone after the noun; 주다 → 주세요 (polite request)" } },
    "하나|noun": { korean: "하나", note: "The noun 'one thing, a single one', which unlike the numeral can take particles: 하나만 (only one), 하나도 (not even one, with a negative).", example: { ko: "하나도 몰라요.", en: "I do not know a single thing.", form: "하나 + 도 (even, with a negative); 모르다 → 몰라요 (르-irregular, present, polite casual)" } },
    "은|particle": { korean: "은", note: "The topic marker after a noun ending in a consonant; 는 after a vowel. It sets what the sentence is about and often implies contrast — 저는 학생이에요 answers 'and you?'. Use 이/가 instead when you are introducing new information.", example: { ko: "저는 학생이에요.", en: "I am a student.", form: "저 ends in a vowel so it takes 는; a batchim noun would take 은: 선생님은" } },
    "것|dependent noun": { korean: "것", note: "A bound noun meaning 'thing' or 'the one', which can never stand alone — it always follows a modifier: 제 것 (mine), 큰 것 (the big one). In speech it contracts to 거.", example: { ko: "이것은 제 것이에요.", en: "This is mine.", form: "제 (my) + 것; 것 + 이에요 (이다 after a batchim, present, polite casual)" } },
    "또|adverb": { korean: "또", note: "Again, or 'also' when adding to a list. It marks a repeat of the same thing; 다시 is closer to 'once more, over again' and is preferred when redoing something properly.", example: { ko: "내일 또 만나요.", en: "See you again tomorrow.", form: "또 placed before the verb; 만나다 → 만나요 (present, polite casual)" } },
    "집|noun": { korean: "집", note: "A house or home, and the suffix for shops that serve food: 커피집, 고기집. 집에 가요 means going home; 우리 집 is the normal way to say 'my house'.", example: { ko: "우리 집이 커요.", en: "Our house is big.", form: "집 + 이 (subject particle); 크다 → 커요 (ㅡ drops before -어요; present, polite casual)" } },
    "되다|verb": { korean: "되다", note: "To become, or for something to work out. The thing you become takes 이/가, not 을/를: 의사가 되다 = to become a doctor. 안 돼요 is the everyday 'that will not do'.", example: { ko: "저는 선생님이 되고 싶어요.", en: "I want to become a teacher.", form: "선생님 + 이 (the complement takes 이/가); 되다 → 되고 싶어요 (-고 싶다, present, polite casual)" } },
    "안녕하세요|expression": { korean: "안녕하세요", note: "The all-purpose polite greeting, used at any hour and for both hello and, with a rising tone, 'how are you'. Answer it by repeating it. 안녕 alone is casual, for friends and children only.", example: { ko: "안녕하세요. 만나서 반가워요.", en: "Hello. Nice to meet you.", form: "Fixed expression, used whole; never conjugated further" } },
    "잘 모르겠어요|phrase": { korean: "잘 모르겠어요", note: "The polite way to say you do not know. The 겠 softens it — plain 몰라요 is blunt and can sound curt. 잘 ('well') makes it gentler still, closer to 'I am not quite sure'.", example: { ko: "죄송해요, 잘 모르겠어요.", en: "Sorry, I do not really know.", form: "모르다 + 겠 + 어요; fixed as a unit at this level" } },
    "사람|noun": { korean: "사람", note: "A person, and the plain counter for people (한 사람). Add it to a country to give nationality: 한국 사람 = a Korean person. 명 is the neutral counter and 분 the honorific one.", example: { ko: "저 사람은 제 친구예요.", en: "That person is my friend.", form: "사람 + 은 (topic particle after a batchim); 이다 → 예요 (after a vowel, present, polite casual)" } },
    "하다|verb": { korean: "하다", note: "To do — and the engine of hundreds of compound verbs, where it attaches to a noun: 공부하다, 일하다, 사랑하다. Its 여-irregular conjugation gives 해요, not 하아요.", example: { ko: "숙제를 해요.", en: "I do my homework.", form: "숙제 + 를 (object particle after a vowel); 하다 → 해요 (여-irregular, present, polite casual)" } },
    "하다|auxiliary verb": { korean: "하다", note: "-어야 하다 expresses obligation, 'must' or 'have to'. Attach -아야/어야 to the stem, then 하다: 가다 → 가야 해요. 되다 can replace 하다 with almost no change in meaning.", example: { ko: "지금 가야 해요.", en: "I have to go now.", form: "가다 → 가야 (obligation connector) + 하다 → 해요 (present, polite casual)" } },
    "보다|verb": { korean: "보다", note: "To see or watch, and the default verb for films, TV and books read casually. Also 'to meet' in 시험을 보다 (to sit an exam) and 맛을 보다 (to taste).", example: { ko: "저녁에 영화를 봐요.", en: "I watch a movie in the evening.", form: "영화 + 를 (object particle); 보다 → 봐요 (ㅗ + 아 contracts; present, polite casual)" } },
    "보다|auxiliary verb": { korean: "보다", note: "-어 보다 means to try doing something, in the sense of giving it a go. 먹어 보세요 = 'give it a taste'. It does not mean 'attempt and fail' — that is -려고 하다.", example: { ko: "한번 먹어 보세요.", en: "Try eating it once.", form: "먹다 → 먹어 (connector) + 보다 → 보세요 (polite request)" } },
    "보다|adverb": { korean: "보다", note: "'More' in comparisons, placed before the adjective: 보다 빠르게. It is bookish — in speech Koreans use 더 instead, and mark the compared thing with 보다 as a particle: 나보다 커요.", example: { ko: "이것이 보다 좋아요.", en: "This one is better.", form: "보다 placed directly before the adjective; 좋다 → 좋아요 (present, polite casual)" } },
    "가다|verb": { korean: "가다", note: "To go. The destination takes 에 (학교에 가요); the purpose takes -러 (밥 먹으러 가요). Korean picks 가다 or 오다 by where the speaker is, so 'I am coming' to where you are is 지금 가요, not 와요.", example: { ko: "학교에 가요.", en: "I go to school.", form: "학교 + 에 (destination particle); 가다 → 가요 (identical ㅏ merges; present, polite casual)" } },
    "가다|auxiliary verb": { korean: "가다", note: "-어 가다 means to keep doing something, with the action moving away from now into the future. Its mirror is -어 오다, which tracks it up to the present.", example: { ko: "일이 끝나 가요.", en: "The work is nearly finished.", form: "끝나다 → 끝나 (connector) + 가다 → 가요 (progressive-away, present, polite casual)" } },
    "이|numeral": { korean: "이", note: "Sino-Korean 'two', used for dates, money, phone numbers and minutes: 이월 (February), 이십 (twenty). Native 둘 is used for counting objects and ages.", example: { ko: "이월에 한국에 가요.", en: "I go to Korea in February.", form: "이 + 월 (Sino-Korean number before a Sino-Korean counter); 가다 → 가요" } },
    "이|noun": { korean: "이", note: "A tooth. 이가 아파요 is how you say you have toothache. The honorific is 치아, used in dental clinics.", example: { ko: "이가 아파요.", en: "My tooth hurts.", form: "이 + 가 (subject particle after a vowel); 아프다 → 아파요 (ㅡ drops; present, polite casual)" } },
    "이|pronoun": { korean: "이", note: "'This one', pointing at something near the speaker. In speech 이것 or 이거 is far more common; bare 이 as a pronoun is written and formal.", example: { ko: "이가 제 책이에요.", en: "This one is my book.", form: "이 + 가 (subject particle); 책 + 이에요 (이다 after a batchim)" } },
    "이|determiner": { korean: "이", note: "'This', placed directly in front of a noun: 이 책, 이 사람. The set is 이 (near me) / 그 (near you) / 저 (over there) — Korean splits 'that' two ways where English has one.", example: { ko: "이 책을 읽으세요.", en: "Please read this book.", form: "이 + noun (determiner, never takes a particle); 읽다 → 읽으세요 (polite request after a batchim)" } },
    "말하다|verb": { korean: "말하다", note: "To speak or to say. What is said takes 을/를 or the quotative -고: 저는 한국어를 말해요. For talking *with* someone use 이야기하다; for telling someone use 에게 말하다.", example: { ko: "천천히 말해 주세요.", en: "Please speak slowly.", form: "말하다 → 말해 (여-irregular connector) + 주다 → 주세요 (request for someone's benefit)" } },
    "오다|verb": { korean: "오다", note: "To come, toward where the speaker is. Also the verb for weather falling: 비가 와요, 눈이 와요 — never 떨어지다 for rain.", example: { ko: "비가 와요.", en: "It is raining.", form: "비 + 가 (subject particle); 오다 → 와요 (ㅗ + 아 contracts; present, polite casual)" } },
    "오다|auxiliary verb": { korean: "오다", note: "-어 오다 means an action has been going on up to now. 살아 왔어요 = 'I have lived (up to this point)'. Its mirror -어 가다 points forward instead.", example: { ko: "십 년 동안 한국어를 배워 왔어요.", en: "I have been learning Korean for ten years.", form: "배우다 → 배워 (connector) + 오다 → 왔어요 (past, polite casual)" } },
    "알다|verb": { korean: "알다", note: "To know. It is a ㄹ-irregular: the ㄹ drops before ㄴ, ㅂ and ㅅ, giving 압니다 and 아세요. Its negative is the separate verb 모르다, never 안 알다.", example: { ko: "그 사람을 알아요.", en: "I know that person.", form: "사람 + 을 (object particle); 알다 → 알아요 (present, polite casual)" } },

    // ================================================================= day 2
    "안|noun": { korean: "안", note: "The inside of something, used as noun + 안에: 가방 안에. Do not confuse it with the negation adverb 안, which sits before a verb — the position noun always follows another noun.", example: { ko: "가방 안에 책이 있어요.", en: "There is a book inside the bag.", form: "안 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "안|adverb": { korean: "안", note: "The short negation, placed immediately before the verb: 안 가요 = I do not go. With 하다 compounds it splits them — 공부 안 해요, not 안 공부해요. The long form -지 않다 means the same thing.", example: { ko: "저는 고기를 안 먹어요.", en: "I do not eat meat.", form: "안 placed before the verb; 먹다 → 먹어요 (present, polite casual)" } },
    "받다|verb": { korean: "받다", note: "To receive or get. The giver takes 에게/한테 (친구한테서 받다). It also carries 'to take' in fixed pairs: 전화를 받다 (answer a call), 스트레스를 받다 (get stressed).", example: { ko: "친구한테서 편지를 받았어요.", en: "I received a letter from a friend.", form: "친구 + 한테서 (source particle); 받다 → 받았어요 (past, polite casual)" } },
    "생각|noun": { korean: "생각", note: "A thought or an opinion. 생각하다 is to think; 생각이 나다 is 'it comes to mind'; 제 생각에는 is the standard opener for 'in my opinion'.", example: { ko: "제 생각에는 좋아요.", en: "In my opinion it is good.", form: "생각 + 에는 (에 + 는, topic-marked location); 좋다 → 좋아요" } },
    "안녕히 가세요|expression": { korean: "안녕히 가세요", note: "Goodbye said to the person who is leaving, while you stay. Its pair 안녕히 계세요 is said by the one leaving to the one staying. Getting them backwards is the classic beginner slip.", example: { ko: "안녕히 가세요. 내일 봬요.", en: "Goodbye. See you tomorrow.", form: "Fixed expression; 가다 + 세요 already carries the polite request form" } },
    "안녕히 계세요|expression": { korean: "안녕히 계세요", note: "Goodbye said by the person leaving to whoever is staying behind. If you are both walking out, use 안녕히 가세요 to each other.", example: { ko: "먼저 갈게요. 안녕히 계세요.", en: "I will go first. Goodbye.", form: "Fixed expression; 계시다 (honorific 있다) + 세요" } },
    "나오다|verb": { korean: "나오다", note: "To come out, toward the speaker. The place you exit takes 에서: 집에서 나와요. Also used for things appearing — 책이 나왔어요 (the book came out).", example: { ko: "집에서 나왔어요.", en: "I came out of the house.", form: "집 + 에서 (source particle); 나오다 → 나왔어요 (past, polite casual)" } },
    "살다|verb": { korean: "살다", note: "To live, both 'be alive' and 'reside'. Where you live takes 에 or 에서: 서울에 살아요. It is a ㄹ-irregular, giving 삽니다 and 사세요.", example: { ko: "서울에 살아요.", en: "I live in Seoul.", form: "서울 + 에 (location particle); 살다 → 살아요 (present, polite casual)" } },
    "을|particle": { korean: "을", note: "The object marker after a consonant; 를 after a vowel. Note that some Korean verbs take 을/를 where English uses no object at all, and vice versa — 만나다 takes 을/를 (친구를 만나요), not 에게.", example: { ko: "밥을 먹어요.", en: "I eat rice.", form: "밥 ends in a batchim so it takes 을; a vowel noun takes 를: 커피를" } },
    "모르다|verb": { korean: "모르다", note: "To not know — a separate word, not a negation of 알다. It is 르-irregular: 모르 + 아요 gives 몰라요, with the ㄹ doubling. 잘 모르겠어요 is the polite hedge.", example: { ko: "이름을 몰라요.", en: "I do not know the name.", form: "이름 + 을 (object particle); 모르다 → 몰라요 (르-irregular, present, polite casual)" } },
    "만들다|verb": { korean: "만들다", note: "To make. ㄹ-irregular, so the ㄹ drops before ㅂ and ㅅ: 만듭니다, 만드세요. What you make takes 을/를.", example: { ko: "김치를 만들어요.", en: "I make kimchi.", form: "김치 + 를 (object particle); 만들다 → 만들어요 (present, polite casual)" } },
    "먹다|verb": { korean: "먹다", note: "To eat. Its honorific is the separate verb 드시다 or 잡수시다, used when the eater deserves respect. 나이를 먹다 means to grow older.", example: { ko: "아침을 먹었어요.", en: "I ate breakfast.", form: "아침 + 을 (object particle); 먹다 → 먹었어요 (past, polite casual)" } },
    "먹다|auxiliary verb": { korean: "먹다", note: "-어 먹다 adds a blunt, informal 'to oneself' colouring to an action, often something reckless or complete: 잊어 먹었어요 = 'I clean forgot'. Avoid it in polite writing.", example: { ko: "약속을 잊어 먹었어요.", en: "I completely forgot the appointment.", form: "잊다 → 잊어 (connector) + 먹다 → 먹었어요 (past, polite casual)" } },
    "듣다|verb": { korean: "듣다", note: "To listen or hear. ㄷ-irregular: the ㄷ becomes ㄹ before a vowel, giving 들어요 and 들었어요. 수업을 듣다 is 'to take a class'.", example: { ko: "음악을 들어요.", en: "I listen to music.", form: "음악 + 을 (object particle); 듣다 → 들어요 (ㄷ-irregular, present, polite casual)" } },
    "감사합니다|expression": { korean: "감사합니다", note: "Thank you, formal. 고맙습니다 is equally polite but feels warmer and more native; 감사합니다 is the safer default with strangers, in shops and in writing.", example: { ko: "도와주셔서 감사합니다.", en: "Thank you for helping me.", form: "Fixed expression; 감사하다 → 합니다 (present, formal polite)" } },
    "고맙습니다|expression": { korean: "고맙습니다", note: "Thank you. Native-Korean in origin where 감사합니다 is Sino-Korean, and slightly warmer. The casual form is 고마워 (ㅂ-irregular), used with friends only.", example: { ko: "정말 고맙습니다.", en: "Thank you very much.", form: "Fixed expression; 고맙다 → 습니다 (ㅂ-irregular stem, present, formal polite)" } },
    "들다|verb": { korean: "들다", note: "To lift or hold in the hand, and the verb in many set phrases: 돈이 들다 (to cost), 마음에 들다 (to like), 감기가 들다 (to catch a cold). ㄹ-irregular.", example: { ko: "가방을 들었어요.", en: "I picked up the bag.", form: "가방 + 을 (object particle); 들다 → 들었어요 (past, polite casual)" } },
    "가지다|verb": { korean: "가지다", note: "To have or to hold, usually of something you carry or possess actively. For plain possession Koreans prefer 있다: 차가 있어요 rather than 차를 가지고 있어요. Contracts to 갖다 in speech.", example: { ko: "우산을 가지고 오세요.", en: "Please bring an umbrella.", form: "가지다 → 가지고 (connector) + 오다 → 오세요 (polite request)" } },
    "가지다|auxiliary verb": { korean: "가지다", note: "-어 가지고 links two actions where the first sets up the second, roughly 'having done X, then Y'. Very common in speech, often shortened to -어 갖고. In writing -어서 is preferred.", example: { ko: "돈을 모아 가지고 여행을 갔어요.", en: "I saved money and then went travelling.", form: "모으다 → 모아 (connector) + 가지고; 가다 → 갔어요 (past, polite casual)" } },
    "주다|verb": { korean: "주다", note: "To give. The recipient takes 에게/한테. When the receiver deserves respect, switch to the separate verb 드리다 — 선생님께 드려요, never 선생님께 줘요.", example: { ko: "친구에게 선물을 줬어요.", en: "I gave my friend a present.", form: "친구 + 에게 (recipient particle); 주다 → 줬어요 (past, polite casual)" } },
    "주다|auxiliary verb": { korean: "주다", note: "-어 주다 means doing something for someone's benefit, and it is what makes a request polite: 도와주세요 = please help me. Without it, 도우세요 sounds like an order.", example: { ko: "사진을 찍어 주세요.", en: "Please take a photo for me.", form: "찍다 → 찍어 (connector) + 주다 → 주세요 (polite request)" } },
    "시간|noun": { korean: "시간", note: "Time in general, and also 'an hour' when counted: 세 시간 (three hours). Careful — 시 is the clock hour (세 시 = three o'clock), so 세 시간 and 세 시 mean different things.", example: { ko: "시간이 없어요.", en: "I do not have time.", form: "시간 + 이 (subject particle); 없다 → 없어요 (present, polite casual)" } },
    "시간|dependent noun": { korean: "시간", note: "The counter for hours of duration, following a native Korean number: 한 시간, 두 시간. Contrast 시, the counter for clock hours: 한 시 = one o'clock.", example: { ko: "두 시간 기다렸어요.", en: "I waited for two hours.", form: "두 (native number before a counter) + 시간; 기다리다 → 기다렸어요 (past)" } },
    "많다|adjective": { korean: "많다", note: "To be many or much. As a descriptive verb it ends the sentence itself — 사람이 많아요, with no 이다. Before a noun it becomes 많은: 많은 사람.", example: { ko: "사람이 많아요.", en: "There are a lot of people.", form: "사람 + 이 (subject particle); 많다 → 많아요 (present, polite casual)" } },
    "좋다|adjective": { korean: "좋다", note: "To be good. It describes a thing: 날씨가 좋아요. To say *you* like something use 좋아하다 with 을/를 instead — 저는 커피를 좋아해요, not 커피가 좋아해요.", example: { ko: "날씨가 좋아요.", en: "The weather is good.", form: "날씨 + 가 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "제|pronoun": { korean: "제", note: "'My', the humble form of 내. Use 제 with anyone you would use 저 with. 제 이름, 제 친구. 저의 is the full form but 제 is what people actually say.", example: { ko: "제 이름은 민수예요.", en: "My name is Minsu.", form: "제 + noun (determiner); 이름 + 은 (topic particle after a batchim)" } },
    "죄송합니다|expression": { korean: "죄송합니다", note: "I am sorry, formal and more deferential than 미안합니다. Use it with strangers, customers and elders. For bumping into someone in passing, 실례합니다 (excuse me) fits better.", example: { ko: "늦어서 죄송합니다.", en: "I am sorry for being late.", form: "Fixed expression; 죄송하다 → 합니다 (present, formal polite)" } },

    // ================================================================= day 3
    "앞|noun": { korean: "앞", note: "The front or the space in front, used as noun + 앞에: 학교 앞에서 만나요. It also means 'ahead' in time — 앞으로 = from now on.", example: { ko: "집 앞에 차가 있어요.", en: "There is a car in front of the house.", form: "앞 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "뒤|noun": { korean: "뒤", note: "The back or the space behind, as noun + 뒤에. In time it means 'after': 수업 뒤에. 후 is the more formal alternative for the time sense.", example: { ko: "건물 뒤에 주차장이 있어요.", en: "There is a car park behind the building.", form: "뒤 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "속|noun": { korean: "속", note: "The inside, overlapping with 안 but pointing at the interior of a mass or a body rather than an enclosure: 물속, 마음속. For a bag or a room, 안 is the natural choice.", example: { ko: "가방 속에 무엇이 있어요?", en: "What is inside the bag?", form: "속 + 에 (location particle); 있다 → 있어요 (present, polite casual, question)" } },
    "위|noun": { korean: "위", note: "The top or the space above, as noun + 위에. It covers both 'on' (책상 위에 = on the desk) and 'above', which English separates.", example: { ko: "책상 위에 컴퓨터가 있어요.", en: "There is a computer on the desk.", form: "위 + 에 (location particle); 있다 → 있어요 (present, polite casual)" } },
    "여자|noun": { korean: "여자", note: "A woman or a girl. 여자 친구 with a space is a female friend; 여자친구 as one word is a girlfriend, and the difference matters. The polite alternative for an adult is 여성.", example: { ko: "저 여자는 제 누나예요.", en: "That woman is my older sister.", form: "여자 + 는 (topic particle after a vowel); 이다 → 예요 (present, polite casual)" } },
    "남자|noun": { korean: "남자", note: "A man or a boy. As with 여자, 남자 친구 (spaced) is a male friend while 남자친구 is a boyfriend. 남성 is the formal register.", example: { ko: "그 남자를 알아요?", en: "Do you know that man?", form: "남자 + 를 (object particle); 알다 → 알아요 (present, polite casual, question)" } },
    "아이|noun": { korean: "아이", note: "A child. Contracts to 애 in speech. 어린이 is the formal word used on signs and in institutions; 아기 is a baby specifically.", example: { ko: "아이가 자고 있어요.", en: "The child is sleeping.", form: "아이 + 가 (subject particle); 자다 → 자고 있어요 (progressive, present, polite casual)" } },
    "문제|noun": { korean: "문제", note: "Both a problem and an exam question — 문제가 있어요 is 'there is a problem', while 문제를 풀다 is 'to solve a question'. Context separates them cleanly.", example: { ko: "문제가 어려워요.", en: "The question is difficult.", form: "문제 + 가 (subject particle); 어렵다 → 어려워요 (ㅂ-irregular, present, polite casual)" } },
    "다음|noun": { korean: "다음", note: "The next one or what follows: 다음 주, 다음에. 다음에 봐요 is the standard 'see you next time'. As a determiner it needs no particle before the noun.", example: { ko: "다음 주에 만나요.", en: "Let's meet next week.", form: "다음 + noun, then 주 + 에 (time particle); 만나다 → 만나요 (suggestion, polite casual)" } },
    "전|noun": { korean: "전", note: "Before, in time: 삼 년 전 (three years ago), 전에 (previously). It follows the amount of time, where English puts 'ago' after too but 'before' in front.", example: { ko: "삼 년 전에 한국에 왔어요.", en: "I came to Korea three years ago.", form: "삼 년 + 전 + 에 (time particle); 오다 → 왔어요 (past, polite casual)" } },
    "후|noun": { korean: "후", note: "After, in time, following a duration: 한 시간 후에. Its native-Korean equivalent is 뒤에, and the two are interchangeable for time.", example: { ko: "한 시간 후에 갈게요.", en: "I will go in an hour.", form: "한 시간 + 후 + 에 (time particle); 가다 → 갈게요 (intention, polite casual)" } },
    "곳|noun": { korean: "곳", note: "A place, used after a modifier: 좋은 곳, 이곳. It is more written than 데, which fills the same slot in speech.", example: { ko: "여기는 좋은 곳이에요.", en: "This is a good place.", form: "좋다 → 좋은 (adjective modifier) + 곳; 곳 + 이에요 (이다 after a batchim)" } },
    "학교|noun": { korean: "학교", note: "A school of any level. Going there takes 에 (학교에 가요); doing something there takes 에서 (학교에서 공부해요). Getting those two backwards is a very common error.", example: { ko: "학교에서 한국어를 배워요.", en: "I learn Korean at school.", form: "학교 + 에서 (action-location particle); 배우다 → 배워요 (present, polite casual)" } },
    "날|noun": { korean: "날", note: "A day as an occasion — 생일날, 그날. For counting days use 일 (삼 일) and for a date use 날짜. 하루 is 'one day' as a duration.", example: { ko: "그날 비가 왔어요.", en: "It rained that day.", form: "그 (determiner) + 날; 오다 → 왔어요 (past, polite casual)" } },
    "돈|noun": { korean: "돈", note: "Money. It costs with 들다 (돈이 들어요) and you spend it with 쓰다 (돈을 써요). 돈이 많다 is 'to be rich' in everyday speech.", example: { ko: "돈이 없어요.", en: "I have no money.", form: "돈 + 이 (subject particle); 없다 → 없어요 (present, polite casual)" } },
    "친구|noun": { korean: "친구", note: "A friend, normally someone of about your own age — Korean rarely calls an older person 친구. Meeting one takes 을/를, not 에게: 친구를 만나요.", example: { ko: "친구를 만났어요.", en: "I met a friend.", form: "친구 + 를 (object particle); 만나다 → 만났어요 (past, polite casual)" } },
    "운동|noun": { korean: "운동", note: "Exercise or sport in general. The verb is 운동하다. For a specific sport, name it instead: 축구를 해요, not 운동을 해요.", example: { ko: "매일 운동을 해요.", en: "I exercise every day.", form: "운동 + 을 (object particle); 하다 → 해요 (present, polite casual)" } },
    "마음|noun": { korean: "마음", note: "The heart or mind as the seat of feeling and intention — not the organ, which is 심장. 마음에 들다 means to like something; 마음이 아프다 is heartache.", example: { ko: "이 옷이 마음에 들어요.", en: "I like these clothes.", form: "마음 + 에 (location particle in a fixed phrase); 들다 → 들어요 (present, polite casual)" } },
    "이|particle": { korean: "이/가", note: "The subject marker: 이 after a consonant, 가 after a vowel. It introduces new information, where 은/는 marks something already under discussion. Answers to 누가? always take 이/가.", example: { ko: "친구가 왔어요.", en: "A friend came.", form: "친구 ends in a vowel so it takes 가; a batchim noun takes 이: 선생님이" } },
    "에|particle": { korean: "에", note: "Marks a destination (학교에 가요), a static location with 있다/없다 (집에 있어요), and a point in time (세 시에). It does not mark where an action happens — that is 에서.", example: { ko: "일곱 시에 일어나요.", en: "I get up at seven o'clock.", form: "일곱 시 + 에 (time particle); 일어나다 → 일어나요 (present, polite casual)" } },
    "에서|particle": { korean: "에서", note: "Marks where an action takes place (식당에서 먹어요) and where movement starts (집에서 왔어요). With 있다 you must use 에 instead, never 에서.", example: { ko: "도서관에서 공부해요.", en: "I study at the library.", form: "도서관 + 에서 (action-location particle); 공부하다 → 공부해요 (present, polite casual)" } },
    "시작하다|verb": { korean: "시작하다", note: "To start something, taking an object: 수업을 시작해요. When the thing starts by itself, use the paired intransitive 시작되다: 수업이 시작돼요.", example: { ko: "지금 시작할까요?", en: "Shall we start now?", form: "시작하다 → 시작할까요 (suggestion, polite casual, question)" } },
    "만나다|verb": { korean: "만나다", note: "To meet. The person met takes 을/를, not 에게 — 친구를 만나요. With 와/과 it means meeting each other: 친구와 만나요.", example: { ko: "내일 친구를 만나요.", en: "I am meeting a friend tomorrow.", form: "친구 + 를 (object particle); 만나다 → 만나요 (identical ㅏ merges; present, polite casual)" } },
    "쓰다|verb": { korean: "쓰다", note: "Four verbs share this shape: to write, to use, to wear on the head, and to be bitter. All are ㅡ-irregular — 써요. Context decides, and the object usually makes it obvious.", example: { ko: "편지를 써요.", en: "I write a letter.", form: "편지 + 를 (object particle); 쓰다 → 써요 (ㅡ drops before -어요; present, polite casual)" } },
    "찾다|verb": { korean: "찾다", note: "To look for, and also to find — Korean does not split them. 은행에서 돈을 찾다 means to withdraw money, a fixed sense worth memorising.", example: { ko: "열쇠를 찾고 있어요.", en: "I am looking for my key.", form: "열쇠 + 를 (object particle); 찾다 → 찾고 있어요 (progressive, present, polite casual)" } },
    "사다|verb": { korean: "사다", note: "To buy. What you buy takes 을/를 and the shop takes 에서: 시장에서 과일을 샀어요. Its opposite is 팔다.", example: { ko: "시장에서 과일을 샀어요.", en: "I bought fruit at the market.", form: "시장 + 에서 (action-location); 사다 → 샀어요 (past, polite casual)" } },

    // ================================================================= day 4
    "생활|noun": { korean: "생활", note: "Daily life as it is lived — 학교 생활, 한국 생활. It is not 'a life' in the biographical sense, which is 인생, nor the state of being alive, which is 삶.", example: { ko: "한국 생활이 재미있어요.", en: "Life in Korea is fun.", form: "생활 + 이 (subject particle); 재미있다 → 재미있어요 (present, polite casual)" } },
    "길|noun": { korean: "길", note: "A road or a way, and also 'the way there': 길을 잃다 (to get lost), 길을 묻다 (to ask directions). 길이 막히다 is the standard phrase for traffic.", example: { ko: "길을 잃어버렸어요.", en: "I got lost.", form: "길 + 을 (object particle); 잃어버리다 → 잃어버렸어요 (past, polite casual)" } },
    "얼굴|noun": { korean: "얼굴", note: "The face. Washing it is 세수하다, a specific verb — 얼굴을 씻다 is understandable but unidiomatic.", example: { ko: "얼굴이 빨개졌어요.", en: "My face turned red.", form: "얼굴 + 이 (subject particle); 빨개지다 → 빨개졌어요 (past, polite casual)" } },
    "몸|noun": { korean: "몸", note: "The body. 몸이 안 좋다 is the everyday way to say you feel unwell, and 몸조심하세요 is 'take care of yourself'.", example: { ko: "오늘 몸이 안 좋아요.", en: "I do not feel well today.", form: "몸 + 이 (subject particle); 안 + 좋다 → 안 좋아요 (negated, present, polite casual)" } },
    "물|noun": { korean: "물", note: "Water. Uncountable, so count it by container: 물 한 잔, 물 한 병. 물을 주다 is also 'to water' a plant.", example: { ko: "물 한 잔 주세요.", en: "Please give me a glass of water.", form: "물 한 잔 (noun + native number + counter); 주다 → 주세요 (polite request)" } },
    "이번|noun": { korean: "이번", note: "This time round: 이번 주, 이번 달, 이번에. The set runs 지난 (last) / 이번 (this) / 다음 (next), and none of them take a particle before the noun.", example: { ko: "이번 주에 시험이 있어요.", en: "There is an exam this week.", form: "이번 + 주 + 에 (time particle); 있다 → 있어요 (present, polite casual)" } },
    "지금|adverb": { korean: "지금", note: "Now, at this moment. 이제 is close but carries 'from now on, as opposed to before' — 이제 알겠어요 means 'now I finally understand'.", example: { ko: "지금 어디에 있어요?", en: "Where are you now?", form: "지금 placed early in the sentence; 있다 → 있어요 (present, polite casual, question)" } },
    "지금|noun": { korean: "지금", note: "The present moment used as a noun, so it can take particles: 지금까지 (until now), 지금부터 (from now).", example: { ko: "지금부터 시작해요.", en: "Let's start from now.", form: "지금 + 부터 (starting-point particle); 시작하다 → 시작해요" } },
    "손|noun": { korean: "손", note: "The hand. Washing them is 손을 씻다. 손님 (guest) is a separate word despite the shape.", example: { ko: "손을 씻으세요.", en: "Please wash your hands.", form: "손 + 을 (object particle); 씻다 → 씻으세요 (polite request after a batchim)" } },
    "처음|noun": { korean: "처음", note: "The beginning or the first time. 처음 뵙겠습니다 is the set phrase on first meeting someone; 처음에는 means 'at first'.", example: { ko: "처음 뵙겠습니다.", en: "How do you do. (I am meeting you for the first time.)", form: "Fixed greeting; 뵙다 (humble 보다) → 뵙겠습니다 (formal polite)" } },
    "선생님|noun": { korean: "선생님", note: "Teacher, and the default respectful way to address any professional. The 님 is an honorific suffix, so 선생님이 takes the honorific particle 께서 in formal speech.", example: { ko: "선생님께서 오셨어요.", en: "The teacher has arrived.", form: "선생님 + 께서 (honorific subject particle); 오다 → 오셨어요 (honorific past, polite casual)" } },
    "책|noun": { korean: "책", note: "A book, counted with 권 (책 세 권). Read it with 읽다, though 보다 is also natural and a shade more casual.", example: { ko: "책을 세 권 샀어요.", en: "I bought three books.", form: "책 + 을 (object particle); 세 권 (native number + counter); 사다 → 샀어요 (past)" } },
    "이야기|noun": { korean: "이야기", note: "A story or a talk. 이야기하다 is to chat or to tell. It contracts to 얘기 in speech, which is a separate entry in this bank.", example: { ko: "재미있는 이야기예요.", en: "It is an interesting story.", form: "재미있다 → 재미있는 (present modifier) + 이야기; 이다 → 예요" } },
    "시장|noun": { korean: "시장", note: "A traditional market. A supermarket is 마트 and a department store is 백화점, so 시장 specifically signals the open-air or covered kind.", example: { ko: "시장에서 과일을 사요.", en: "I buy fruit at the market.", form: "시장 + 에서 (action-location particle); 사다 → 사요 (present, polite casual)" } },
    "역사|noun": { korean: "역사", note: "History as a subject or a record. 역사가 있다 means something is long-established. The person is 역사가 or 역사학자.", example: { ko: "한국 역사를 공부해요.", en: "I study Korean history.", form: "역사 + 를 (object particle); 공부하다 → 공부해요 (present, polite casual)" } },
    "동안|noun": { korean: "동안", note: "For a duration, following the amount of time: 세 시간 동안, 방학 동안. It never starts a phrase — the time always comes first.", example: { ko: "두 시간 동안 기다렸어요.", en: "I waited for two hours.", form: "두 시간 + 동안 (duration); 기다리다 → 기다렸어요 (past, polite casual)" } },
    "힘|noun": { korean: "힘", note: "Strength or energy. 힘이 없다 is 'to feel weak or drained'; 힘내세요 is the standard 'cheer up, hang in there'.", example: { ko: "힘내세요!", en: "Cheer up!", form: "힘 + 내다 → 내세요 (polite request, used as a fixed encouragement)" } },
    "나라|noun": { korean: "나라", note: "A country. 우리나라 written as one word means 'my country, Korea' when a Korean says it, so it is not a neutral 'our country'.", example: { ko: "어느 나라에서 왔어요?", en: "Which country are you from?", form: "어느 (determiner) + 나라 + 에서 (source particle); 오다 → 왔어요 (past, question)" } },
    "학생|noun": { korean: "학생", note: "A student at any level. 대학생 is a university student, 중학생 a middle schooler. 학생 is also how a teacher addresses a pupil directly.", example: { ko: "저는 대학생이에요.", en: "I am a university student.", form: "대학생 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "이름|noun": { korean: "이름", note: "A name. The honorific is 성함, used when asking an elder or a customer: 성함이 어떻게 되세요? Asking 이름이 뭐예요? is fine among peers.", example: { ko: "이름이 뭐예요?", en: "What is your name?", form: "이름 + 이 (subject particle); 뭐 + 예요 (이다 after a vowel, question)" } },
    "밤|noun": { korean: "밤", note: "Night. The identical 밤 meaning chestnut is distinguished only by vowel length in careful speech, and by context otherwise.", example: { ko: "밤에 잠이 안 와요.", en: "I cannot sleep at night.", form: "밤 + 에 (time particle); 잠 + 이 (subject); 오다 → 안 와요 (negated present)" } },
    "아침|noun": { korean: "아침", note: "Both the morning and breakfast — 아침을 먹다 is 'to eat breakfast', 아침에 is 'in the morning'. 점심 and 저녁 work the same way.", example: { ko: "아침에 커피를 마셔요.", en: "I drink coffee in the morning.", form: "아침 + 에 (time particle); 마시다 → 마셔요 (present, polite casual)" } },
    "방|noun": { korean: "방", note: "A room in a home, and the second half of many compounds: 노래방, 찜질방. A classroom is 교실, not 방.", example: { ko: "제 방은 작아요.", en: "My room is small.", form: "방 + 은 (topic particle); 작다 → 작아요 (present, polite casual)" } },
    "앉다|verb": { korean: "앉다", note: "To sit down. The place takes 에: 의자에 앉으세요. For 'to be seated' as a state, use 앉아 있다.", example: { ko: "여기에 앉으세요.", en: "Please sit here.", form: "여기 + 에 (location particle); 앉다 → 앉으세요 (polite request after a batchim)" } },
    "서다|verb": { korean: "서다", note: "To stand, and also for a vehicle to stop: 버스가 섰어요. To be standing is 서 있다.", example: { ko: "버스가 섰어요.", en: "The bus stopped.", form: "버스 + 가 (subject particle); 서다 → 섰어요 (past, polite casual)" } },
    "읽다|verb": { korean: "읽다", note: "To read. The ㄺ cluster keeps only ㄱ before a consonant, so it is pronounced [익따] but [일거요] before a vowel.", example: { ko: "신문을 읽어요.", en: "I read the newspaper.", form: "신문 + 을 (object particle); 읽다 → 읽어요 (present, polite casual)" } },
    "잡다|verb": { korean: "잡다", note: "To catch or grab, and to book something: 자리를 잡다 (to get a seat), 택시를 잡다 (to hail a taxi).", example: { ko: "택시를 잡았어요.", en: "I caught a taxi.", form: "택시 + 를 (object particle); 잡다 → 잡았어요 (past, polite casual)" } },

    // ================================================================= day 5
    "얼마나|adverb": { korean: "얼마나", note: "How much or how long, before an adjective or a quantity: 얼마나 걸려요? (how long does it take?). For a price use 얼마 alone: 얼마예요?", example: { ko: "여기서 얼마나 걸려요?", en: "How long does it take from here?", form: "얼마나 before the verb; 걸리다 → 걸려요 (present, polite casual, question)" } },
    "얼마|noun": { korean: "얼마", note: "How much, chiefly of price: 이거 얼마예요? is the phrase you will use in every shop. For duration or degree, 얼마나 is the right word.", example: { ko: "이거 얼마예요?", en: "How much is this?", form: "얼마 + 예요 (이다 after a vowel; present, polite casual, question)" } },
    "잘|adverb": { korean: "잘", note: "Well, or skilfully: 한국어를 잘해요. It also softens a statement — 잘 모르겠어요 is gentler than 몰라요. Its opposite is 못.", example: { ko: "한국어를 잘해요.", en: "You speak Korean well.", form: "잘 + 하다 → 잘해요 (written as one word in this fixed sense)" } },
    "못|adverb": { korean: "못", note: "Cannot, placed before the verb — it marks inability, where 안 marks choice. 못 가요 is 'I am unable to go'; 안 가요 is 'I am not going'. With 하다 compounds it splits them: 공부 못 해요.", example: { ko: "오늘은 못 가요.", en: "I cannot go today.", form: "못 placed before the verb; 가다 → 가요 (present, polite casual)" } },
    "더|adverb": { korean: "더", note: "More, before an adjective or verb: 더 크다, 더 주세요. The thing compared against takes the particle 보다 — 저보다 더 커요.", example: { ko: "조금 더 주세요.", en: "Please give me a little more.", form: "더 before the verb; 주다 → 주세요 (polite request)" } },
    "가장|adverb": { korean: "가장", note: "Most, forming the superlative: 가장 큰 도시. 제일 means the same and is more common in speech; 가장 is the written register.", example: { ko: "이것이 가장 좋아요.", en: "This one is the best.", form: "가장 before the adjective; 좋다 → 좋아요 (present, polite casual)" } },
    "다시|adverb": { korean: "다시", note: "Again, in the sense of doing it over. 또 is 'again' as a repeat occurrence, so 다시 말해 주세요 (say it again properly) differs from 또 왔어요 (came again).", example: { ko: "다시 말해 주세요.", en: "Please say that again.", form: "다시 before the verb; 말하다 → 말해 + 주다 → 주세요 (request)" } },
    "많이|adverb": { korean: "많이", note: "A lot, the adverb formed from 많다. It modifies the verb — 많이 먹었어요 — where 많다 describes a noun: 사람이 많아요.", example: { ko: "많이 드세요.", en: "Please eat a lot.", form: "많이 before the verb; 드시다 (honorific 먹다) → 드세요 (polite request)" } },
    "좀|adverb": { korean: "좀", note: "A little, contracted from 조금 — but its real work is softening a request. 좀 도와주세요 is far more natural than the bare 도와주세요.", example: { ko: "좀 도와주세요.", en: "Please help me a little.", form: "좀 before the verb; 돕다 → 도와 (ㅂ-irregular) + 주다 → 주세요" } },
    "함께|adverb": { korean: "함께", note: "Together, with a slightly formal or written feel. 같이 means the same and is what people say aloud. Both pair with 와/과 or 하고.", example: { ko: "친구와 함께 갔어요.", en: "I went together with a friend.", form: "친구 + 와 (with, after a vowel) + 함께; 가다 → 갔어요 (past)" } },
    "같이|adverb": { korean: "같이", note: "Together, the everyday spoken form. Pronounced [가치], not [가티] — the ㅌ palatalises before 이. Also means 'like' after a noun: 저같이.", example: { ko: "같이 갈까요?", en: "Shall we go together?", form: "같이 before the verb; 가다 → 갈까요 (suggestion, polite casual, question)" } },
    "왜|adverb": { korean: "왜", note: "Why. The answer normally uses -어서 or 왜냐하면. On its own with rising tone, 왜요? means 'why do you ask?'.", example: { ko: "왜 안 왔어요?", en: "Why did you not come?", form: "왜 opens the question; 안 + 오다 → 안 왔어요 (negated past, polite casual)" } },
    "아직|adverb": { korean: "아직", note: "Still, or 'not yet' with a negative: 아직 안 왔어요. With a positive verb it means the state continues: 아직 있어요.", example: { ko: "아직 안 끝났어요.", en: "It is not finished yet.", form: "아직 + 안 + 끝나다 → 안 끝났어요 (negated past, polite casual)" } },
    "물론|adverb": { korean: "물론", note: "Of course. Usually stands alone as an answer, or opens a sentence: 물론이에요. It concedes a point rather than expressing enthusiasm.", example: { ko: "물론이에요.", en: "Of course.", form: "물론 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "너무|adverb": { korean: "너무", note: "Too, excessively — though in casual speech it has drifted to simply mean 'very'. 너무 좋아요 is now a compliment, not a complaint. 아주 is the neutral 'very'.", example: { ko: "너무 비싸요.", en: "It is too expensive.", form: "너무 before the adjective; 비싸다 → 비싸요 (present, polite casual)" } },
    "아주|adverb": { korean: "아주", note: "Very, neutral and safe in any register. Unlike 너무 it carries no sense of excess, so it is the better choice in writing.", example: { ko: "아주 맛있어요.", en: "It is very delicious.", form: "아주 before the adjective; 맛있다 → 맛있어요 (present, polite casual)" } },
    "먼저|adverb": { korean: "먼저", note: "First, before others. 먼저 갈게요 is the polite way to excuse yourself from a group. 처음 is 'for the first time', a different idea.", example: { ko: "먼저 갈게요.", en: "I will go first.", form: "먼저 before the verb; 가다 → 갈게요 (intention, polite casual)" } },
    "곧|adverb": { korean: "곧", note: "Soon, shortly. It points at the near future and pairs with a future or present-tense verb: 곧 가요, 곧 도착해요.", example: { ko: "곧 도착해요.", en: "I will arrive soon.", form: "곧 before the verb; 도착하다 → 도착해요 (present used for near future)" } },
    "정말|adverb": { korean: "정말", note: "Really, truly. Also stands alone as 정말요? ('really?'). 진짜 is its casual twin and is more common among friends.", example: { ko: "정말 고맙습니다.", en: "Thank you very much indeed.", form: "정말 before the expression; 고맙다 → 고맙습니다 (formal polite)" } },
    "매우|adverb": { korean: "매우", note: "Very — but distinctly written and formal. In speech Koreans say 아주 or 정말; 매우 appears in essays, news and textbooks.", example: { ko: "매우 중요한 문제입니다.", en: "It is a very important issue.", form: "매우 + 중요하다 → 중요한 (adjective modifier) + 문제; 이다 → 입니다 (formal polite)" } },
    "꼭|adverb": { korean: "꼭", note: "Certainly, without fail. It strengthens a promise or a request: 꼭 오세요. It also means 'tightly' in a physical sense.", example: { ko: "내일 꼭 오세요.", en: "Please be sure to come tomorrow.", form: "꼭 before the verb; 오다 → 오세요 (polite request)" } },
    "계속|adverb": { korean: "계속", note: "Continuously, keeping on. It works as an adverb (계속 공부해요) and as a noun with 하다 (계속하다 = to continue).", example: { ko: "비가 계속 와요.", en: "It keeps raining.", form: "계속 before the verb; 오다 → 와요 (present, polite casual)" } },
    "갑자기|adverb": { korean: "갑자기", note: "Suddenly, all at once. It usually opens the clause and pairs with a past-tense verb.", example: { ko: "갑자기 비가 왔어요.", en: "It suddenly started raining.", form: "갑자기 opens the clause; 오다 → 왔어요 (past, polite casual)" } },
    "빨리|adverb": { korean: "빨리", note: "Quickly, the adverb from 빠르다. 빨리빨리 doubled is a cultural catchphrase for hurrying. As a command it can sound brusque, so add 좀.", example: { ko: "빨리 오세요.", en: "Please come quickly.", form: "빨리 before the verb; 오다 → 오세요 (polite request)" } },
    "천천히|adverb": { korean: "천천히", note: "Slowly, the adverb from 천천하다. 천천히 말해 주세요 is the single most useful sentence for a learner.", example: { ko: "천천히 말해 주세요.", en: "Please speak slowly.", form: "천천히 before the verb; 말하다 → 말해 + 주다 → 주세요 (request)" } },
    "자주|adverb": { korean: "자주", note: "Often, frequently. 가끔 is 'sometimes' and 항상 is 'always', giving a clean frequency ladder: 항상 > 자주 > 가끔.", example: { ko: "자주 만나요.", en: "We meet often.", form: "자주 before the verb; 만나다 → 만나요 (present, polite casual)" } },
    "벌써|adverb": { korean: "벌써", note: "Already, with a note of surprise that it happened so soon. 이미 states the same fact neutrally, without the surprise.", example: { ko: "벌써 도착했어요?", en: "You have arrived already?", form: "벌써 before the verb; 도착하다 → 도착했어요 (past, polite casual, question)" } },
    "아마|adverb": { korean: "아마", note: "Probably. It normally pairs with a guessing ending such as -을 거예요 or -겠- rather than a plain statement.", example: { ko: "아마 내일 올 거예요.", en: "He will probably come tomorrow.", form: "아마 + 오다 → 올 거예요 (supposition, polite casual)" } },
    "항상|adverb": { korean: "항상", note: "Always. 언제나 is a close synonym with a slightly warmer, more literary feel; both sit before the verb.", example: { ko: "항상 아침을 먹어요.", en: "I always eat breakfast.", form: "항상 before the verb; 먹다 → 먹어요 (present, polite casual)" } },
    "가끔|adverb": { korean: "가끔", note: "Sometimes, now and then. Lower on the frequency ladder than 자주. Often doubled as 가끔씩 with no change in meaning.", example: { ko: "가끔 영화를 봐요.", en: "I sometimes watch movies.", form: "가끔 before the verb; 보다 → 봐요 (present, polite casual)" } },
    "일찍|adverb": { korean: "일찍", note: "Early, of timing. Do not use it for 'early' in a sequence — that is 먼저. Its opposite is 늦게.", example: { ko: "오늘 일찍 일어났어요.", en: "I got up early today.", form: "일찍 before the verb; 일어나다 → 일어났어요 (past, polite casual)" } },
    // ------------------------------------------------- day 1, remaining
    "그|determiner": { korean: "그", note: "'That', for something near the listener or already mentioned. The three-way set is 이 (near me) / 그 (near you) / 저 (over there), where English has only this and that.", example: { ko: "그 책을 주세요.", en: "Please give me that book.", form: "그 + noun (determiner, never takes a particle); 주다 → 주세요 (polite request)" } },
    "개|counter": { korean: "개", note: "The all-purpose counter for objects, used when no more specific counter fits. It follows a native Korean number: 한 개, 두 개, 세 개 — never 일 개.", example: { ko: "사과 세 개 주세요.", en: "Please give me three apples.", form: "사과 + 세 (native number) + 개 (counter); 주다 → 주세요" } },
    "아|interjection": { korean: "아", note: "A sound of realisation or mild surprise, like English 'ah' or 'oh'. 아, 그래요? is 'oh, really?'. It carries no politeness of its own, so it fits any register.", example: { ko: "아, 알겠어요.", en: "Ah, I see.", form: "Interjection, standing alone before the clause; 알다 → 알겠어요" } },
    "그러나|conjunction": { korean: "그러나", note: "'However', joining two sentences. It is the written form — in speech Koreans say 하지만 or 그런데. It opens the second sentence rather than joining inside one.", example: { ko: "비가 왔어요. 그러나 우리는 갔어요.", en: "It rained. However, we went.", form: "그러나 opens the second sentence; 가다 → 갔어요 (past, polite casual)" } },
    "자기소개|noun phrase": { korean: "자기소개", note: "A self-introduction, the set piece you give on a first day at work or class. 자기소개를 하다 is the verb phrase.", example: { ko: "자기소개를 해 주세요.", en: "Please introduce yourself.", form: "자기소개 + 를 (object particle); 하다 → 해 + 주다 → 주세요 (request)" } },
    "다시 말해 주세요|phrase": { korean: "다시 말해 주세요", note: "'Please say that again' — the phrase to reach for the moment you lose the thread. Add 좀 for extra softness: 좀 다시 말해 주세요.", example: { ko: "죄송해요, 다시 말해 주세요.", en: "Sorry, please say that again.", form: "다시 + 말하다 → 말해 + 주다 → 주세요 (request for the speaker's benefit)" } },
    "아니다|adjective": { korean: "아니다", note: "'To not be', the negative of 이다. The thing denied takes 이/가, not 을/를: 학생이 아니에요 = I am not a student. This is the single most common beginner particle error.", example: { ko: "저는 학생이 아니에요.", en: "I am not a student.", form: "학생 + 이 (the complement of 아니다 takes 이/가); 아니다 → 아니에요" } },

    // ------------------------------------------------- day 2, remaining
    "장|counter": { korean: "장", note: "The counter for flat sheets — paper, tickets, photographs, pizza slices: 종이 두 장, 표 한 장. Takes native Korean numbers.", example: { ko: "표 두 장 주세요.", en: "Please give me two tickets.", form: "표 + 두 (native number) + 장 (counter); 주다 → 주세요" } },
    "그래|interjection": { korean: "그래", note: "'Yes, all right' — but casual, for friends and juniors only. Saying it to an elder or a stranger is rude; use 네 or 예 instead.", example: { ko: "그래, 알았어.", en: "Yeah, got it.", form: "Casual interjection; 알다 → 알았어 (past, casual)" } },
    "거|dependent noun": { korean: "거", note: "The spoken contraction of 것. Same rules: it needs a modifier in front, and it fuses with particles — 거 + 이 becomes 게, 거 + 는 becomes 건.", example: { ko: "이거 얼마예요?", en: "How much is this?", form: "이 (determiner) + 거; 얼마 + 예요 (이다 after a vowel, question)" } },
    "같다|adjective": { korean: "같다", note: "To be the same or to seem. The thing compared takes 와/과 or 하고: 저와 같아요. In -는 것 같다 it becomes the main way to hedge a guess: 비가 오는 것 같아요.", example: { ko: "제 생각도 같아요.", en: "I think the same.", form: "생각 + 도 (also); 같다 → 같아요 (present, polite casual)" } },
    "둘째|numeral": { korean: "둘째", note: "'Second' in an ordered list, and also the second child in a family. The set is 첫째, 둘째, 셋째 — note 첫째 is irregular, not 하나째.", example: { ko: "둘째 아들이에요.", en: "He is the second son.", form: "둘째 + noun; 아들 + 이에요 (이다 after a batchim)" } },
    "천천히 말해 주세요|phrase": { korean: "천천히 말해 주세요", note: "'Please speak slowly.' More useful than asking someone to repeat, because it fixes the cause rather than the symptom.", example: { ko: "조금 천천히 말해 주세요.", en: "Please speak a little more slowly.", form: "천천히 + 말하다 → 말해 + 주다 → 주세요 (request)" } },
    "대중교통|noun phrase": { korean: "대중교통", note: "Public transport as a category — buses, subway, trains together. Taking it uses 이용하다 or 타다: 대중교통을 이용해요.", example: { ko: "대중교통을 이용해요.", en: "I use public transport.", form: "대중교통 + 을 (object particle); 이용하다 → 이용해요" } },
    "의|particle": { korean: "의", note: "The possessive marker, 'of': 친구의 책. Pronounced [에] in this use, not [의]. Korean drops it far more often than English drops 'of' — 친구 책 is perfectly normal.", example: { ko: "친구의 이름을 몰라요.", en: "I do not know my friend's name.", form: "친구 + 의 (possessive); 이름 + 을 (object particle); 모르다 → 몰라요" } },
    "그렇다|adjective": { korean: "그렇다", note: "'To be so, to be like that.' ㅎ-irregular, giving 그래요 and 그런. It is the root of 그래서, 그러면, 그런데 — learning it explains a whole family of connectives.", example: { ko: "네, 그래요.", en: "Yes, that is so.", form: "그렇다 → 그래요 (ㅎ-irregular, present, polite casual)" } },
    "그|pronoun": { korean: "그", note: "'He', or 'that one'. As a third-person pronoun it is largely written — in speech Koreans use the person's name or title instead, or 그 사람 / 그분.", example: { ko: "그는 의사예요.", en: "He is a doctor.", form: "그 + 는 (topic particle after a vowel); 의사 + 예요 (이다 after a vowel)" } },
    "첫째|numeral": { korean: "첫째", note: "'First' in an ordered list, and the eldest child. Irregular — built on 첫, not 하나. Also opens a list of reasons: 첫째, ... 둘째, ...", example: { ko: "첫째, 시간이 없어요.", en: "First, there is no time.", form: "첫째 opening a list; 시간 + 이 (subject); 없다 → 없어요" } },
    "생각하다|verb": { korean: "생각하다", note: "To think. What you think about takes 을/를 or 에 대해: 그 문제를 생각해요. For 'I think that...', Koreans normally use -것 같다 instead, which sounds less assertive.", example: { ko: "가족을 생각해요.", en: "I think about my family.", form: "가족 + 을 (object particle); 생각하다 → 생각해요 (여-irregular, present, polite casual)" } },
    "무슨 뜻이에요|phrase": { korean: "무슨 뜻이에요", note: "'What does it mean?' — the phrase for asking about a word you have just heard. Point at it or repeat it first: '한글'이 무슨 뜻이에요?", example: { ko: "이 단어가 무슨 뜻이에요?", en: "What does this word mean?", form: "단어 + 가 (subject); 무슨 (determiner) + 뜻 + 이에요 (question)" } },
    "대|counter": { korean: "대", note: "The counter for vehicles and machines: 자동차 한 대, 컴퓨터 두 대. Takes native Korean numbers.", example: { ko: "차가 세 대 있어요.", en: "There are three cars.", form: "차 + 가 (subject); 세 (native number) + 대 (counter); 있다 → 있어요" } },
    "뭐|interjection": { korean: "뭐", note: "A filler, closer to 'well...' or 'I mean' than to a question. 뭐, 괜찮아요 shades the sentence toward reluctant acceptance.", example: { ko: "뭐, 괜찮아요.", en: "Well, it is fine.", form: "Interjection opening the clause; 괜찮다 → 괜찮아요" } },
    "크다|adjective": { korean: "크다", note: "To be big, of size. For height of a person or building use 높다; 키가 크다 is the fixed way to say someone is tall. ㅡ-irregular: 커요.", example: { ko: "집이 커요.", en: "The house is big.", form: "집 + 이 (subject particle); 크다 → 커요 (ㅡ drops before -어요)" } },
    "사이|noun": { korean: "사이", note: "The gap between two things, and by extension a relationship between two people: 친구 사이 = 'as friends'. Also 'while' in 그 사이에.", example: { ko: "우리는 좋은 사이예요.", en: "We are on good terms.", form: "좋다 → 좋은 (adjective modifier) + 사이; 이다 → 예요" } },

    // ------------------------------------------------- day 3, remaining
    "우리나라|noun": { korean: "우리나라", note: "Written as one word it means 'my country' from a Korean speaker's mouth — that is, Korea. A learner saying it will be heard as claiming Korea, so use 제 나라 for your own.", example: { ko: "우리나라는 사계절이 있어요.", en: "Our country has four seasons.", form: "우리나라 + 는 (topic particle); 사계절 + 이 (subject); 있다 → 있어요" } },
    "그때|noun": { korean: "그때", note: "'Then, at that time', pointing back at a moment already mentioned. Written as one word; 그 때 with a space is a different, rarer reading.", example: { ko: "그때 저는 학생이었어요.", en: "At that time I was a student.", form: "그때 opens the clause; 이다 → 이었어요 (past after a batchim, polite casual)" } },
    "때문|dependent noun": { korean: "때문", note: "'Because of', always as noun + 때문에. For a verb reason you need -기 때문에: 비가 오기 때문에. It never stands alone.", example: { ko: "비 때문에 못 갔어요.", en: "I could not go because of the rain.", form: "비 + 때문에 (cause); 못 + 가다 → 못 갔어요 (inability, past)" } },
    "잘 부탁드립니다|expression": { korean: "잘 부탁드립니다", note: "Said on joining a group or starting work together — roughly 'please look after me, I look forward to this'. There is no English equivalent, and omitting it on a first day is noticeable.", example: { ko: "안녕하세요. 잘 부탁드립니다.", en: "Hello. I look forward to working with you.", form: "Fixed expression; 부탁드리다 → 드립니다 (humble, formal polite)" } },
    "어떻게 생각해요|phrase": { korean: "어떻게 생각해요", note: "'What do you think?' — note Korean asks 어떻게 ('how'), not 무엇 ('what'). Asking 무엇을 생각해요? means 'what are you thinking about', a different question.", example: { ko: "이 영화를 어떻게 생각해요?", en: "What do you think of this movie?", form: "영화 + 를 (object); 어떻게 + 생각하다 → 생각해요 (question)" } },
    "실례합니다|expression": { korean: "실례합니다", note: "'Excuse me', for interrupting, squeezing past, or opening a question to a stranger. It is not an apology for wrongdoing — that is 죄송합니다.", example: { ko: "실례합니다, 길 좀 물어볼게요.", en: "Excuse me, may I ask for directions?", form: "Fixed expression; 실례하다 → 합니다 (formal polite)" } },
    "다|adverb": { korean: "다", note: "All, or completely, placed before the verb: 다 먹었어요 = 'I ate it all'. It modifies the action, where 모두 tends to gather the subjects.", example: { ko: "숙제를 다 했어요.", en: "I finished all my homework.", form: "다 before the verb; 하다 → 했어요 (past, polite casual)" } },
    "네|interjection": { korean: "네", note: "Yes, and also a general acknowledgement — Koreans say 네 constantly to show they are listening. Note it answers the question as asked, so to a negative question 네 can mean 'that's right, I didn't'.", example: { ko: "네, 알겠습니다.", en: "Yes, understood.", form: "Interjection; 알다 → 알겠습니다 (formal polite)" } },
    "자리|noun": { korean: "자리", note: "A seat or a spot. 자리가 있어요? asks whether a seat is free; 자리를 잡다 is to grab a place. Also a social occasion: 술자리.", example: { ko: "자리가 있어요?", en: "Is this seat free?", form: "자리 + 가 (subject particle); 있다 → 있어요 (question)" } },
    "얘기|noun": { korean: "얘기", note: "The spoken contraction of 이야기. 얘기하다 is to chat. It is casual — write 이야기 in an essay or an exam.", example: { ko: "친구하고 얘기했어요.", en: "I chatted with a friend.", form: "친구 + 하고 (with, casual); 얘기하다 → 얘기했어요 (past)" } },
    "셋째|numeral": { korean: "셋째", note: "'Third' in a list, and the third child. Built on 셋, regularly, unlike 첫째.", example: { ko: "셋째 줄에 앉으세요.", en: "Please sit in the third row.", form: "셋째 + 줄 + 에 (location); 앉다 → 앉으세요 (polite request)" } },
    "엄마|noun": { korean: "엄마", note: "Mum — what you call your own mother, and only in the family. 어머니 is the respectful word used about someone else's mother or in formal settings.", example: { ko: "엄마가 요리를 해요.", en: "Mum is cooking.", form: "엄마 + 가 (subject particle); 요리하다 → 요리를 해요" } },
    "에게|particle": { korean: "에게", note: "'To' a person, marking the recipient of giving, telling or sending: 친구에게 줬어요. Its casual twin is 한테 and its honorific is 께. For a place, use 에 instead — 에게 never attaches to a thing.", example: { ko: "친구에게 편지를 썼어요.", en: "I wrote a letter to a friend.", form: "친구 + 에게 (recipient particle); 쓰다 → 썼어요 (past, polite casual)" } },
    "시간이 없어요|phrase": { korean: "시간이 없어요", note: "'I do not have time.' Note the subject particle 이 — the thing you lack is grammatically the subject of 없다, not an object, so 시간을 없어요 is wrong.", example: { ko: "미안해요, 시간이 없어요.", en: "Sorry, I do not have time.", form: "시간 + 이 (subject of 없다); 없다 → 없어요 (present, polite casual)" } },

    // ------------------------------------------------- day 4, remaining
    "남편|noun": { korean: "남편", note: "Husband. There is no honorific version for your own husband — you say 제 남편 flatly. For someone else's, 남편분 adds respect.", example: { ko: "제 남편은 회사원이에요.", en: "My husband is an office worker.", form: "남편 + 은 (topic particle); 회사원 + 이에요 (이다 after a batchim)" } },
    "잘 먹겠습니다|expression": { korean: "잘 먹겠습니다", note: "Said just before eating, to whoever is feeding you — closer to 'thank you for this food' than to grace. Its partner 잘 먹었습니다 closes the meal.", example: { ko: "잘 먹겠습니다!", en: "Thank you for the food. (before eating)", form: "Fixed expression; 먹다 + 겠 (intention) + 습니다 (formal polite)" } },
    "잘 먹었습니다|expression": { korean: "잘 먹었습니다", note: "Said after finishing a meal someone provided. Pair it with 잘 먹겠습니다 at the start; skipping either is noticeable at a Korean table.", example: { ko: "잘 먹었습니다. 맛있었어요.", en: "Thank you for the meal. It was delicious.", form: "Fixed expression; 먹다 → 먹었습니다 (past, formal polite)" } },
    "어떤|determiner": { korean: "어떤", note: "'What kind of', asking about quality: 어떤 음악을 좋아해요? It also means 'a certain' in statements. 무슨 asks which category, so the two overlap but are not identical.", example: { ko: "어떤 음악을 좋아해요?", en: "What kind of music do you like?", form: "어떤 + noun (determiner); 음악 + 을 (object); 좋아하다 → 좋아해요" } },
    "환경 오염|noun phrase": { korean: "환경 오염", note: "Environmental pollution — a set phrase that turns up constantly in TOPIK reading passages about society. 환경을 오염시키다 is the verb form.", example: { ko: "환경 오염이 심각해요.", en: "Environmental pollution is serious.", form: "환경 오염 + 이 (subject particle); 심각하다 → 심각해요" } },
    "대학|noun": { korean: "대학", note: "A university, or a college within one. 대학교 is the institution as a whole and is what people usually say; 대학 is common in compounds like 대학 생활.", example: { ko: "대학에서 한국어를 배워요.", en: "I learn Korean at university.", form: "대학 + 에서 (action-location particle); 배우다 → 배워요" } },
    "가운데|noun": { korean: "가운데", note: "The middle, as noun + 가운데에. Also 'among' when picking from a group: 이 가운데에서 하나를 고르세요.", example: { ko: "방 가운데에 책상이 있어요.", en: "There is a desk in the middle of the room.", form: "가운데 + 에 (location particle); 있다 → 있어요" } },
    "일|dependent noun": { korean: "일", note: "The counter for days in dates and durations, with Sino-Korean numbers: 삼 일 (three days), 오월 오일 (5 May). For a number of days as a native count, 하루/이틀/사흘 are used instead.", example: { ko: "삼 일 동안 여행했어요.", en: "I travelled for three days.", form: "삼 (Sino-Korean number) + 일 + 동안 (duration); 여행하다 → 여행했어요" } },
    "한테|particle": { korean: "한테", note: "'To' a person, the casual spoken twin of 에게. Use 에게 in writing, 한테 in speech, 께 when the recipient deserves respect.", example: { ko: "동생한테 말했어요.", en: "I told my younger sibling.", form: "동생 + 한테 (recipient particle, casual); 말하다 → 말했어요 (past)" } },
    "께|particle": { korean: "께", note: "The honorific 'to a person', replacing 에게 when the recipient is an elder or superior: 선생님께 드렸어요. It normally pairs with the humble verb 드리다, not 주다.", example: { ko: "선생님께 선물을 드렸어요.", en: "I gave the teacher a present.", form: "선생님 + 께 (honorific recipient); 드리다 → 드렸어요 (humble, past)" } },
    "몇|numeral": { korean: "몇", note: "'How many', before a counter: 몇 개, 몇 명, 몇 시. It also means 'a few' in statements. It always needs a counter — 몇 사람 works because 사람 counts people.", example: { ko: "몇 시예요?", en: "What time is it?", form: "몇 + 시 (counter); 이다 → 예요 (question)" } },
    "이렇다|adjective": { korean: "이렇다", note: "'To be like this.' ㅎ-irregular, giving 이래요 and 이런. It is the 이 member of the 이렇다 / 그렇다 / 저렇다 set.", example: { ko: "왜 이래요?", en: "Why are you like this?", form: "이렇다 → 이래요 (ㅎ-irregular, present, polite casual, question)" } },
    "오늘|noun": { korean: "오늘", note: "Today, used as a noun so it can take particles: 오늘은 (as for today), 오늘까지 (by today). It also works bare as an adverb without 에 — 오늘에 가요 is wrong.", example: { ko: "오늘은 바빠요.", en: "Today I am busy.", form: "오늘 + 은 (topic particle); 바쁘다 → 바빠요 (ㅡ drops before -아요)" } },
    "시간이 있어요|phrase": { korean: "시간이 있어요", note: "'I have time', and as a question the standard way to ask someone if they are free. Like 없어요, it takes the subject particle 이.", example: { ko: "내일 시간이 있어요?", en: "Do you have time tomorrow?", form: "시간 + 이 (subject of 있다); 있다 → 있어요 (question)" } },
    "다녀오겠습니다|expression": { korean: "다녀오겠습니다", note: "Said on leaving home — literally 'I will go and come back'. The household answers 다녀오세요. Saying only 갈게요 to a parent sounds abrupt.", example: { ko: "학교에 다녀오겠습니다.", en: "I am off to school.", form: "다녀오다 + 겠 (intention) + 습니다 (formal polite)" } },
    "다녀왔습니다|expression": { korean: "다녀왔습니다", note: "Said on arriving home, the counterpart to 다녀오겠습니다. The reply is 어서 와 or 잘 다녀왔어?", example: { ko: "저 왔어요, 다녀왔습니다.", en: "I am home.", form: "다녀오다 → 다녀왔습니다 (past, formal polite)" } },
    "저|pronoun": { korean: "저", note: "'I', humble — the form to use with anyone senior or unfamiliar. 나 is the casual equivalent. Its possessive is 제, and as a subject it becomes 제가, never 저가.", example: { ko: "저는 학생이에요.", en: "I am a student.", form: "저 + 는 (topic particle after a vowel); note the subject form is 제가" } },
    "들어가다|verb": { korean: "들어가다", note: "To go in, away from the speaker. The place entered takes 에: 방에 들어가요. Its mirror 들어오다 is coming in toward the speaker.", example: { ko: "교실에 들어갔어요.", en: "I went into the classroom.", form: "교실 + 에 (destination particle); 들어가다 → 들어갔어요 (past)" } },
    "끝|noun": { korean: "끝", note: "The end of something. 끝나다 is the verb 'to end' and 끝내다 is 'to finish something'. Said alone, 끝! means 'done, that's it'.", example: { ko: "이제 끝이에요.", en: "That is the end now.", form: "끝 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "입|noun": { korean: "입", note: "The mouth. 입다 (to wear) is an unrelated verb that merely looks similar. 입맛이 없다 is the set phrase for having no appetite.", example: { ko: "입을 크게 벌리세요.", en: "Please open your mouth wide.", form: "입 + 을 (object particle); 벌리다 → 벌리세요 (polite request)" } },
    "않다|auxiliary verb": { korean: "않다", note: "-지 않다, the long negation: 가지 않아요 = 안 가요. Attach 지 to the stem, then 않다. It is preferred in writing and with long verbs, where 안 in front sounds clumsy.", example: { ko: "저는 커피를 마시지 않아요.", en: "I do not drink coffee.", form: "마시다 → 마시지 (connector) + 않다 → 않아요 (negated present, polite casual)" } },
    "다르다|adjective": { korean: "다르다", note: "To be different. 르-irregular: 달라요. What it differs from takes 와/과 or 하고. Do not confuse it with 틀리다, which means 'to be wrong'.", example: { ko: "생각이 달라요.", en: "Our thoughts are different.", form: "생각 + 이 (subject); 다르다 → 달라요 (르-irregular, present, polite casual)" } },
    "하지만|conjunction": { korean: "하지만", note: "'But, however', opening the second sentence. It is the everyday spoken choice; 그러나 is its written equivalent and 그런데 adds a change of subject.", example: { ko: "피곤해요. 하지만 가야 해요.", en: "I am tired. But I have to go.", form: "하지만 opens the second sentence; 가다 → 가야 해요 (obligation)" } },
    "다른|determiner": { korean: "다른", note: "'Other, different', in front of a noun: 다른 사람. It is the modifier form of 다르다, so it never takes a particle of its own.", example: { ko: "다른 것을 보여 주세요.", en: "Please show me a different one.", form: "다른 + 것 + 을 (object particle); 보이다 → 보여 + 주다 → 주세요" } },
    "필요|noun": { korean: "필요", note: "Need or necessity. In practice you will meet it as 필요하다 ('to be necessary'), where the needed thing takes 이/가: 돈이 필요해요, not 돈을.", example: { ko: "도움이 필요해요.", en: "I need help.", form: "도움 + 이 (the needed thing takes 이/가); 필요하다 → 필요해요" } },
    "하늘|noun": { korean: "하늘", note: "The sky. 하늘이 맑다 for clear skies; 하늘색 is sky blue.", example: { ko: "하늘이 파래요.", en: "The sky is blue.", form: "하늘 + 이 (subject particle); 파랗다 → 파래요 (ㅎ-irregular, present, polite casual)" } },
    "내다|verb": { korean: "내다", note: "To put out or produce, and the verb in many set phrases: 돈을 내다 (to pay), 시간을 내다 (to make time), 화를 내다 (to get angry).", example: { ko: "제가 낼게요.", en: "I will pay.", form: "제 + 가 (subject); 내다 → 낼게요 (intention, polite casual)" } },

    // ------------------------------------------------- day 5, remaining
    "수고하셨습니다|expression": { korean: "수고하셨습니다", note: "'Thank you for your hard work', said at the end of a shared task or a working day. Say it to peers and juniors; to a senior, 고생하셨습니다 or a plain 감사합니다 is safer.", example: { ko: "오늘도 수고하셨습니다.", en: "Thank you for your hard work today as well.", form: "수고하다 + 시 (honorific) → 수고하셨습니다 (past, formal polite)" } },
    "별말씀을요|phrase": { korean: "별말씀을요", note: "'Not at all' — the modest reply to thanks or praise. Literally 'what strange words'. 천만에요 fills the same slot and is slightly more old-fashioned.", example: { ko: "별말씀을요. 당연한 일이에요.", en: "Not at all. It was the least I could do.", form: "Fixed expression; 별 + 말씀 (honorific 말) + 을요" } },
    "천만에요|phrase": { korean: "천만에요", note: "'You are welcome', deflecting thanks. Textbooks teach it, but in daily speech 아니에요 and 별말씀을요 are heard more often.", example: { ko: "천만에요. 도움이 됐다니 기뻐요.", en: "You are welcome. I am glad it helped.", form: "Fixed expression, used whole" } },
    "인천|proper noun": { korean: "인천", note: "Incheon, the port city west of Seoul and the site of the main international airport. 인천 공항 is where most journeys into Korea begin.", example: { ko: "인천 공항에 도착했어요.", en: "I arrived at Incheon Airport.", form: "인천 공항 + 에 (destination particle); 도착하다 → 도착했어요 (past)" } },
    "대구|proper noun": { korean: "대구", note: "Daegu, a large city in the southeast, inland and known for hot summers. The identical 대구 meaning cod is a separate word.", example: { ko: "대구는 여름에 아주 더워요.", en: "Daegu is very hot in summer.", form: "대구 + 는 (topic particle); 여름 + 에 (time); 덥다 → 더워요 (ㅂ-irregular)" } },
    "이제|noun": { korean: "이제", note: "Now, but with a sense of change from before — 이제 알겠어요 means 'now I finally get it'. Plain 지금 has no such contrast.", example: { ko: "이제부터 열심히 할게요.", en: "From now on I will work hard.", form: "이제 + 부터 (starting-point particle); 하다 → 할게요 (intention)" } },
    "술|noun": { korean: "술", note: "Alcohol of any kind. 술을 마시다 is to drink; 술집 is a bar. Korean drinking etiquette turns up in TOPIK listening, so the word is worth knowing well.", example: { ko: "저는 술을 안 마셔요.", en: "I do not drink alcohol.", form: "술 + 을 (object particle); 안 + 마시다 → 안 마셔요 (negated present)" } },
    "송이|counter": { korean: "송이", note: "The counter for flowers and clustered things: 장미 한 송이 (a single rose), 포도 두 송이 (two bunches of grapes). Takes native Korean numbers.", example: { ko: "장미 한 송이 주세요.", en: "Please give me one rose.", form: "장미 + 한 (native number) + 송이 (counter); 주다 → 주세요" } },
    "예|interjection": { korean: "예", note: "Yes, slightly more formal and deferential than 네. Common in the military, in service work, and from older speakers.", example: { ko: "예, 알겠습니다.", en: "Yes, understood.", form: "Interjection; 알다 → 알겠습니다 (formal polite)" } },
    "명|dependent noun": { korean: "명", note: "The neutral counter for people: 세 명, 네 명. 사람 is the plainer alternative and 분 is the honorific — count guests and elders with 분.", example: { ko: "학생이 다섯 명 있어요.", en: "There are five students.", form: "학생 + 이 (subject); 다섯 (native number) + 명 (counter); 있다 → 있어요" } },
    "개|dependent noun": { korean: "개", note: "The general counter for objects, used as a bound noun after a native Korean number: 한 개, 두 개. When no specific counter fits, this is the safe default.", example: { ko: "빵 두 개 주세요.", en: "Please give me two pieces of bread.", form: "빵 + 두 (native number) + 개 (counter); 주다 → 주세요" } },
    "에게서|particle": { korean: "에게서", note: "'From' a person, marking the source of something received: 친구에게서 받았어요. Its casual twin is 한테서. For a place, use 에서.", example: { ko: "친구에게서 선물을 받았어요.", en: "I received a present from a friend.", form: "친구 + 에게서 (source particle); 받다 → 받았어요 (past)" } },
    "한테서|particle": { korean: "한테서", note: "'From' a person, the spoken form of 에게서. In casual speech the 서 is often dropped, leaving just 한테.", example: { ko: "동생한테서 들었어요.", en: "I heard it from my younger sibling.", form: "동생 + 한테서 (source particle, casual); 듣다 → 들었어요 (ㄷ-irregular, past)" } },
    "사랑|noun": { korean: "사랑", note: "Love. The verb is 사랑하다, and it takes 을/를: 저는 가족을 사랑해요. Koreans use it far more sparingly than English speakers use 'love'.", example: { ko: "사랑해요.", en: "I love you.", form: "사랑하다 → 사랑해요 (여-irregular, present, polite casual; object usually dropped)" } },
    "너|pronoun": { korean: "너", note: "'You', casual — for close friends, children and juniors only. Using it with anyone else is rude; Korean normally uses the person's name or title instead. Its subject form is 네가, pronounced [니가] to avoid confusion with 내가.", example: { ko: "너는 어디에 가?", en: "Where are you going?", form: "너 + 는 (topic particle); 가다 → 가 (casual, plain)" } },
    "축하합니다|expression": { korean: "축하합니다", note: "Congratulations. The thing congratulated takes 을/를: 졸업을 축하합니다. Pronounced [추카함니다] — the ㄱ and ㅎ fuse.", example: { ko: "생일 축하합니다!", en: "Happy birthday!", form: "Fixed expression; 축하하다 → 합니다 (formal polite)" } },
    "아빠|noun": { korean: "아빠", note: "Dad — what you call your own father, within the family. 아버지 is the respectful word for formal settings or someone else's father.", example: { ko: "아빠는 지금 회사에 있어요.", en: "Dad is at the office now.", form: "아빠 + 는 (topic particle); 회사 + 에 (location); 있다 → 있어요" } },
    "넷째|numeral": { korean: "넷째", note: "'Fourth' in a list, and the fourth child. Built regularly on 넷.", example: { ko: "넷째 줄에 앉았어요.", en: "I sat in the fourth row.", form: "넷째 + 줄 + 에 (location); 앉다 → 앉았어요 (past)" } },
    "한번|noun": { korean: "한번", note: "'Once' or 'give it a go'. Written as one word it softens a suggestion: 한번 해 보세요 = 'why not try it'. With a space, 한 번 is literally one time as a count.", example: { ko: "한번 해 보세요.", en: "Give it a try.", form: "한번 + 하다 → 해 + 보다 → 보세요 (trying, polite request)" } },
    "이런|determiner": { korean: "이런", note: "'This kind of', in front of a noun: 이런 사람. The modifier form of 이렇다. Alone as an exclamation, 이런! means 'oh no'.", example: { ko: "이런 음식을 좋아해요.", en: "I like this kind of food.", form: "이런 + 음식 + 을 (object particle); 좋아하다 → 좋아해요" } },
    "오랜만이에요|expression": { korean: "오랜만이에요", note: "'Long time no see.' The standard greeting after a gap. 오랜만입니다 is the formal version and 오랜만이야 the casual one.", example: { ko: "오랜만이에요! 잘 지냈어요?", en: "Long time no see! How have you been?", form: "오랜만 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "잘 지내셨어요|expression": { korean: "잘 지내셨어요", note: "'How have you been?', with the honorific 시 built in. Pair it with 오랜만이에요. The plain version is 잘 지냈어요?", example: { ko: "오랜만이에요. 잘 지내셨어요?", en: "Long time no see. How have you been?", form: "지내다 + 시 (honorific) → 지내셨어요 (past, polite casual, question)" } },
    "가슴|noun": { korean: "가슴", note: "The chest, and the seat of feeling in idiom: 가슴이 아프다 is heartache, not chest pain. For the organ use 심장.", example: { ko: "가슴이 아파요.", en: "My heart aches.", form: "가슴 + 이 (subject particle); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "맛|noun": { korean: "맛", note: "Flavour or taste. 맛있다 (delicious) and 맛없다 (bad-tasting) are built from it and are single words. 맛을 보다 is to taste something.", example: { ko: "이 음식은 맛이 좋아요.", en: "This food tastes good.", form: "맛 + 이 (subject particle); 좋다 → 좋아요 (present, polite casual)" } },
    "나가다|verb": { korean: "나가다", note: "To go out, away from the speaker. The place left takes 에서: 집에서 나가요. Its mirror 나오다 is coming out toward the speaker.", example: { ko: "잠깐 나갈게요.", en: "I will step out for a moment.", form: "잠깐 + 나가다 → 나갈게요 (intention, polite casual)" } },
    "나가다|auxiliary verb": { korean: "나가다", note: "-어 나가다 means carrying an action forward and onward, often against resistance: 이겨 나가다 (to keep overcoming). It is more written than spoken.", example: { ko: "어려움을 이겨 나갔어요.", en: "They kept overcoming the difficulties.", form: "이기다 → 이겨 (connector) + 나가다 → 나갔어요 (past)" } },
    "뭐|pronoun": { korean: "뭐", note: "'What', the spoken contraction of 무엇. 뭐예요? is the everyday 'what is it?'. Write 무엇 in formal contexts.", example: { ko: "이게 뭐예요?", en: "What is this?", form: "이거 + 가 → 이게 (contracted subject); 뭐 + 예요 (question)" } },
    "아내|noun": { korean: "아내", note: "Wife, the neutral word for your own. 와이프 is a common borrowing in speech, and 부인 refers politely to someone else's wife.", example: { ko: "제 아내는 선생님이에요.", en: "My wife is a teacher.", form: "아내 + 는 (topic particle); 선생님 + 이에요 (이다 after a batchim)" } },
    "인구 감소|noun phrase": { korean: "인구 감소", note: "Population decline — a set phrase that appears constantly in TOPIK reading passages on Korean society. Its opposite is 인구 증가.", example: { ko: "인구 감소가 문제예요.", en: "Population decline is a problem.", form: "인구 감소 + 가 (subject particle); 문제 + 예요 (이다 after a vowel)" } },
    "바로|adverb": { korean: "바로", note: "'Right away' in time, and 'right there' in place — 바로 앞에. It also emphasises identity: 바로 그 사람이에요 = 'that is exactly the person'.", example: { ko: "바로 갈게요.", en: "I will go right away.", form: "바로 before the verb; 가다 → 갈게요 (intention, polite casual)" } },
    // ================================================================= day 6
    "그|interjection": { korean: "그", note: "A hesitation filler, like English 'um' or 'er', while you search for a word. Koreans stretch it — 그어... — and often follow it with 뭐지?", example: { ko: "그, 뭐라고 했지요?", en: "Um, what did you say?", form: "Filler opening the clause; 하다 → 했지요 (past, seeking confirmation)" } },
    "에 대해|expression": { korean: "에 대해", note: "'About, concerning', after a noun: 한국에 대해 알고 싶어요. The fuller 에 대하여 is written; before a noun it becomes 에 대한 — 한국에 대한 책.", example: { ko: "그 문제에 대해 이야기했어요.", en: "We talked about that problem.", form: "문제 + 에 대해; 이야기하다 → 이야기했어요 (past, polite casual)" } },
    "도시|noun": { korean: "도시", note: "A city as a type of place, opposed to 시골 (the countryside). For a named city, 시 is attached instead: 서울시.", example: { ko: "서울은 큰 도시예요.", en: "Seoul is a big city.", form: "서울 + 은 (topic); 크다 → 큰 (modifier) + 도시; 이다 → 예요" } },
    "물론이죠|phrase": { korean: "물론이죠", note: "'Of course' as a warm, willing answer to a request. The 죠 ending invites agreement, which is what makes it sound generous rather than curt.", example: { ko: "물론이죠. 제가 도와드릴게요.", en: "Of course. I will help you.", form: "물론 + 이다 → 이죠 (이지요 contracted; agreement-seeking)" } },
    "으로|particle": { korean: "으로", note: "After a consonant; 로 after a vowel or ㄹ. It marks the means (버스로 가요), the direction (왼쪽으로), and the material (나무로 만들어요). Direction differs from 에: 로 is 'toward', 에 is 'to and arriving'.", example: { ko: "젓가락으로 먹어요.", en: "I eat with chopsticks.", form: "젓가락 ends in a batchim so it takes 으로; a vowel noun takes 로: 버스로" } },
    "퍼센트|dependent noun": { korean: "퍼센트", note: "Percent, following a Sino-Korean number: 오십 퍼센트. The symbol % is read the same way. 프로 is a common spoken alternative.", example: { ko: "학생의 오십 퍼센트가 왔어요.", en: "Fifty percent of the students came.", form: "오십 (Sino-Korean) + 퍼센트 + 가 (subject); 오다 → 왔어요" } },
    "에 따라|expression": { korean: "에 따라", note: "'According to' or 'depending on', after a noun: 사람에 따라 달라요. Before a noun it becomes 에 따른.", example: { ko: "날씨에 따라 계획이 바뀌어요.", en: "The plan changes depending on the weather.", form: "날씨 + 에 따라; 바뀌다 → 바뀌어요 (present, polite casual)" } },
    "모두|adverb": { korean: "모두", note: "All, altogether, before the verb: 모두 왔어요. 다 is the closer, more casual equivalent; 모두 leans slightly formal and often totals things up.", example: { ko: "모두 합쳐서 만 원이에요.", en: "It comes to ten thousand won altogether.", form: "모두 before the verb; 합치다 → 합쳐서 (connector); 이다 → 이에요" } },
    "을 통해|expression": { korean: "을 통해", note: "'Through' or 'by way of', after a noun — a channel or medium: 인터넷을 통해 배웠어요. 를 통해 after a vowel.", example: { ko: "친구를 통해 알게 됐어요.", en: "I came to know through a friend.", form: "친구 + 를 통해; 알다 → 알게 되다 → 알게 됐어요 (past)" } },
    "그동안|noun": { korean: "그동안", note: "'During that time' or 'in the meantime', looking back at a stretch just past. 그동안 잘 지냈어요? is a standard greeting after a gap.", example: { ko: "그동안 잘 지냈어요?", en: "How have you been in the meantime?", form: "그동안 opens the clause; 지내다 → 지냈어요 (past, question)" } },
    "바람|noun": { korean: "바람", note: "Wind. It blows with 불다: 바람이 불어요, never 바람이 와요. The separate bound noun 바람 in -는 바람에 means 'because of' and is unrelated in sense.", example: { ko: "바람이 많이 불어요.", en: "The wind is blowing hard.", form: "바람 + 이 (subject); 불다 → 불어요 (present, polite casual)" } },
    "와|particle": { korean: "와", note: "'And' or 'with', joining nouns after a vowel; 과 after a consonant. It is the written pairing — in speech Koreans say 하고 or 랑. It joins nouns only, never clauses.", example: { ko: "커피와 빵을 샀어요.", en: "I bought coffee and bread.", form: "커피 ends in a vowel so it takes 와; a batchim noun takes 과: 빵과" } },
    "그럼요|phrase": { korean: "그럼요", note: "'Of course, certainly' — an enthusiastic yes. Warmer than 물론이죠 and very common in speech when agreeing to help.", example: { ko: "그럼요, 언제든지요.", en: "Of course, any time.", form: "그럼 + 요 (politeness particle on a fixed expression)" } },
    "번|dependent noun": { korean: "번", note: "Two jobs: the counter for times with native numbers (한 번, 두 번 = once, twice), and a number label with Sino-Korean numbers (삼 번 = number three). 한번 written solid means 'give it a go'.", example: { ko: "두 번 갔어요.", en: "I went twice.", form: "두 (native number) + 번 (counter); 가다 → 갔어요 (past)" } },
    "에 비해|expression": { korean: "에 비해", note: "'Compared to', after a noun: 작년에 비해 추워요. Before a noun it becomes 에 비한. It sets a baseline rather than making a direct comparison the way 보다 does.", example: { ko: "작년에 비해 많이 추워요.", en: "It is much colder compared to last year.", form: "작년 + 에 비해; 춥다 → 추워요 (ㅂ-irregular, present, polite casual)" } },
    "근|counter": { korean: "근", note: "A traditional unit of weight, about 600g, still used at markets and butchers for meat and vegetables: 고기 한 근. Takes native Korean numbers.", example: { ko: "돼지고기 한 근 주세요.", en: "Please give me one geun of pork.", form: "돼지고기 + 한 (native number) + 근 (counter); 주다 → 주세요" } },
    "어디|interjection": { korean: "어디", note: "Not the question word here but a nudge — 'well then, let's see', said before trying something. 어디 봅시다 is 'let's have a look'.", example: { ko: "어디 한번 봅시다.", en: "Well then, let us have a look.", form: "어디 as a nudge; 보다 → 봅시다 (formal suggestion)" } },
    "넣다|verb": { korean: "넣다", note: "To put something in. Where it goes takes 에: 가방에 넣어요. Its opposite is 꺼내다 (to take out).", example: { ko: "가방에 책을 넣었어요.", en: "I put the book in the bag.", form: "가방 + 에 (destination); 책 + 을 (object); 넣다 → 넣었어요 (past)" } },
    "광주|proper noun": { korean: "광주", note: "Gwangju, the largest city in the southwest, known for its food and for the 1980 democratic uprising. Often paired with 전라도 in reading passages.", example: { ko: "광주에서 이 년 살았어요.", en: "I lived in Gwangju for two years.", form: "광주 + 에서 (location); 이 년 (Sino-Korean + counter); 살다 → 살았어요" } },
    "기후 변화|noun phrase": { korean: "기후 변화", note: "Climate change, a set phrase that appears often in TOPIK reading. 기후 is long-term climate, as against 날씨 for today's weather.", example: { ko: "기후 변화가 심각해요.", en: "Climate change is serious.", form: "기후 변화 + 가 (subject); 심각하다 → 심각해요" } },
    "학년|noun": { korean: "학년", note: "A school year or grade, with Sino-Korean numbers: 일 학년, 이 학년. Asking 몇 학년이에요? is how you ask what year someone is in.", example: { ko: "저는 삼 학년이에요.", en: "I am in the third year.", form: "삼 (Sino-Korean) + 학년 + 이에요 (이다 after a batchim)" } },
    "일|numeral": { korean: "일", note: "Sino-Korean 'one', used in dates, money, phone numbers and counting above ten: 일월 (January), 십일 (eleven). Native 하나 covers objects and ages.", example: { ko: "일월에 시험이 있어요.", en: "There is an exam in January.", form: "일 + 월 (Sino-Korean number before a Sino-Korean counter); 있다 → 있어요" } },

    // ================================================================= day 7
    "부르다|verb": { korean: "부르다", note: "To call someone over, and also to sing: 노래를 부르다. 르-irregular, giving 불러요. Do not use it for phoning — that is 전화하다.", example: { ko: "노래를 불렀어요.", en: "I sang a song.", form: "노래 + 를 (object); 부르다 → 불렀어요 (르-irregular, past)" } },
    "에 의해|expression": { korean: "에 의해", note: "'By' an agent, mostly in written and passive sentences: 이 책은 그 사람에 의해 쓰였어요. In speech Koreans restructure the sentence instead.", example: { ko: "이 그림은 학생에 의해 그려졌어요.", en: "This picture was drawn by a student.", form: "학생 + 에 의해; 그리다 → 그려졌어요 (passive, past)" } },
    "하고|particle": { korean: "하고", note: "'And' or 'with', the spoken workhorse. Unlike 와/과 it does not change for batchim, which is why speech prefers it: 밥하고 김치, 친구하고 갔어요.", example: { ko: "친구하고 영화를 봤어요.", en: "I watched a movie with a friend.", form: "친구 + 하고 (with, spoken); 보다 → 봤어요 (past, polite casual)" } },
    "죽다|verb": { korean: "죽다", note: "To die. Blunt — for a person you respect, use 돌아가시다 instead. Also hyperbole in speech: 배고파 죽겠어요 = 'I am starving to death'.", example: { ko: "배고파 죽겠어요.", en: "I am starving.", form: "배고프다 → 배고파 (connector) + 죽다 → 죽겠어요 (exaggeration, polite casual)" } },
    "아무래도 좋아요|phrase": { korean: "아무래도 좋아요", note: "'Either is fine with me', deferring a choice. 아무거나 좋아요 does the same job for objects and is more common in a restaurant.", example: { ko: "저는 아무래도 좋아요.", en: "Either is fine with me.", form: "아무래도 + 좋다 → 좋아요 (present, polite casual)" } },
    "꿈|noun": { korean: "꿈", note: "A dream, both while asleep and as an ambition. You do not 'have' one — you 꿈을 꾸다, using the dedicated verb 꾸다.", example: { ko: "어젯밤에 꿈을 꿨어요.", en: "I had a dream last night.", form: "꿈 + 을 (object); 꾸다 → 꿨어요 (past, polite casual)" } },
    "시|dependent noun": { korean: "시", note: "O'clock, with native Korean numbers: 한 시, 두 시, 세 시. Minutes take Sino-Korean 분 instead — 세 시 십 분. Mixing the two systems here is the classic error.", example: { ko: "지금 세 시예요.", en: "It is three o'clock now.", form: "세 (native number) + 시; 이다 → 예요 (after a vowel)" } },
    "을 위해|expression": { korean: "을 위해", note: "'For the sake of', after a noun: 가족을 위해 일해요. For a verb reason use -기 위해 instead: 배우기 위해.", example: { ko: "가족을 위해 일해요.", en: "I work for my family.", form: "가족 + 을 위해; 일하다 → 일해요 (present, polite casual)" } },
    "그래|conjunction": { korean: "그래", note: "'So, and so', opening a casual follow-up. It is the clipped spoken form; 그래서 is the full connective and what you should write.", example: { ko: "그래, 그래서 어떻게 됐어?", en: "So, what happened then?", form: "그래 opening the clause; 되다 → 됐어 (past, casual)" } },
    "내리다|verb": { korean: "내리다", note: "To get off a vehicle, and for rain or snow to fall. The vehicle takes 에서: 버스에서 내려요. Its opposite for boarding is 타다.", example: { ko: "다음 역에서 내려요.", en: "I get off at the next station.", form: "역 + 에서 (source); 내리다 → 내려요 (present, polite casual)" } },
    "나무|noun": { korean: "나무", note: "A tree, and also wood as a material: 나무로 만든 의자. Counted with 그루 for standing trees.", example: { ko: "공원에 나무가 많아요.", en: "There are many trees in the park.", form: "공원 + 에 (location); 나무 + 가 (subject); 많다 → 많아요" } },
    "이때|noun": { korean: "이때", note: "'At this moment', pointing at the present or a moment just described. Written solid, and paired with 그때 for a past moment.", example: { ko: "이때 전화가 왔어요.", en: "At this moment the phone rang.", form: "이때 opens the clause; 전화 + 가 (subject); 오다 → 왔어요 (past)" } },
    "물건|noun": { korean: "물건", note: "A thing or an item, especially goods for sale. 물건이 좋다 is 'the goods are good quality'. For an abstract 'thing', 것 is the word.", example: { ko: "이 물건은 얼마예요?", en: "How much is this item?", form: "물건 + 은 (topic); 얼마 + 예요 (question)" } },
    "만|numeral": { korean: "만", note: "Ten thousand — the pivot of Korean number-reading. Korean groups by four digits, so 100,000 is 십만 and a million is 백만, not 'one thousand thousand'.", example: { ko: "만 원이에요.", en: "It is ten thousand won.", form: "만 + 원 (currency counter); 이다 → 이에요 (after a batchim)" } },
    "와 관련해|expression": { korean: "와 관련해", note: "'In relation to', after a noun — formal and mostly written: 이 문제와 관련해. 과 관련해 after a consonant.", example: { ko: "그 사건과 관련해 조사가 있었어요.", en: "There was an investigation in relation to that incident.", form: "사건 + 과 관련해; 조사 + 가 (subject); 있다 → 있었어요 (past)" } },
    "이랑|particle": { korean: "이랑", note: "'And' or 'with', the most casual of the set — friends and family only. 랑 after a vowel, 이랑 after a consonant. Never in writing.", example: { ko: "친구랑 놀았어요.", en: "I hung out with a friend.", form: "친구 ends in a vowel so it takes 랑; a batchim noun takes 이랑: 동생이랑" } },
    "생기다|verb": { korean: "생기다", note: "For something to come into being — a problem arises, a shop opens, you acquire something. It is intransitive, so what appears takes 이/가: 문제가 생겼어요.", example: { ko: "문제가 생겼어요.", en: "A problem has come up.", form: "문제 + 가 (subject); 생기다 → 생겼어요 (past, polite casual)" } },
    "발|noun": { korean: "발", note: "The foot. 다리 is the leg above it — Korean keeps them separate more strictly than casual English does. 발이 아파요 is specifically sore feet.", example: { ko: "발이 아파요.", en: "My feet hurt.", form: "발 + 이 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "자루|counter": { korean: "자루", note: "The counter for long thin objects held in the hand: 연필 한 자루, 칼 두 자루. Takes native Korean numbers.", example: { ko: "연필 세 자루 주세요.", en: "Please give me three pencils.", form: "연필 + 세 (native number) + 자루 (counter); 주다 → 주세요" } },
    "모든|determiner": { korean: "모든", note: "'Every, all', in front of a noun: 모든 사람. It never takes a particle. For 'all' as an adverb after the subject, use 다 or 모두.", example: { ko: "모든 학생이 왔어요.", en: "Every student came.", form: "모든 + 학생 + 이 (subject particle); 오다 → 왔어요 (past)" } },
    "사용하다|verb": { korean: "사용하다", note: "To use, slightly formal. 쓰다 is the everyday equivalent and is what people say aloud; 사용하다 fits instructions and writing.", example: { ko: "이 방법을 사용해요.", en: "I use this method.", form: "방법 + 을 (object); 사용하다 → 사용해요 (여-irregular, present)" } },
    "을 바탕으로|expression": { korean: "을 바탕으로", note: "'On the basis of', after a noun — written register, common in TOPIK reading: 경험을 바탕으로. 를 바탕으로 after a vowel.", example: { ko: "경험을 바탕으로 책을 썼어요.", en: "I wrote a book on the basis of my experience.", form: "경험 + 을 바탕으로; 쓰다 → 썼어요 (ㅡ drops, past)" } },
    "상관없어요|phrase": { korean: "상관없어요", note: "'It does not matter' — neutral, but blunt if said flatly. 괜찮아요 is warmer when someone is trying to accommodate you.", example: { ko: "저는 상관없어요.", en: "It does not matter to me.", form: "상관없다 → 상관없어요 (present, polite casual)" } },
    "쪽|dependent noun": { korean: "쪽", note: "A side or direction, after a modifier: 이쪽, 오른쪽, 남쪽. It is also the counter for pages: 십 쪽.", example: { ko: "이쪽으로 오세요.", en: "Please come this way.", form: "이 + 쪽 + 으로 (direction particle); 오다 → 오세요 (polite request)" } },
    "대전|proper noun": { korean: "대전", note: "Daejeon, a central city and the country's science and research hub. Its position makes it the main rail junction, so it turns up in travel dialogues.", example: { ko: "대전은 서울에서 한 시간 거리예요.", en: "Daejeon is an hour from Seoul.", form: "대전 + 은 (topic); 서울 + 에서 (source); 이다 → 예요" } },
    "인공 지능|noun phrase": { korean: "인공 지능", note: "Artificial intelligence, abbreviated AI in Korean text too. A frequent topic in higher-level TOPIK reading about technology and work.", example: { ko: "인공 지능이 빠르게 발전해요.", en: "Artificial intelligence is developing fast.", form: "인공 지능 + 이 (subject); 발전하다 → 발전해요" } },
    "결혼|noun": { korean: "결혼", note: "Marriage. The verb 결혼하다 takes 와/과 or 하고 for the spouse, not 을/를: 친구와 결혼했어요.", example: { ko: "다음 달에 결혼해요.", en: "I am getting married next month.", form: "달 + 에 (time); 결혼하다 → 결혼해요 (present used for a fixed future)" } },
    "들어오다|verb": { korean: "들어오다", note: "To come in, toward the speaker. The place entered takes 에: 방에 들어와요. Its mirror 들어가다 goes in away from the speaker.", example: { ko: "들어오세요.", en: "Please come in.", form: "들어오다 → 들어오세요 (polite request)" } },
    "그거|pronoun": { korean: "그거", note: "'That thing', the spoken contraction of 그것. It fuses with particles: 그거 + 이 becomes 그게, 그거 + 는 becomes 그건.", example: { ko: "그거 주세요.", en: "Please give me that.", form: "그거 with the object particle dropped, as is normal in speech; 주다 → 주세요" } },
    "도|particle": { korean: "도", note: "'Also, too', and 'even' with a negative. It replaces 은/는 and 이/가 rather than stacking with them — 저도 갔어요, never 저는도.", example: { ko: "저도 갔어요.", en: "I went too.", form: "저 + 도 (replacing the topic particle); 가다 → 갔어요 (past)" } },
    "아기|noun": { korean: "아기", note: "A baby. 아이 is a child who can walk and talk; 애기 is a common soft spoken variant of 아기.", example: { ko: "아기가 자고 있어요.", en: "The baby is sleeping.", form: "아기 + 가 (subject); 자다 → 자고 있어요 (progressive, present)" } },
    "을 중심으로|expression": { korean: "을 중심으로", note: "'Centering on', after a noun — written register: 서울을 중심으로 발전했어요. 를 중심으로 after a vowel.", example: { ko: "서울을 중심으로 발전했어요.", en: "It developed centering on Seoul.", form: "서울 + 을 중심으로; 발전하다 → 발전했어요 (past)" } },

    // ================================================================= day 8
    "힘들다|adjective": { korean: "힘들다", note: "To be hard or exhausting — of effort, not of difficulty to understand, which is 어렵다. ㄹ-irregular: 힘듭니다, 힘드세요.", example: { ko: "일이 너무 힘들어요.", en: "The work is too hard.", form: "일 + 이 (subject); 힘들다 → 힘들어요 (present, polite casual)" } },
    "아저씨|noun": { korean: "아저씨", note: "How you address an unrelated middle-aged man — a shopkeeper, a taxi driver. It is normal and not rude, but it does mark him as no longer young, so use 선생님 in professional settings.", example: { ko: "아저씨, 여기요!", en: "Excuse me! (to a middle-aged man)", form: "Direct address; 여기 + 요 (politeness particle) used to call someone over" } },
    "옛날|noun": { korean: "옛날", note: "The old days. 옛날에 opens folk tales the way 'once upon a time' does. For a specific past time use 예전 or 과거.", example: { ko: "옛날에 한 왕이 살았어요.", en: "Once upon a time there lived a king.", form: "옛날 + 에 (time particle); 살다 → 살았어요 (past)" } },
    "왜냐하면|conjunction": { korean: "왜냐하면", note: "'Because', opening the sentence that explains. It normally pairs with -기 때문이다 at the end: 왜냐하면 ... 때문이에요. Leaving off that ending sounds unfinished.", example: { ko: "못 갔어요. 왜냐하면 아팠기 때문이에요.", en: "I could not go, because I was ill.", form: "왜냐하면 opens the clause, closed by 아프다 → 아팠기 때문이에요" } },
    "마지막|noun": { korean: "마지막", note: "The last one in a sequence. It modifies directly: 마지막 날. For 'last' meaning previous, use 지난 — 지난주, not 마지막 주.", example: { ko: "오늘이 마지막 날이에요.", en: "Today is the last day.", form: "오늘 + 이 (subject); 마지막 + 날 + 이에요 (이다 after a batchim)" } },
    "에 관해|expression": { korean: "에 관해", note: "'Regarding', after a noun. Almost interchangeable with 에 대해, but slightly more formal and more common in writing. Before a noun: 에 관한.", example: { ko: "이 문제에 관해 말씀드릴게요.", en: "I will speak to you regarding this issue.", form: "문제 + 에 관해; 말씀드리다 → 말씀드릴게요 (humble intention)" } },
    "몇|determiner": { korean: "몇", note: "'How many' or 'a few', in front of a noun with a counter: 몇 사람, 몇 개. As a determiner it never takes a particle of its own.", example: { ko: "몇 사람이 왔어요?", en: "How many people came?", form: "몇 + 사람 + 이 (subject particle); 오다 → 왔어요 (past, question)" } },
    "어쩔 수 없어요|phrase": { korean: "어쩔 수 없어요", note: "'There is nothing to be done' — resignation about something outside your control. It excuses rather than apologises.", example: { ko: "비가 와서 어쩔 수 없어요.", en: "It is raining, so there is nothing to be done.", form: "어쩌다 → 어쩔 (modifier) + 수 없다 → 없어요 (impossibility)" } },
    "조각|counter": { korean: "조각", note: "The counter for slices and broken pieces: 케이크 한 조각, 피자 두 조각. Takes native Korean numbers.", example: { ko: "케이크 한 조각 주세요.", en: "Please give me a slice of cake.", form: "케이크 + 한 (native number) + 조각 (counter); 주다 → 주세요" } },
    "그럼|interjection": { korean: "그럼", note: "'Of course, sure', as a warm agreement — distinct from the connective 그럼 meaning 'then'. Tone and position separate them.", example: { ko: "그럼, 당연하죠.", en: "Of course, naturally.", form: "Interjection standing alone; 당연하다 → 당연하죠 (agreement-seeking)" } },
    "다니다|verb": { korean: "다니다", note: "To go somewhere regularly — to attend school, commute to work, frequent a place: 학교에 다녀요. It implies repetition, where 가다 is a single trip.", example: { ko: "회사에 다녀요.", en: "I work at a company. (I commute there.)", form: "회사 + 에 (destination); 다니다 → 다녀요 (present, polite casual)" } },
    "만|particle": { korean: "만", note: "'Only, just', attached to a noun: 물만 주세요. It replaces 은/는 and 이/가, and can stack in front of other particles: 저한테만.", example: { ko: "물만 주세요.", en: "Just water, please.", form: "물 + 만 (limiting particle, replacing the object particle); 주다 → 주세요" } },
    "에 반해|expression": { korean: "에 반해", note: "'In contrast to', after a noun — written register, setting up an opposition: 예상에 반해.", example: { ko: "예상에 반해 결과가 좋았어요.", en: "In contrast to expectations, the result was good.", form: "예상 + 에 반해; 좋다 → 좋았어요 (past, polite casual)" } },
    "건물|noun": { korean: "건물", note: "A building as a structure. 집 is a home and 빌딩 is a borrowed word for a tall office block; 건물 is the neutral term.", example: { ko: "저 건물이 아주 높아요.", en: "That building is very tall.", form: "건물 + 이 (subject); 높다 → 높아요 (present, polite casual)" } },
    "외국|noun": { korean: "외국", note: "A foreign country, from Korea's point of view. 외국에 가다 is to go abroad; a foreigner is 외국인 and a foreign language is 외국어.", example: { ko: "외국에서 공부하고 싶어요.", en: "I want to study abroad.", form: "외국 + 에서 (action-location); 공부하다 → 공부하고 싶어요 (-고 싶다)" } },
    "정보 통신|noun phrase": { korean: "정보 통신", note: "Information and communications, as in the IT sector. A set phrase in news and TOPIK reading about technology and industry.", example: { ko: "정보 통신 기술이 발전했어요.", en: "Information and communications technology has advanced.", form: "정보 통신 기술 + 이 (subject); 발전하다 → 발전했어요 (past)" } },
    "밑|noun": { korean: "밑", note: "The underneath, as noun + 밑에: 책상 밑에. 아래 covers the same ground and is slightly more formal; 밑 suggests direct contact underneath.", example: { ko: "책상 밑에 가방이 있어요.", en: "There is a bag under the desk.", form: "밑 + 에 (location particle); 있다 → 있어요" } },
    "로 인해|expression": { korean: "로 인해", note: "'Due to', after a noun — formal cause, common in news: 비로 인해 취소됐어요. 으로 인해 after a consonant.", example: { ko: "눈으로 인해 길이 막혔어요.", en: "The road was blocked due to snow.", form: "눈 + 으로 인해 (after a batchim); 막히다 → 막혔어요 (past)" } },
    "적다|adjective": { korean: "적다", note: "To be few or little in quantity. Its opposite is 많다. Do not confuse it with 작다 (small in size) — 돈이 적다 is 'little money', 돈이 작다 is wrong.", example: { ko: "사람이 적어요.", en: "There are few people.", form: "사람 + 이 (subject); 적다 → 적어요 (present, polite casual)" } },
    "어른|noun": { korean: "어른", note: "An adult, especially as someone deserving respect. 어른들 앞에서 means 'in front of one's elders'. 성인 is the legal-age term.", example: { ko: "어른한테 존댓말을 써요.", en: "I use polite speech to adults.", form: "어른 + 한테 (recipient); 존댓말 + 을 (object); 쓰다 → 써요" } },
    "조금|noun": { korean: "조금", note: "A small amount, used as a noun so it takes particles: 조금만 주세요, 조금씩. Contracts to 좀 in speech.", example: { ko: "조금만 주세요.", en: "Please give me just a little.", form: "조금 + 만 (only); 주다 → 주세요 (polite request)" } },
    "그럴 리가요|phrase": { korean: "그럴 리가요", note: "'That cannot be' — disbelief at news you find impossible. 리 is a bound noun meaning 'reason', so it literally denies there is any way.", example: { ko: "정말요? 그럴 리가요.", en: "Really? That cannot be.", form: "그렇다 → 그럴 (modifier) + 리 + 가 + 요 (fixed, trailing off)" } },
    "부터|particle": { korean: "부터", note: "'From', marking a starting point in time: 아홉 시부터. For a place, 에서 is the right particle. It pairs with 까지 for 'from ... to'.", example: { ko: "아홉 시부터 시작해요.", en: "It starts from nine o'clock.", form: "아홉 시 + 부터 (starting point); 시작하다 → 시작해요" } },
    "사탕|noun": { korean: "사탕", note: "Candy or a sweet, counted with 개. 설탕 (sugar) shares the 탕 element but is a different word.", example: { ko: "아이가 사탕을 좋아해요.", en: "The child likes candy.", form: "아이 + 가 (subject); 사탕 + 을 (object); 좋아하다 → 좋아해요" } },

    // ================================================================= day 9
    "담배|noun": { korean: "담배", note: "Tobacco or a cigarette. Smoking uses 피우다 — 담배를 피워요 — never 먹다 or 마시다.", example: { ko: "여기서 담배를 피우지 마세요.", en: "Please do not smoke here.", form: "담배 + 를 (object); 피우다 → 피우지 마세요 (prohibition)" } },
    "여보세요|interjection": { korean: "여보세요", note: "'Hello' on the telephone only — never face to face. It also works to get the attention of someone who is not responding.", example: { ko: "여보세요? 누구세요?", en: "Hello? Who is this?", form: "Fixed telephone greeting; 누구 + 시 (honorific) + 세요 (question)" } },
    "웃다|verb": { korean: "웃다", note: "To laugh or to smile — Korean does not split them, so context decides. Its opposite is 울다.", example: { ko: "아이가 크게 웃었어요.", en: "The child laughed loudly.", form: "아이 + 가 (subject); 웃다 → 웃었어요 (past, polite casual)" } },
    "환자|noun": { korean: "환자", note: "A patient in a medical sense. Counted with 명. The doctor is 의사 and the nurse 간호사.", example: { ko: "환자가 많아요.", en: "There are many patients.", form: "환자 + 가 (subject); 많다 → 많아요 (present, polite casual)" } },
    "대화|noun": { korean: "대화", note: "A conversation, slightly formal. 대화하다 is to converse, and the person takes 와/과. 이야기 is the everyday word.", example: { ko: "친구와 대화를 나눴어요.", en: "I had a conversation with a friend.", form: "친구 + 와 (with); 대화 + 를 (object); 나누다 → 나눴어요 (past)" } },
    "에 불과하다|expression": { korean: "에 불과하다", note: "'To be nothing more than', dismissing something as merely that: 소문에 불과해요. Written register, common in argument passages.", example: { ko: "그것은 소문에 불과해요.", en: "That is nothing more than a rumour.", form: "소문 + 에 불과하다 → 불과해요 (present, polite casual)" } },
    "어디|pronoun": { korean: "어디", note: "'Where', as a question word and as 'somewhere' in statements. The destination takes 에 (어디에 가요?) and the location of an action takes 에서 (어디에서 만나요?).", example: { ko: "어디에 가요?", en: "Where are you going?", form: "어디 + 에 (destination particle); 가다 → 가요 (question)" } },
    "못하다|auxiliary verb": { korean: "못하다", note: "-지 못하다, the long form of 못: 가지 못해요 = 못 가요. It marks inability, not choice, and is preferred in writing and with 하다 compounds.", example: { ko: "바빠서 가지 못했어요.", en: "I was busy so I could not go.", form: "가다 → 가지 (connector) + 못하다 → 못했어요 (inability, past)" } },
    "이제|adverb": { korean: "이제", note: "'Now', with a sense of change from before — 이제 그만하세요 means 'stop now, as of this point'. Plain 지금 lacks that contrast.", example: { ko: "이제 가야 해요.", en: "I have to go now.", form: "이제 before the verb; 가다 → 가야 해요 (obligation)" } },
    "떠나다|verb": { korean: "떠나다", note: "To leave a place, with a sense of departure rather than a short exit. The place left takes 을/를 or 에서: 한국을 떠났어요.", example: { ko: "내일 서울을 떠나요.", en: "I leave Seoul tomorrow.", form: "서울 + 을 (object); 떠나다 → 떠나요 (present, polite casual)" } },
    "까지|particle": { korean: "까지", note: "'Until' in time and 'as far as' in space: 다섯 시까지, 서울까지. It pairs with 부터 (time) and 에서 (place) for a range.", example: { ko: "다섯 시까지 기다릴게요.", en: "I will wait until five o'clock.", form: "다섯 시 + 까지 (end point); 기다리다 → 기다릴게요 (intention)" } },
    "모두|noun": { korean: "모두", note: "'Everyone' or 'the whole lot', used as a noun so it takes particles: 모두가 왔어요, 모두를 위해.", example: { ko: "모두가 기다리고 있어요.", en: "Everyone is waiting.", form: "모두 + 가 (subject); 기다리다 → 기다리고 있어요 (progressive)" } },
    "말도 안 돼요|phrase": { korean: "말도 안 돼요", note: "'That makes no sense' or 'no way' — strong disbelief or objection. Literally 'it does not even become words'. Too blunt for a superior.", example: { ko: "말도 안 돼요!", en: "That is ridiculous!", form: "말 + 도 (even) + 안 + 되다 → 안 돼요 (negated present)" } },
    "에 달려 있다|expression": { korean: "에 달려 있다", note: "'To depend on', after a noun: 날씨에 달려 있어요. The thing depended on takes 에, never 을/를.", example: { ko: "결과는 노력에 달려 있어요.", en: "The result depends on effort.", form: "노력 + 에 달려 있다 → 있어요 (present, polite casual)" } },
    "제일|noun": { korean: "제일", note: "'The best' or 'the first' as a noun. Far more often it works as an adverb making a superlative: 제일 좋아요.", example: { ko: "건강이 제일이에요.", en: "Health is the most important thing.", form: "건강 + 이 (subject); 제일 + 이에요 (이다 after a batchim)" } },
    "한강|proper noun": { korean: "한강", note: "The Han River, running through Seoul. Its parks are a default meeting place, so it appears constantly in dialogues about weekends.", example: { ko: "한강에서 자전거를 탔어요.", en: "I rode a bicycle at the Han River.", form: "한강 + 에서 (action-location); 타다 → 탔어요 (past)" } },
    "일자리 창출|noun phrase": { korean: "일자리 창출", note: "Job creation, a set phrase from economic and policy writing. 일자리 is a position of employment, as against 일 for work itself.", example: { ko: "일자리 창출이 중요해요.", en: "Job creation is important.", form: "일자리 창출 + 이 (subject); 중요하다 → 중요해요" } },
    "해|noun": { korean: "해", note: "A year, and also the sun. 해가 뜨다 is 'the sun rises'; 새해 is the new year. For counting years, 년 with Sino-Korean numbers is standard.", example: { ko: "새해 복 많이 받으세요.", en: "Happy New Year.", form: "새 + 해; fixed New Year greeting; 받다 → 받으세요 (polite request)" } },
    "세|determiner": { korean: "세", note: "'Three' in front of a counter: 세 개, 세 명, 세 시. The native numbers 하나/둘/셋/넷 all shorten before a counter — 한, 두, 세, 네.", example: { ko: "사과 세 개 주세요.", en: "Please give me three apples.", form: "세 (shortened from 셋) + 개 (counter); 주다 → 주세요" } },
    "을 막론하고|expression": { korean: "을 막론하고", note: "'Regardless of', after a noun — formal and written: 남녀노소를 막론하고. 를 막론하고 after a vowel.", example: { ko: "나이를 막론하고 누구나 할 수 있어요.", en: "Regardless of age, anyone can do it.", form: "나이 + 를 막론하고; 하다 → 할 수 있어요 (possibility)" } },
    "달|dependent noun": { korean: "달", note: "The counter for months, with native Korean numbers: 한 달, 두 달. Its Sino-Korean partner is 개월 — 일 개월, 이 개월 — and the two systems must not be mixed.", example: { ko: "한 달 동안 여행했어요.", en: "I travelled for a month.", form: "한 (native number) + 달 + 동안 (duration); 여행하다 → 여행했어요" } },
    "값|noun": { korean: "값", note: "A price or value. 값이 비싸다 / 싸다 for expensive and cheap. 가격 is the more formal equivalent used on labels.", example: { ko: "값이 너무 비싸요.", en: "The price is too high.", form: "값 + 이 (subject); 비싸다 → 비싸요 (present, polite casual)" } },
    "마다|particle": { korean: "마다", note: "'Every', attached to a noun: 날마다, 사람마다. It replaces the subject and object particles rather than stacking with them.", example: { ko: "날마다 운동해요.", en: "I exercise every day.", form: "날 + 마다 (every); 운동하다 → 운동해요 (present, polite casual)" } },
    "그러므로|conjunction": { korean: "그러므로", note: "'Therefore', drawing a conclusion — formal and written, the register of essays and reports. In speech, 그래서.", example: { ko: "증거가 없어요. 그러므로 사실이 아니에요.", en: "There is no evidence. Therefore it is not true.", form: "그러므로 opens the conclusion; 이다 → 아니에요 (negated)" } },
    "어린이|noun": { korean: "어린이", note: "A child, the formal and institutional word — 어린이날 (Children's Day), 어린이집 (daycare). 아이 is what people say in conversation.", example: { ko: "어린이날은 오월 오일이에요.", en: "Children's Day is the fifth of May.", form: "어린이날 + 은 (topic); 오월 오일 + 이에요 (Sino-Korean date)" } },
    "척|counter": { korean: "척", note: "The counter for ships and boats: 배 한 척. Takes native Korean numbers. Rare in speech but standard in written descriptions.", example: { ko: "배 두 척이 보여요.", en: "Two ships are visible.", form: "배 + 두 (native number) + 척 (counter) + 이 (subject); 보이다 → 보여요" } },
    "안녕|interjection": { korean: "안녕", note: "'Hi' and 'bye', casual — for friends, children and juniors only. To anyone else, say 안녕하세요. It works for both arriving and leaving.", example: { ko: "안녕! 내일 봐.", en: "Bye! See you tomorrow.", form: "Casual greeting; 보다 → 봐 (casual, plain)" } },
    "그러게요|phrase": { korean: "그러게요", note: "'I know, right' — agreeing with a remark, often a complaint. It signals shared feeling rather than adding information.", example: { ko: "날씨가 춥네요. 그러게요.", en: "It is cold, isn't it. I know, right.", form: "그러다 → 그러게요 (agreement, polite casual)" } },
    "말씀|noun": { korean: "말씀", note: "The honorific of 말, working two ways: elevating someone else's words (선생님 말씀) and humbling your own (말씀드릴게요). Both are polite.", example: { ko: "선생님 말씀을 들었어요.", en: "I heard what the teacher said.", form: "말씀 + 을 (object); 듣다 → 들었어요 (ㄷ-irregular, past)" } },
    "에도 불구하고|expression": { korean: "에도 불구하고", note: "'In spite of', after a noun — formal and written: 노력에도 불구하고. After a verb it becomes -는데도 불구하고.", example: { ko: "노력에도 불구하고 실패했어요.", en: "In spite of the effort, it failed.", form: "노력 + 에도 불구하고; 실패하다 → 실패했어요 (past)" } },

    // ================================================================ day 10
    "눈물|noun": { korean: "눈물", note: "A tear. Tears come out with 나다 — 눈물이 나요 — not 오다. 눈물을 흘리다 is 'to shed tears'.", example: { ko: "눈물이 났어요.", en: "Tears came to my eyes.", form: "눈물 + 이 (subject); 나다 → 났어요 (past, polite casual)" } },
    "주인|noun": { korean: "주인", note: "The owner of a thing or a shop, and the host of a gathering. 주인공 is the protagonist of a story, a separate word.", example: { ko: "이 가게 주인이 친절해요.", en: "The owner of this shop is kind.", form: "가게 주인 + 이 (subject); 친절하다 → 친절해요" } },
    "반|noun": { korean: "반", note: "Two senses: half (한 시간 반 = an hour and a half) and a class group at school (우리 반). Context separates them cleanly.", example: { ko: "한 시간 반 걸려요.", en: "It takes an hour and a half.", form: "한 시간 + 반; 걸리다 → 걸려요 (present, polite casual)" } },
    "귀|noun": { korean: "귀", note: "The ear. 귀가 아프다 for earache. 귀엽다 (cute) merely looks similar and is unrelated.", example: { ko: "귀가 아파요.", en: "My ear hurts.", form: "귀 + 가 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "아파트|noun": { korean: "아파트", note: "An apartment building or a flat in one — the standard form of Korean housing, so it is far more common than 집 in city contexts. Counted with 채 or 동 for blocks.", example: { ko: "저는 아파트에 살아요.", en: "I live in an apartment.", form: "아파트 + 에 (location); 살다 → 살아요 (present, polite casual)" } },
    "기 마련이다|expression": { korean: "기 마련이다", note: "'To be bound to happen', stating something as natural and inevitable. Attach 기 to the verb stem: 실수하기 마련이에요.", example: { ko: "사람은 실수하기 마련이에요.", en: "People are bound to make mistakes.", form: "실수하다 → 실수하기 (nominalised) + 마련이다 → 마련이에요" } },
    "돌아오다|verb": { korean: "돌아오다", note: "To come back, toward the speaker. Its mirror 돌아가다 is going back away from the speaker — and 돌아가시다 is the honorific for dying.", example: { ko: "언제 돌아와요?", en: "When are you coming back?", form: "언제 + 돌아오다 → 돌아와요 (present, polite casual, question)" } },
    "처럼|particle": { korean: "처럼", note: "'Like', comparing to a noun: 아이처럼 웃어요. 같이 does the same job and is slightly more casual. It attaches directly with no other particle.", example: { ko: "아이처럼 웃어요.", en: "She laughs like a child.", form: "아이 + 처럼 (comparison); 웃다 → 웃어요 (present, polite casual)" } },
    "달러|dependent noun": { korean: "달러", note: "Dollar, following a Sino-Korean number: 십 달러. Korean currency 원 works the same way.", example: { ko: "십 달러예요.", en: "It is ten dollars.", form: "십 (Sino-Korean) + 달러; 이다 → 예요 (after a vowel)" } },
    "잔|noun": { korean: "잔", note: "A cup or glass, and the counter for drinks served in one: 커피 한 잔, 물 두 잔. Takes native Korean numbers.", example: { ko: "커피 한 잔 주세요.", en: "Please give me a cup of coffee.", form: "커피 + 한 (native number) + 잔 (counter); 주다 → 주세요" } },
    "저|determiner": { korean: "저", note: "'That over there', for something distant from both speaker and listener. Completes the set 이 / 그 / 저. Do not confuse it with the pronoun 저 (I).", example: { ko: "저 건물이 뭐예요?", en: "What is that building over there?", form: "저 + 건물 + 이 (subject); 뭐 + 예요 (question)" } },
    "오르다|verb": { korean: "오르다", note: "To go up — a mountain, a price, a temperature. 르-irregular: 올라요. The mountain takes 에 (산에 오르다).", example: { ko: "값이 많이 올랐어요.", en: "The price has gone up a lot.", form: "값 + 이 (subject); 오르다 → 올랐어요 (르-irregular, past)" } },
    "뉴스|noun": { korean: "뉴스", note: "The news, on television or online. You watch it with 보다 and hear it with 듣다; 소식 is news in the sense of tidings about a person.", example: { ko: "저녁에 뉴스를 봐요.", en: "I watch the news in the evening.", form: "저녁 + 에 (time); 뉴스 + 를 (object); 보다 → 봐요" } },
    "는 바람에|expression": { korean: "는 바람에", note: "'Because of', but only for an unwanted or unexpected result: 늦게 일어나는 바람에 지각했어요. It never takes a good outcome.", example: { ko: "비가 오는 바람에 늦었어요.", en: "I was late because it rained.", form: "오다 → 오는 (present modifier) + 바람에; 늦다 → 늦었어요 (past)" } },
    "그런 것 같아요|phrase": { korean: "그런 것 같아요", note: "'I think so' — the standard Korean hedge. Koreans reach for -것 같다 far more than English reaches for 'I think', because a flat assertion sounds too strong.", example: { ko: "네, 그런 것 같아요.", en: "Yes, I think so.", form: "그렇다 → 그런 (modifier) + 것 같다 → 같아요 (supposition)" } },
    "백두산|proper noun": { korean: "백두산", note: "Mount Baekdu, on the North Korea–China border and the highest peak on the peninsula. It carries strong symbolic weight in Korean identity and appears in the national anthem.", example: { ko: "백두산은 한국에서 가장 높아요.", en: "Mount Baekdu is the highest in Korea.", form: "백두산 + 은 (topic); 가장 + 높다 → 높아요 (superlative)" } },
    "세대 차이|noun phrase": { korean: "세대 차이", note: "The generation gap, a set phrase common in TOPIK reading about family and society. 세대 is a generation, 차이 a difference.", example: { ko: "세대 차이를 느껴요.", en: "I feel the generation gap.", form: "세대 차이 + 를 (object); 느끼다 → 느껴요 (present, polite casual)" } },
    "놓다|verb": { korean: "놓다", note: "To put something down and leave it there. Where it goes takes 에: 책상에 놓았어요. Compare 넣다, which puts something inside a container.", example: { ko: "책을 책상에 놓았어요.", en: "I put the book on the desk.", form: "책 + 을 (object); 책상 + 에 (destination); 놓다 → 놓았어요 (past)" } },
    "층|noun": { korean: "층", note: "A floor of a building, with Sino-Korean numbers: 삼 층. It doubles as the counter, so 삼 층 is both 'third floor' and 'three floors'.", example: { ko: "사무실은 삼 층에 있어요.", en: "The office is on the third floor.", form: "삼 (Sino-Korean) + 층 + 에 (location); 있다 → 있어요" } },
    "통|counter": { korean: "통", note: "The counter for letters, phone calls and bucket-like containers: 편지 한 통, 전화 두 통. Takes native Korean numbers.", example: { ko: "편지 한 통을 받았어요.", en: "I received a letter.", form: "편지 + 한 (native number) + 통 + 을 (object); 받다 → 받았어요" } },
    "아니|interjection": { korean: "아니", note: "Casual 'no', and also an exclamation of surprise — 아니, 벌써? = 'what, already?'. As a refusal it is friends-only; use 아니요 otherwise.", example: { ko: "아니, 벌써 왔어?", en: "What, you are here already?", form: "Interjection opening the clause; 오다 → 왔어 (past, casual)" } },
    "같이|particle": { korean: "같이", note: "'Like', attached to a noun for comparison: 눈같이 하얘요. Same job as 처럼. Do not confuse it with the adverb 같이 meaning 'together'.", example: { ko: "눈같이 하얘요.", en: "It is white like snow.", form: "눈 + 같이 (comparison); 하얗다 → 하얘요 (ㅎ-irregular, present)" } },
    "는 김에|expression": { korean: "는 김에", note: "'While you are at it', taking the chance created by one action to do another: 나가는 김에 우유 좀 사 와요.", example: { ko: "나가는 김에 우유를 샀어요.", en: "While I was out, I bought milk.", form: "나가다 → 나가는 (present modifier) + 김에; 사다 → 샀어요 (past)" } },
    "그럼|conjunction": { korean: "그럼", note: "'Then, in that case', the spoken contraction of 그러면. It draws a consequence from what was just said: 그럼 내일 만나요.", example: { ko: "그럼 내일 만나요.", en: "Then let us meet tomorrow.", form: "그럼 opens the clause; 만나다 → 만나요 (suggestion, polite casual)" } },
    "개월|dependent noun": { korean: "개월", note: "The counter for months with Sino-Korean numbers: 일 개월, 삼 개월. Its native partner is 달 — 한 달, 세 달. Never mix the systems.", example: { ko: "삼 개월 동안 배웠어요.", en: "I studied for three months.", form: "삼 (Sino-Korean) + 개월 + 동안 (duration); 배우다 → 배웠어요" } },
    "팔|noun": { korean: "팔", note: "The arm. The identical 팔 meaning Sino-Korean eight is a separate entry — context and position make it clear which is meant.", example: { ko: "팔이 아파요.", en: "My arm hurts.", form: "팔 + 이 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "설명|noun": { korean: "설명", note: "An explanation. 설명하다 is to explain, and the thing explained takes 을/를: 문법을 설명해요.", example: { ko: "설명이 어려워요.", en: "The explanation is difficult.", form: "설명 + 이 (subject); 어렵다 → 어려워요 (ㅂ-irregular, present)" } },
    "비슷하다|adjective": { korean: "비슷하다", note: "To be similar. What it resembles takes 와/과 or 하고: 형과 비슷해요. 같다 means identical, so the two are not interchangeable.", example: { ko: "동생하고 비슷해요.", en: "He is similar to my younger brother.", form: "동생 + 하고 (with); 비슷하다 → 비슷해요 (present, polite casual)" } },
    "티브이|noun": { korean: "티브이", note: "TV, the spoken short form of 텔레비전, written out phonetically. Watched with 보다.", example: { ko: "티브이를 보고 있어요.", en: "I am watching TV.", form: "티브이 + 를 (object); 보다 → 보고 있어요 (progressive, present)" } },
    "바꾸다|verb": { korean: "바꾸다", note: "To change or exchange one thing for another. The replacement takes 로/으로: 큰 걸로 바꿔 주세요. For something changing by itself, use 바뀌다.", example: { ko: "이걸로 바꿔 주세요.", en: "Please change it for this one.", form: "이거 + 로 (replacement); 바꾸다 → 바꿔 + 주다 → 주세요 (request)" } },
    "는 대로|expression": { korean: "는 대로", note: "'As soon as' after a verb stem: 도착하는 대로 전화할게요. After a noun it means 'in accordance with': 계획대로.", example: { ko: "도착하는 대로 전화할게요.", en: "I will call as soon as I arrive.", form: "도착하다 → 도착하는 (present modifier) + 대로; 전화하다 → 전화할게요" } },
    "잘 될 거예요|phrase": { korean: "잘 될 거예요", note: "'It will work out' — the standard reassurance to someone worried. 잘 되다 is 'to go well', and -을 거예요 makes it a prediction.", example: { ko: "걱정 마세요. 잘 될 거예요.", en: "Do not worry. It will work out.", form: "되다 → 될 (modifier) + 거예요 (supposition, polite casual)" } },

    // ================================================================ day 11
    "어깨|noun": { korean: "어깨", note: "The shoulder. 어깨가 아프다 for a sore shoulder; 어깨가 무겁다 is idiomatic for feeling burdened by responsibility.", example: { ko: "어깨가 아파요.", en: "My shoulder hurts.", form: "어깨 + 가 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "새|determiner": { korean: "새", note: "'New', in front of a noun: 새 옷, 새 차. It never conjugates and never takes a particle. The adjective 새롭다 is used to end a sentence instead.", example: { ko: "새 옷을 샀어요.", en: "I bought new clothes.", form: "새 + 옷 + 을 (object particle); 사다 → 샀어요 (past)" } },
    "새|noun": { korean: "새", note: "A bird, counted with 마리. Identical in spelling to the determiner 새 (new), but that one always sits in front of a noun.", example: { ko: "새가 날아가요.", en: "A bird is flying away.", form: "새 + 가 (subject); 날아가다 → 날아가요 (present, polite casual)" } },
    "부부|noun": { korean: "부부", note: "A married couple as a unit: 우리 부부. Counted with 쌍. For a dating couple, 커플 is the borrowed word used.", example: { ko: "저 부부는 사이가 좋아요.", en: "That couple gets on well.", form: "부부 + 는 (topic); 사이 + 가 (subject); 좋다 → 좋아요" } },
    "보다|particle": { korean: "보다", note: "'Than', attached to the thing compared: 저보다 커요 = taller than me. It usually pairs with 더 for emphasis, and the order is the reverse of English.", example: { ko: "형이 저보다 커요.", en: "My older brother is taller than me.", form: "저 + 보다 (comparison particle); 크다 → 커요 (ㅡ drops)" } },
    "는 반면에|expression": { korean: "는 반면에", note: "'Whereas, on the other hand', contrasting two clauses: 값은 싼 반면에 질이 나빠요. Adjectives take -은 반면에.", example: { ko: "값은 싼 반면에 질이 나빠요.", en: "It is cheap, but on the other hand the quality is poor.", form: "싸다 → 싼 (adjective modifier) + 반면에; 나쁘다 → 나빠요" } },
    "공|noun": { korean: "공", note: "A ball, counted with 개. 공을 차다 is to kick it, 공을 던지다 to throw it. The identical 공 meaning zero is a separate word.", example: { ko: "공을 던졌어요.", en: "I threw the ball.", form: "공 + 을 (object); 던지다 → 던졌어요 (past, polite casual)" } },
    "이거|pronoun": { korean: "이거", note: "'This thing', the spoken contraction of 이것. It fuses with particles: 이거 + 이 becomes 이게, 이거 + 는 becomes 이건.", example: { ko: "이게 뭐예요?", en: "What is this?", form: "이거 + 가 → 이게 (contracted subject); 뭐 + 예요 (question)" } },
    "미터|dependent noun": { korean: "미터", note: "Metre, following a Sino-Korean number: 백 미터. Distances in Korea are otherwise given in 킬로미터.", example: { ko: "백 미터를 달렸어요.", en: "I ran a hundred metres.", form: "백 (Sino-Korean) + 미터 + 를 (object); 달리다 → 달렸어요" } },
    "과|noun": { korean: "과", note: "A lesson or chapter in a textbook (제1과), and a department at a university or hospital (영어과, 내과). The particle 과 meaning 'and' is separate.", example: { ko: "오늘은 삼 과를 공부해요.", en: "Today we study lesson three.", form: "삼 (Sino-Korean) + 과 + 를 (object); 공부하다 → 공부해요" } },
    "남녀 차별|noun phrase": { korean: "남녀 차별", note: "Gender discrimination, a set phrase in social-issue reading. 차별 is discrimination generally; 구별 means a neutral distinction and is not a synonym.", example: { ko: "남녀 차별이 아직 있어요.", en: "Gender discrimination still exists.", form: "남녀 차별 + 이 (subject); 아직 + 있다 → 있어요" } },
    "남녀|noun": { korean: "남녀", note: "Men and women as a pair, used in compounds: 남녀 차별, 남녀노소 (people of all ages and both sexes). Rarely stands alone.", example: { ko: "남녀 모두 참가할 수 있어요.", en: "Both men and women can take part.", form: "남녀 + 모두; 참가하다 → 참가할 수 있어요 (possibility)" } },
    "사월|noun": { korean: "사월", note: "April. Months are Sino-Korean number + 월. Watch the two irregulars: June is 유월, not 육월, and October is 시월, not 십월.", example: { ko: "사월에 꽃이 피어요.", en: "Flowers bloom in April.", form: "사월 + 에 (time particle); 피다 → 피어요 (present, polite casual)" } },
    "봉지|counter": { korean: "봉지", note: "The counter for bags and packets of things: 과자 한 봉지, 라면 두 봉지. Takes native Korean numbers.", example: { ko: "과자 한 봉지 샀어요.", en: "I bought a packet of snacks.", form: "과자 + 한 (native number) + 봉지 (counter); 사다 → 샀어요" } },
    "음|interjection": { korean: "음", note: "'Hmm' — thinking aloud, or acknowledging what you heard while you consider it. Neutral in politeness.", example: { ko: "음, 생각해 볼게요.", en: "Hmm, I will think about it.", form: "Interjection; 생각하다 → 생각해 + 보다 → 볼게요 (trying, intention)" } },
    "기 위해서|expression": { korean: "기 위해서", note: "'In order to', after a verb stem: 배우기 위해서 왔어요. Both clauses must share a subject. After a noun, use 을/를 위해서.", example: { ko: "한국어를 배우기 위해서 왔어요.", en: "I came in order to learn Korean.", form: "배우다 → 배우기 (nominalised) + 위해서; 오다 → 왔어요 (past)" } },
    "나중|noun": { korean: "나중", note: "'Later', almost always as 나중에. 나중에 봐요 is a standard casual goodbye. It is vaguer than 다음에, which implies a next specific occasion.", example: { ko: "나중에 전화할게요.", en: "I will call you later.", form: "나중 + 에 (time particle); 전화하다 → 전화할게요 (intention)" } },
    "며칠|noun": { korean: "며칠", note: "Two jobs: 'a few days' (며칠 걸려요) and 'what date' (오늘 며칠이에요?). Spelled 며칠, never 몇일, despite the meaning.", example: { ko: "오늘 며칠이에요?", en: "What is the date today?", form: "며칠 + 이에요 (이다 after a batchim; question)" } },
    "힘내세요|phrase": { korean: "힘내세요", note: "'Cheer up, hang in there' — encouragement to someone struggling. Literally 'produce strength'. Warmer than 화이팅 and safe with a superior.", example: { ko: "조금만 더 힘내세요.", en: "Hang in there just a little longer.", form: "힘 + 내다 → 내세요 (polite request, used as encouragement)" } },
    "그래도|conjunction": { korean: "그래도", note: "'Still, even so', conceding the previous point but holding your position: 비싸요. 그래도 살 거예요.", example: { ko: "비싸요. 그래도 살 거예요.", en: "It is expensive. Even so, I will buy it.", form: "그래도 opens the clause; 사다 → 살 거예요 (intention, polite casual)" } },
    "작년|noun": { korean: "작년", note: "Last year. The set runs 작년 / 올해 / 내년, and note that 올해 breaks the pattern — it is not 금년 in speech.", example: { ko: "작년에 한국에 왔어요.", en: "I came to Korea last year.", form: "작년 + 에 (time particle); 오다 → 왔어요 (past, polite casual)" } },
    "밖에|particle": { korean: "밖에", note: "'Only', but it requires a negative verb: 천 원밖에 없어요 = 'I only have a thousand won'. Using it with a positive verb is ungrammatical. 만 takes a positive verb instead.", example: { ko: "천 원밖에 없어요.", en: "I only have a thousand won.", form: "천 원 + 밖에 (requires a negative); 없다 → 없어요" } },
    "괜찮다|adjective": { korean: "괜찮다", note: "To be okay. It covers three jobs: 'I am fine', 'that is acceptable', and as a reply to thanks or apology, 'no problem'. 괜찮아요? is the standard 'are you all right?'.", example: { ko: "괜찮아요, 걱정하지 마세요.", en: "It is fine, do not worry.", form: "괜찮다 → 괜찮아요 (present, polite casual)" } },
    "잘하다|verb": { korean: "잘하다", note: "To do well or be good at something. Written as one word. What you are good at takes 을/를: 한국어를 잘해요. Its opposite is 못하다.", example: { ko: "노래를 잘해요.", en: "She sings well.", form: "노래 + 를 (object); 잘하다 → 잘해요 (여-irregular, present)" } },
    "못하다|verb": { korean: "못하다", note: "To be worse or not as good — a comparison, not an inability: 저보다 못해요. The inability sense belongs to the auxiliary -지 못하다.", example: { ko: "제 실력이 형보다 못해요.", en: "My skill is worse than my brother's.", form: "실력 + 이 (subject); 형 + 보다 (comparison); 못하다 → 못해요" } },
    "기 때문에|expression": { korean: "기 때문에", note: "'Because', after a verb or adjective stem: 바쁘기 때문에 못 가요. It states a firm reason, and unlike -아서/어서 it cannot be used with a request or suggestion.", example: { ko: "바쁘기 때문에 못 가요.", en: "I cannot go because I am busy.", form: "바쁘다 → 바쁘기 (nominalised) + 때문에; 못 + 가다 → 못 가요" } },
    "전|determiner": { korean: "전", note: "'Previous, former', in front of a noun: 전 남편, 전 대통령. Distinct from the noun 전 meaning 'before' in time, which follows a duration.", example: { ko: "전 직장이 더 좋았어요.", en: "My previous workplace was better.", form: "전 + 직장 + 이 (subject); 좋다 → 좋았어요 (past, polite casual)" } },
    "술|dependent noun": { korean: "술", note: "The counter for spoonfuls: 밥 한 술. Rare, and unrelated to 술 meaning alcohol despite the identical spelling.", example: { ko: "밥 한 술만 먹었어요.", en: "I ate only a spoonful of rice.", form: "밥 + 한 (native number) + 술 + 만 (only); 먹다 → 먹었어요" } },
    "이곳|pronoun": { korean: "이곳", note: "'This place, here' — the written equivalent of 여기. Completes the set 이곳 / 그곳 / 저곳, matching 여기 / 거기 / 저기 in speech.", example: { ko: "이곳이 제 고향이에요.", en: "This place is my hometown.", form: "이곳 + 이 (subject); 고향 + 이에요 (이다 after a batchim)" } },
    "는 덕분에|expression": { korean: "는 덕분에", note: "'Thanks to', and only for a good outcome — the mirror of -는 바람에, which takes a bad one. After a noun: 덕분에.", example: { ko: "도와주신 덕분에 잘 끝났어요.", en: "Thanks to your help, it ended well.", form: "도와주다 + 시 → 도와주신 (past honorific modifier) + 덕분에; 끝나다 → 끝났어요" } },
    "허리|noun": { korean: "허리", note: "The waist and lower back together — Korean does not split them, so 허리가 아파요 covers both backache and a sore waist.", example: { ko: "허리가 아파요.", en: "My back hurts.", form: "허리 + 가 (subject); 아프다 → 아파요 (ㅡ drops before -아요)" } },
    "어떠하다|adjective": { korean: "어떠하다", note: "'To be how, of what sort' — the full written form of 어떻다. In speech you will only meet the contraction; this form appears in formal writing and set questions.", example: { ko: "결과가 어떠했어요?", en: "How was the result?", form: "어떠하다 → 어떠했어요 (past, polite casual, question)" } },
    "이해하다|verb": { korean: "이해하다", note: "To understand. What you understand takes 을/를: 설명을 이해했어요. For 'I see' in conversation, Koreans say 알겠어요 rather than 이해해요.", example: { ko: "설명을 이해했어요.", en: "I understood the explanation.", form: "설명 + 을 (object); 이해하다 → 이해했어요 (past, polite casual)" } },
    "조차|particle": { korean: "조차", note: "'Even', marking something unexpected and usually paired with a negative: 물조차 없어요. It carries a note of dismay that 도 lacks.", example: { ko: "물조차 없었어요.", en: "There was not even water.", form: "물 + 조차 (even, with a negative); 없다 → 없었어요 (past)" } },
    // ------------------------------------------------ day 8, stragglers
    "을 비롯해|expression": { korean: "을 비롯해", note: "'Including, starting with', naming the leading example of a group: 서울을 비롯해 여러 도시. 를 비롯해 after a vowel. Written register.", example: { ko: "서울을 비롯해 여러 도시에 눈이 왔어요.", en: "It snowed in several cities including Seoul.", form: "서울 + 을 비롯해; 오다 → 왔어요 (past, polite casual)" } },
    "그날|noun": { korean: "그날", note: "'That day', pointing back at a day already mentioned. Written solid; 그 날 with a space is a rarer literal reading.", example: { ko: "그날 비가 많이 왔어요.", en: "It rained a lot that day.", form: "그날 opens the clause; 오다 → 왔어요 (past, polite casual)" } },
    "그러니까|conjunction": { korean: "그러니까", note: "'So, that is to say' — either drawing a consequence or rephrasing what you just said more clearly. Very common as a spoken filler while you restate.", example: { ko: "그러니까 내일 못 온다는 거죠?", en: "So you are saying you cannot come tomorrow?", form: "그러니까 opens the clause; 오다 → 못 온다는 거죠 (reported, seeking confirmation)" } },

    // ================================================================ day 12
    "조심하세요|phrase": { korean: "조심하세요", note: "'Please be careful' — said when parting in bad weather, or warning of a hazard. 조심히 가세요 is the version for someone heading off.", example: { ko: "길이 미끄러워요. 조심하세요.", en: "The road is slippery. Please be careful.", form: "조심하다 → 조심하세요 (polite request)" } },
    "달|noun": { korean: "달", note: "The moon, and a month as a period. 달이 밝다 for a bright moon; 이번 달 for this month. The counter 달 is a separate entry.", example: { ko: "오늘 달이 밝아요.", en: "The moon is bright tonight.", form: "달 + 이 (subject); 밝다 → 밝아요 (present, polite casual)" } },
    "는 탓에|expression": { korean: "는 탓에", note: "'Owing to', and it assigns blame — only for bad outcomes: 늦게 일어난 탓에 지각했어요. Its positive mirror is -는 덕분에.", example: { ko: "늦게 일어난 탓에 지각했어요.", en: "I was late owing to getting up late.", form: "일어나다 → 일어난 (past modifier) + 탓에; 지각하다 → 지각했어요" } },
    "돌아가다|verb": { korean: "돌아가다", note: "To go back, away from the speaker. Note the honorific 돌아가시다 means 'to pass away', so use it carefully — 할아버지가 돌아가셨어요 is not about travel.", example: { ko: "고향에 돌아가고 싶어요.", en: "I want to go back to my hometown.", form: "고향 + 에 (destination); 돌아가다 → 돌아가고 싶어요 (-고 싶다)" } },
    "상자|counter": { korean: "상자", note: "The counter for boxes: 사과 한 상자. Takes native Korean numbers. It is also the noun 'box' on its own.", example: { ko: "사과 한 상자를 샀어요.", en: "I bought a box of apples.", form: "사과 + 한 (native number) + 상자 + 를 (object); 사다 → 샀어요" } },
    "응|interjection": { korean: "응", note: "Casual 'yeah' — friends and juniors only. Saying it to an elder is rude; use 네. Its negative partner is 아니.", example: { ko: "응, 알았어.", en: "Yeah, got it.", form: "Casual interjection; 알다 → 알았어 (past, casual)" } },
    "장|dependent noun": { korean: "장", note: "The bound-noun form of the flat-sheet counter: 종이 두 장, 표 세 장. Takes native Korean numbers.", example: { ko: "종이 두 장 주세요.", en: "Please give me two sheets of paper.", form: "종이 + 두 (native number) + 장; 주다 → 주세요" } },
    "싶다|auxiliary verb": { korean: "싶다", note: "-고 싶다 expresses a wish: 가고 싶어요. It only works for your own desire — for someone else's you must use -고 싶어하다: 친구가 가고 싶어해요.", example: { ko: "한국에 가고 싶어요.", en: "I want to go to Korea.", form: "가다 → 가고 (connector) + 싶다 → 싶어요 (desire, present, polite casual)" } },
    "북한|proper noun": { korean: "북한", note: "North Korea, as South Koreans call it. The North calls itself 조선. South Korea is 남한 or, in daily speech, simply 한국.", example: { ko: "북한과 남한은 언어가 조금 달라요.", en: "North and South Korea differ a little in language.", form: "북한 + 과 (and); 언어 + 가 (subject); 다르다 → 달라요 (르-irregular)" } },
    "빈부 격차|noun phrase": { korean: "빈부 격차", note: "The gap between rich and poor — a set phrase in social-issue reading. 격차 is a gap or disparity generally.", example: { ko: "빈부 격차가 커지고 있어요.", en: "The gap between rich and poor is widening.", form: "빈부 격차 + 가 (subject); 커지다 → 커지고 있어요 (progressive)" } },
    "키|noun": { korean: "키", note: "A person's height. 키가 크다 is 'tall' and 키가 작다 is 'short' — never 높다, which is for buildings and mountains.", example: { ko: "동생은 키가 커요.", en: "My younger sibling is tall.", form: "동생 + 은 (topic); 키 + 가 (subject); 크다 → 커요 (ㅡ drops)" } },
    "그러자|conjunction": { korean: "그러자", note: "'And then, thereupon' — the second event follows immediately from the first, in narration. Past tense only, and mostly written.", example: { ko: "문을 열었어요. 그러자 고양이가 들어왔어요.", en: "I opened the door. Thereupon a cat came in.", form: "그러자 opens the clause; 들어오다 → 들어왔어요 (past)" } },
    "을 뿐만 아니라|expression": { korean: "을 뿐만 아니라", note: "'Not only ... but also', after a verb or adjective modifier: 예쁠 뿐만 아니라 착해요. After a noun it is 뿐만 아니라 directly.", example: { ko: "값이 쌀 뿐만 아니라 질도 좋아요.", en: "Not only is it cheap, the quality is good too.", form: "싸다 → 쌀 (modifier) + 뿐만 아니라; 좋다 → 좋아요" } },
    "아무|determiner": { korean: "아무", note: "'Any' in a positive sentence and 'no' with a negative: 아무 문제 없어요 = 'no problem at all'. It always sits in front of a noun.", example: { ko: "아무 문제 없어요.", en: "There is no problem at all.", form: "아무 + 문제; 없다 → 없어요 (negative existence)" } },
    "아무|pronoun": { korean: "아무", note: "'Anyone' or, with a negative, 'no one': 아무도 몰라요. As a subject it is nearly always 아무도, since the bare form is rare.", example: { ko: "아무도 몰라요.", en: "Nobody knows.", form: "아무 + 도 (with a negative); 모르다 → 몰라요 (르-irregular)" } },
    "마저|particle": { korean: "마저", note: "'Even, down to the last one', marking the final item in a losing sequence: 너마저 가면 어떡해. It carries more resignation than 도 or 조차.", example: { ko: "너마저 나를 떠나니?", en: "Even you are leaving me?", form: "너 + 마저 (even, final item); 떠나다 → 떠나니 (casual question)" } },
    "근처|noun": { korean: "근처", note: "The vicinity, as noun + 근처에: 학교 근처에 있어요. 가까이 is the adverb 'nearby' and does not take a preceding noun the same way.", example: { ko: "학교 근처에 살아요.", en: "I live near the school.", form: "근처 + 에 (location particle); 살다 → 살아요 (present, polite casual)" } },
    "그곳|pronoun": { korean: "그곳", note: "'That place' — the written equivalent of 거기. Part of the set 이곳 / 그곳 / 저곳.", example: { ko: "그곳에서 만났어요.", en: "We met at that place.", form: "그곳 + 에서 (action-location); 만나다 → 만났어요 (past)" } },
    "서로|adverb": { korean: "서로", note: "'Each other, mutually', before the verb: 서로 도와요. It replaces an object, so 서로를 is unnecessary in most sentences.", example: { ko: "우리는 서로 도와요.", en: "We help each other.", form: "서로 before the verb; 돕다 → 도와요 (ㅂ-irregular, present)" } },
    "걱정하지 마세요|phrase": { korean: "걱정하지 마세요", note: "'Do not worry' — the polite prohibition -지 마세요 attached to 걱정하다. 걱정 마세요 is the common clipped version.", example: { ko: "걱정하지 마세요. 괜찮을 거예요.", en: "Do not worry. It will be fine.", form: "걱정하다 → 걱정하지 마세요 (polite prohibition)" } },
    "을 수밖에 없다|expression": { korean: "을 수밖에 없다", note: "'To have no choice but to', after a verb modifier: 갈 수밖에 없어요. Built from 수 (way) + 밖에 (only, with a negative).", example: { ko: "지금 갈 수밖에 없어요.", en: "I have no choice but to go now.", form: "가다 → 갈 (modifier) + 수밖에 없다 → 없어요" } },
    "낮|noun": { korean: "낮", note: "Daytime, the hours of light. Its opposite is 밤. 낮에 means 'during the day'; 점심 is specifically lunch or midday.", example: { ko: "낮에는 따뜻해요.", en: "It is warm during the day.", form: "낮 + 에는 (에 + 는, topic-marked time); 따뜻하다 → 따뜻해요" } },
    "고맙다|adjective": { korean: "고맙다", note: "To be grateful. ㅂ-irregular, giving 고마워요 and 고맙습니다. It is native Korean where 감사하다 is Sino-Korean, and feels slightly warmer.", example: { ko: "정말 고마워요.", en: "Thank you very much.", form: "고맙다 → 고마워요 (ㅂ-irregular, present, polite casual)" } },
    "센티미터|dependent noun": { korean: "센티미터", note: "Centimetre, following a Sino-Korean number: 십 센티미터. Shortened to 센치 in speech.", example: { ko: "십 센티미터 정도예요.", en: "It is about ten centimetres.", form: "십 (Sino-Korean) + 센티미터 + 정도 (about); 이다 → 예요" } },
    "시작되다|verb": { korean: "시작되다", note: "For something to begin by itself. Intransitive, so the thing that starts takes 이/가: 수업이 시작돼요. Its transitive partner is 시작하다.", example: { ko: "수업이 시작됐어요.", en: "The class has begun.", form: "수업 + 이 (subject); 시작되다 → 시작됐어요 (past, polite casual)" } },
    "인사|noun": { korean: "인사", note: "A greeting, including the bow that goes with it. 인사하다 is to greet, and the person takes 에게/한테. 인사 also means a farewell greeting.", example: { ko: "선생님께 인사했어요.", en: "I greeted the teacher.", form: "선생님 + 께 (honorific recipient); 인사하다 → 인사했어요 (past)" } },
    "을 리가 없다|expression": { korean: "을 리가 없다", note: "'There is no way that', denying a possibility outright: 그럴 리가 없어요. 리 is a bound noun meaning reason or likelihood.", example: { ko: "그 사람이 거짓말할 리가 없어요.", en: "There is no way that person is lying.", form: "거짓말하다 → 거짓말할 (modifier) + 리가 없다 → 없어요" } },
    "커녕|particle": { korean: "커녕", note: "'Let alone, far from' — denying the smaller thing after ruling out the bigger one: 밥커녕 물도 못 마셨어요. Usually 은/는커녕 in practice.", example: { ko: "밥은커녕 물도 못 마셨어요.", en: "Let alone rice, I could not even drink water.", form: "밥 + 은커녕; 물 + 도 (even); 마시다 → 못 마셨어요 (inability, past)" } },
    "소금|noun": { korean: "소금", note: "Salt. 설탕 is sugar and 후추 is pepper. 소금을 넣다 is to add salt.", example: { ko: "소금을 조금 넣으세요.", en: "Please add a little salt.", form: "소금 + 을 (object); 넣다 → 넣으세요 (polite request after a batchim)" } },
    "갑|counter": { korean: "갑", note: "The counter for small packs and boxes: 담배 한 갑, 우유 두 갑. Takes native Korean numbers.", example: { ko: "담배 한 갑 주세요.", en: "Please give me a pack of cigarettes.", form: "담배 + 한 (native number) + 갑 (counter); 주다 → 주세요" } },
    "와|interjection": { korean: "와", note: "'Wow' — surprise or admiration. Stretched for emphasis: 와아. Distinct from the particle 와 meaning 'and', which attaches to a noun.", example: { ko: "와, 정말 예뻐요!", en: "Wow, it is really pretty!", form: "Interjection standing alone; 예쁘다 → 예뻐요 (ㅡ drops)" } },

    // ================================================================ day 13
    "말다|verb": { korean: "말다", note: "To stop or cease. On its own it is rare — you will meet it as -지 말다, the prohibition: 가지 마세요. ㄹ-irregular, so the ㄹ drops: 마세요, not 말으세요.", example: { ko: "하던 일을 말고 쉬세요.", en: "Stop what you are doing and rest.", form: "말다 → 말고 (connector, ㄹ retained before ㄱ); 쉬다 → 쉬세요" } },
    "네|determiner": { korean: "네", note: "'Four' in front of a counter: 네 개, 네 명, 네 시. The shortened native set is 한, 두, 세, 네. Distinct from 네 meaning 'yes'.", example: { ko: "사과 네 개 주세요.", en: "Please give me four apples.", form: "네 (shortened from 넷) + 개 (counter); 주다 → 주세요" } },
    "은 척하다|expression": { korean: "은 척하다", note: "'To pretend to', after a modifier: 모르는 척했어요. 체하다 is an exact synonym. It implies the pretence is transparent.", example: { ko: "모르는 척했어요.", en: "I pretended not to know.", form: "모르다 → 모르는 (present modifier) + 척하다 → 척했어요 (past)" } },
    "신경 쓰지 마세요|phrase": { korean: "신경 쓰지 마세요", note: "'Never mind, do not bother about it.' 신경을 쓰다 is 'to pay attention, to fret', so this releases the listener from worrying.", example: { ko: "제 걱정은 신경 쓰지 마세요.", en: "Do not bother worrying about me.", form: "신경 쓰다 → 신경 쓰지 마세요 (polite prohibition)" } },
    "고령화 사회|noun phrase": { korean: "고령화 사회", note: "An ageing society — a standing topic in TOPIK reading about Korea. 고령화 is the process of ageing as a population.", example: { ko: "한국은 고령화 사회예요.", en: "Korea is an ageing society.", form: "한국 + 은 (topic); 고령화 사회 + 예요 (이다 after a vowel)" } },
    "거리|noun": { korean: "거리", note: "Two senses: a street (거리를 걷다) and a distance (거리가 멀다). Both are common; context decides.", example: { ko: "거리가 멀어요.", en: "The distance is far.", form: "거리 + 가 (subject); 멀다 → 멀어요 (present, polite casual)" } },
    "한글|noun": { korean: "한글", note: "The Korean alphabet specifically — the writing system, not the language. The language is 한국어 or 한국말. 한글날 is a public holiday on 9 October.", example: { ko: "한글은 배우기 쉬워요.", en: "Hangul is easy to learn.", form: "한글 + 은 (topic); 배우다 → 배우기 (nominalised); 쉽다 → 쉬워요 (ㅂ-irregular)" } },
    "그런데도|conjunction": { korean: "그런데도", note: "'And yet, even so' — conceding the previous fact and contradicting it more strongly than 그래도.", example: { ko: "많이 잤어요. 그런데도 피곤해요.", en: "I slept a lot. And yet I am tired.", form: "그런데도 opens the clause; 피곤하다 → 피곤해요" } },
    "세|dependent noun": { korean: "세", note: "The formal counter for years of age, with Sino-Korean numbers: 이십 세. Everyday speech uses 살 with native numbers — 스무 살. Forms appear in 세, conversation in 살.", example: { ko: "이십 세 이상만 들어갈 수 있어요.", en: "Only those aged twenty and over may enter.", form: "이십 (Sino-Korean) + 세 + 이상; 들어가다 → 들어갈 수 있어요" } },
    "내일|noun": { korean: "내일", note: "Tomorrow, as a noun so it takes particles: 내일은, 내일까지. Like 오늘 it works bare as an adverb — 내일에 가요 is wrong.", example: { ko: "내일은 바빠요.", en: "Tomorrow I am busy.", form: "내일 + 은 (topic particle); 바쁘다 → 바빠요 (ㅡ drops)" } },
    "이나|particle": { korean: "이나", note: "Two jobs: 'or' between nouns (커피나 차), and 'as many as' after a quantity (세 개나 먹었어요). 나 after a vowel.", example: { ko: "커피나 차를 마셔요.", en: "I drink coffee or tea.", form: "커피 ends in a vowel so it takes 나; a batchim noun takes 이나: 물이나" } },
    "을 지경이다|expression": { korean: "을 지경이다", note: "'To be on the verge of', usually something bad: 울 지경이에요. Emphatic and a little dramatic.", example: { ko: "너무 힘들어서 울 지경이에요.", en: "It is so hard I am on the verge of crying.", form: "울다 → 울 (modifier) + 지경이다 → 지경이에요" } },
    "손가락|noun": { korean: "손가락", note: "A finger, counted with 개. 발가락 is a toe, built the same way from 발.", example: { ko: "손가락을 다쳤어요.", en: "I hurt my finger.", form: "손가락 + 을 (object); 다치다 → 다쳤어요 (past, polite casual)" } },
    "놀라다|verb": { korean: "놀라다", note: "To be surprised. What surprised you takes 에: 소리에 놀랐어요. It describes your reaction, so it takes a past tense far more often than a present.", example: { ko: "갑자기 소리가 나서 놀랐어요.", en: "A sound came suddenly and I was startled.", form: "놀라다 → 놀랐어요 (past, polite casual)" } },
    "급|noun": { korean: "급", note: "A level or grade in a ranked system: 일 급, 이 급. TOPIK results are given this way — 삼 급 is level 3.", example: { ko: "토픽 삼 급을 받았어요.", en: "I got TOPIK level 3.", form: "삼 (Sino-Korean) + 급 + 을 (object); 받다 → 받았어요 (past)" } },
    "동물|noun": { korean: "동물", note: "An animal, counted with 마리. 동물원 is a zoo. 식물 is a plant, built on the same pattern.", example: { ko: "동물원에 갔어요.", en: "I went to the zoo.", form: "동물원 + 에 (destination); 가다 → 갔어요 (past, polite casual)" } },
    "울다|verb": { korean: "울다", note: "To cry. ㄹ-irregular: 웁니다, 우세요. Its opposite is 웃다. 울음이 나다 is 'tears come'.", example: { ko: "아기가 울어요.", en: "The baby is crying.", form: "아기 + 가 (subject); 울다 → 울어요 (present, polite casual)" } },
    "기 십상이다|expression": { korean: "기 십상이다", note: "'To be likely to' — and almost always something you would rather avoid: 실수하기 십상이에요. Written and slightly proverbial.", example: { ko: "서두르면 실수하기 십상이에요.", en: "If you rush, you are likely to make a mistake.", form: "실수하다 → 실수하기 (nominalised) + 십상이다 → 십상이에요" } },
    "병|noun": { korean: "병", note: "Two senses: an illness (병에 걸리다 = to fall ill) and a bottle, which doubles as the counter (맥주 두 병). Context separates them.", example: { ko: "물 한 병 주세요.", en: "Please give me a bottle of water.", form: "물 + 한 (native number) + 병 (counter); 주다 → 주세요" } },
    "서두르지 마세요|phrase": { korean: "서두르지 마세요", note: "'Do not rush' — reassuring someone that there is time. 천천히 하세요 fills the same slot more gently.", example: { ko: "시간 많아요. 서두르지 마세요.", en: "There is plenty of time. Do not rush.", form: "서두르다 → 서두르지 마세요 (polite prohibition)" } },
    "다섯째|numeral": { korean: "다섯째", note: "'Fifth' in a list, and the fifth child. Built regularly on 다섯.", example: { ko: "다섯째 줄에 앉으세요.", en: "Please sit in the fifth row.", form: "다섯째 + 줄 + 에 (location); 앉다 → 앉으세요 (polite request)" } },
    "쌍|counter": { korean: "쌍", note: "The counter for pairs: 부부 한 쌍, 양말 두 쌍. Takes native Korean numbers. For shoes and clothing sets, 켤레 and 벌 are more usual.", example: { ko: "부부 한 쌍이 왔어요.", en: "One couple came.", form: "부부 + 한 (native number) + 쌍 + 이 (subject); 오다 → 왔어요" } },
    "우와|interjection": { korean: "우와", note: "'Wow' — a longer, more excited version of 와. Common among younger speakers and in casual settings.", example: { ko: "우와, 정말 대단해요!", en: "Wow, that is really amazing!", form: "Interjection standing alone; 대단하다 → 대단해요" } },
    "버리다|auxiliary verb": { korean: "버리다", note: "-어 버리다 marks an action carried through to completion, usually with relief or regret: 다 먹어 버렸어요. The bare verb 버리다 means to throw away.", example: { ko: "케이크를 다 먹어 버렸어요.", en: "I ended up eating the whole cake.", form: "먹다 → 먹어 (connector) + 버리다 → 버렸어요 (completion, past)" } },
    "늦다|adjective": { korean: "늦다", note: "To be late, as a state: 시간이 늦었어요. The same word also works as a verb ('to run late'), which is why it appears twice in this bank.", example: { ko: "벌써 시간이 늦었어요.", en: "It is already late.", form: "시간 + 이 (subject); 늦다 → 늦었어요 (past, polite casual)" } },
    "지내다|verb": { korean: "지내다", note: "To spend time or get along. 잘 지내요? is the standard 'how are you doing?', and 잘 지내요 the answer.", example: { ko: "요즘 어떻게 지내요?", en: "How have you been doing lately?", form: "어떻게 + 지내다 → 지내요 (present, polite casual, question)" } },
    "백|determiner": { korean: "백", note: "'Hundred' in front of a counter: 백 명, 백 개. Sino-Korean, so it pairs with Sino-Korean counters for money and measures.", example: { ko: "백 명이 왔어요.", en: "A hundred people came.", form: "백 + 명 (counter) + 이 (subject); 오다 → 왔어요 (past)" } },
    "이든지|particle": { korean: "이든지", note: "'Whichever, any', offering free choice: 뭐든지 좋아요. 든지 after a vowel. Often shortened to 이든/든.", example: { ko: "뭐든지 좋아요.", en: "Anything is fine.", form: "뭐 + 든지 (free choice, after a vowel); 좋다 → 좋아요" } },
    "코|noun": { korean: "코", note: "The nose. 코가 막히다 is 'to have a blocked nose'; 콧물 is a runny nose, with the linking ㅅ.", example: { ko: "코가 막혔어요.", en: "My nose is blocked.", form: "코 + 가 (subject); 막히다 → 막혔어요 (past, polite casual)" } },
    "언제|pronoun": { korean: "언제", note: "'When', as a question word: 언제 가요? It needs no particle for time, so 언제에 is wrong. In statements it can mean 'whenever'.", example: { ko: "언제 도착해요?", en: "When do you arrive?", form: "언제 opens the question; 도착하다 → 도착해요 (present, question)" } },
    "는 셈이다|expression": { korean: "는 셈이다", note: "'To amount to, be as good as' — summing a situation up as effectively equivalent to something: 다 한 셈이에요.", example: { ko: "거의 다 끝난 셈이에요.", en: "It amounts to being almost finished.", form: "끝나다 → 끝난 (past modifier) + 셈이다 → 셈이에요" } },
    "고등학교|noun": { korean: "고등학교", note: "Senior high school, years 10 to 12. The set runs 초등학교 / 중학교 / 고등학교. A pupil there is a 고등학생.", example: { ko: "고등학교에서 만났어요.", en: "We met in high school.", form: "고등학교 + 에서 (action-location); 만나다 → 만났어요 (past)" } },
    "팔다|verb": { korean: "팔다", note: "To sell. ㄹ-irregular: 팝니다, 파세요. Its opposite is 사다. The buyer takes 에게/한테.", example: { ko: "여기서 표를 팔아요.", en: "They sell tickets here.", form: "표 + 를 (object); 팔다 → 팔아요 (present, polite casual)" } },
    "별|noun": { korean: "별", note: "A star in the sky. 별이 보이다 is 'stars are visible'. As a prefix 별- means 'particular', as in 별로 (not particularly).", example: { ko: "밤하늘에 별이 많아요.", en: "There are many stars in the night sky.", form: "밤하늘 + 에 (location); 별 + 이 (subject); 많다 → 많아요" } },

    // ================================================================ day 14
    "저출산 문제|noun phrase": { korean: "저출산 문제", note: "The low birth rate problem — one of the most common social topics in Korean media and TOPIK reading. 출산 is childbirth; 저 marks it as low.", example: { ko: "저출산 문제가 심각해요.", en: "The low birth rate problem is serious.", form: "저출산 문제 + 가 (subject); 심각하다 → 심각해요" } },
    "아니면|conjunction": { korean: "아니면", note: "'Or, otherwise', offering an alternative between clauses: 갈래요? 아니면 여기 있을래요? Between nouns, use 이나 instead.", example: { ko: "커피 마실래요? 아니면 차 마실래요?", en: "Shall we have coffee? Or tea?", form: "아니면 opens the alternative; 마시다 → 마실래요 (intention, question)" } },
    "을 뻔하다|expression": { korean: "을 뻔하다", note: "'To almost do something' — and it did not happen. Always past tense: 넘어질 뻔했어요.", example: { ko: "넘어질 뻔했어요.", en: "I almost fell over.", form: "넘어지다 → 넘어질 (modifier) + 뻔하다 → 뻔했어요 (past)" } },
    "칠월|noun": { korean: "칠월", note: "July. Regular — Sino-Korean 칠 plus 월. The irregular months are only 유월 (June) and 시월 (October).", example: { ko: "칠월에 휴가를 가요.", en: "I go on holiday in July.", form: "칠월 + 에 (time particle); 가다 → 가요 (present, polite casual)" } },
    "팔월|noun": { korean: "팔월", note: "August, the hottest month in Korea and the main holiday season. Regular formation from 팔 + 월.", example: { ko: "팔월은 아주 더워요.", en: "August is very hot.", form: "팔월 + 은 (topic); 덥다 → 더워요 (ㅂ-irregular, present)" } },
    "부담 갖지 마세요|phrase": { korean: "부담 갖지 마세요", note: "'Do not feel obliged' — releasing someone from a sense of debt, said when offering a favour or a gift. 부담 is a burden or pressure.", example: { ko: "그냥 드리는 거예요. 부담 갖지 마세요.", en: "I am just giving it to you. Do not feel obliged.", form: "부담 갖다 → 갖지 마세요 (polite prohibition)" } },
    "백|numeral": { korean: "백", note: "'Hundred', Sino-Korean. Korean counts in units of ten thousand, so 100,000 is 십만 rather than a hundred thousand.", example: { ko: "백 명이 참가했어요.", en: "A hundred people took part.", form: "백 + 명 (counter) + 이 (subject); 참가하다 → 참가했어요 (past)" } },
    "호|dependent noun": { korean: "호", note: "A number label for magazine issues and rooms: 삼 호실, 오월 호. Takes Sino-Korean numbers.", example: { ko: "삼백 호실이 어디예요?", en: "Where is room three hundred?", form: "삼백 (Sino-Korean) + 호실 + 이 (subject); 어디 + 예요 (question)" } },
    "이라도|particle": { korean: "이라도", note: "'Even, at least' — accepting a second-best option: 물이라도 주세요. 라도 after a vowel.", example: { ko: "물이라도 주세요.", en: "Give me water at least.", form: "물 ends in a batchim so it takes 이라도; a vowel noun takes 라도: 커피라도" } },
    "올라가다|verb": { korean: "올라가다", note: "To go up, away from the speaker. The place climbed takes 에: 산에 올라가요. Its mirror 올라오다 comes up toward the speaker.", example: { ko: "산에 올라갔어요.", en: "I climbed up the mountain.", form: "산 + 에 (destination); 올라가다 → 올라갔어요 (past)" } },
    "컵|noun": { korean: "컵", note: "A cup, the borrowed word for the object. When counting drinks, the native counter 잔 is used instead: 커피 한 잔, not 한 컵.", example: { ko: "컵이 깨졌어요.", en: "The cup broke.", form: "컵 + 이 (subject); 깨지다 → 깨졌어요 (past, polite casual)" } },
    "고 말다|expression": { korean: "고 말다", note: "'To end up doing', with a note of regret that it finally happened: 울고 말았어요. Similar to -어 버리다 but more resigned and more written.", example: { ko: "결국 울고 말았어요.", en: "In the end I ended up crying.", form: "울다 → 울고 (connector) + 말다 → 말았어요 (past)" } },
    "재미|noun": { korean: "재미", note: "Fun or enjoyment. It builds two very common adjectives: 재미있다 (fun) and 재미없다 (boring), both written solid.", example: { ko: "이 일은 재미가 없어요.", en: "This work is not fun.", form: "재미 + 가 (subject); 없다 → 없어요 (present, polite casual)" } },
    "태어나다|verb": { korean: "태어나다", note: "To be born. The place takes 에서: 서울에서 태어났어요. Almost always past tense.", example: { ko: "저는 서울에서 태어났어요.", en: "I was born in Seoul.", form: "서울 + 에서 (source); 태어나다 → 태어났어요 (past)" } },
    "즐겁다|adjective": { korean: "즐겁다", note: "To be enjoyable, of an experience or an occasion. ㅂ-irregular: 즐거워요. 즐거운 하루 되세요 is a common well-wish. 재미있다 is more about amusement.", example: { ko: "여행이 즐거웠어요.", en: "The trip was enjoyable.", form: "여행 + 이 (subject); 즐겁다 → 즐거웠어요 (ㅂ-irregular, past)" } },
    "인분|counter": { korean: "인분", note: "The counter for food portions on a menu: 삼겹살 이 인분. Takes Sino-Korean numbers, and Korean barbecue is normally ordered by it.", example: { ko: "삼겹살 이 인분 주세요.", en: "Two portions of pork belly, please.", form: "이 (Sino-Korean) + 인분 (counter); 주다 → 주세요" } },
    "둘째|determiner": { korean: "둘째", note: "'Second' in front of a noun: 둘째 아이. It doubles as a numeral standing alone, which is a separate entry here.", example: { ko: "둘째 딸이에요.", en: "She is the second daughter.", form: "둘째 + 딸 + 이에요 (이다 after a batchim)" } },
    "첫째|determiner": { korean: "첫째", note: "'First' in front of a noun: 첫째 아들. Irregular — built on 첫, not 하나.", example: { ko: "첫째 아들이 대학생이에요.", en: "My first son is a university student.", form: "첫째 + 아들 + 이 (subject); 대학생 + 이에요" } },
    "셋째|determiner": { korean: "셋째", note: "'Third' in front of a noun: 셋째 주. Built regularly on 셋.", example: { ko: "셋째 주에 만나요.", en: "Let us meet in the third week.", form: "셋째 + 주 + 에 (time particle); 만나다 → 만나요 (suggestion)" } },
    "어머|interjection": { korean: "어머", note: "'Oh my' — surprise, used mainly by women. 어머나 is the longer form. Men more often say 어 or 아이고.", example: { ko: "어머, 벌써 이렇게 됐어요?", en: "Oh my, is it this late already?", form: "Interjection standing alone; 되다 → 됐어요 (past, question)" } },
    "시작|noun": { korean: "시작", note: "The beginning. 시작이 반이다 ('starting is half the battle') is a well-known proverb. The verbs are 시작하다 and 시작되다.", example: { ko: "시작이 좋아요.", en: "The start is good.", form: "시작 + 이 (subject); 좋다 → 좋아요 (present, polite casual)" } },
    "아 버리다|expression": { korean: "아 버리다", note: "The -아 form of -어 버리다, used after a stem whose last vowel is ㅏ or ㅗ: 가 버렸어요. Marks completion, often with regret.", example: { ko: "친구가 가 버렸어요.", en: "My friend went off and left.", form: "가다 → 가 (아-connector) + 버리다 → 버렸어요 (completion, past)" } },
    "아 놓다|expression": { korean: "아 놓다", note: "The -아 form of -어 놓다: doing something and leaving it in that state. 창문을 열어 놓았어요 = the window is left open.", example: { ko: "문을 열어 놓았어요.", en: "I opened the door and left it open.", form: "열다 → 열어 (connector) + 놓다 → 놓았어요 (resulting state, past)" } },
    "일주일|noun": { korean: "일주일", note: "One week. Built from 일 (one) + 주일 (week). Two weeks is 이 주일, and the counter for weeks alone is 주.", example: { ko: "일주일에 두 번 운동해요.", en: "I exercise twice a week.", form: "일주일 + 에 (per); 두 번 (native number + counter); 운동하다 → 운동해요" } },
    "해|dependent noun": { korean: "해", note: "The counter for years with native Korean numbers: 한 해, 두 해. Its Sino-Korean partner is 년 — 일 년, 이 년 — which is far more common.", example: { ko: "한 해가 빨리 지나갔어요.", en: "The year went by quickly.", form: "한 (native number) + 해 + 가 (subject); 지나가다 → 지나갔어요" } },
    "편하게 하세요|phrase": { korean: "편하게 하세요", note: "'Make yourself comfortable' — said to a guest. 편하다 is 'to be comfortable', and 편하게 turns it into how they should act.", example: { ko: "어서 오세요. 편하게 하세요.", en: "Welcome. Make yourself comfortable.", form: "편하다 → 편하게 (adverbial) + 하다 → 하세요 (polite request)" } },
    "걸다|verb": { korean: "걸다", note: "To hang something up, and to place a call: 전화를 걸다. ㄹ-irregular: 겁니다, 거세요.", example: { ko: "친구한테 전화를 걸었어요.", en: "I called my friend.", form: "친구 + 한테 (recipient); 전화 + 를 (object); 걸다 → 걸었어요 (past)" } },
    "혹은|conjunction": { korean: "혹은", note: "'Or', formal and written — the register of forms and notices. In speech Koreans use 아니면 or the particle 이나.", example: { ko: "월요일 혹은 화요일에 만나요.", en: "Let us meet on Monday or Tuesday.", form: "혹은 joins the two nouns; 화요일 + 에 (time); 만나다 → 만나요" } },
    "박물관|noun": { korean: "박물관", note: "A museum. 미술관 is an art gallery specifically. Visiting takes 에 for the destination and 에서 for what you do there.", example: { ko: "박물관에 갔어요.", en: "I went to the museum.", form: "박물관 + 에 (destination); 가다 → 갔어요 (past, polite casual)" } },
    "지구 온난화|noun phrase": { korean: "지구 온난화", note: "Global warming — a standard phrase in environmental reading passages, alongside 기후 변화.", example: { ko: "지구 온난화가 심해지고 있어요.", en: "Global warming is getting worse.", form: "지구 온난화 + 가 (subject); 심해지다 → 심해지고 있어요 (progressive)" } },
    "그럼|adverb": { korean: "그럼", note: "'Then, in that case', used adverbially inside a sentence rather than opening one. The same shape also works as a conjunction and as an interjection meaning 'of course'.", example: { ko: "그럼 어떻게 할까요?", en: "Then what shall we do?", form: "그럼 before the verb; 하다 → 할까요 (suggestion, question)" } },

    // ================================================================ day 15
    "얘기하다|verb": { korean: "얘기하다", note: "To chat or tell, the spoken contraction of 이야기하다. The person you talk with takes 하고 or 와/과.", example: { ko: "친구하고 얘기했어요.", en: "I chatted with a friend.", form: "친구 + 하고 (with); 얘기하다 → 얘기했어요 (past, polite casual)" } },
    "그릇|noun": { korean: "그릇", note: "A bowl or dish, and the counter for bowls of food: 밥 한 그릇, 국수 두 그릇.", example: { ko: "밥 한 그릇 더 주세요.", en: "One more bowl of rice, please.", form: "밥 + 한 (native number) + 그릇 + 더; 주다 → 주세요" } },
    "아 두다|expression": { korean: "아 두다", note: "'To do in advance and leave it ready': 표를 사 두었어요. Close to -어 놓다, but 두다 stresses preparing for later.", example: { ko: "미리 표를 사 두었어요.", en: "I bought the tickets in advance.", form: "사다 → 사 (아-connector) + 두다 → 두었어요 (past)" } },
    "저기|pronoun": { korean: "저기", note: "'Over there', away from both speaker and listener. Completes 여기 / 거기 / 저기. As an interjection it also means 'excuse me'.", example: { ko: "저기에 있어요.", en: "It is over there.", form: "저기 + 에 (location particle); 있다 → 있어요" } },
    "개|noun": { korean: "개", note: "A dog, counted with 마리. The identical 개 used as a counter for objects is a separate entry — position makes it clear which is meant.", example: { ko: "개 두 마리를 키워요.", en: "I keep two dogs.", form: "개 + 두 (native number) + 마리 + 를 (object); 키우다 → 키워요" } },
    "씩|particle": { korean: "씩", note: "'Each, apiece', distributing a quantity: 하나씩, 조금씩, 한 명씩. It attaches to the number rather than the noun.", example: { ko: "하나씩 가져가세요.", en: "Please take one each.", form: "하나 + 씩 (distributive); 가져가다 → 가져가세요 (polite request)" } },
    "천|determiner": { korean: "천", note: "'Thousand' in front of a counter: 천 원, 천 명. Sino-Korean. Note 만 (ten thousand) is the next unit up, not 십천.", example: { ko: "천 원만 주세요.", en: "Just a thousand won, please.", form: "천 + 원 (counter) + 만 (only); 주다 → 주세요" } },
    "만|determiner": { korean: "만", note: "'Ten thousand' in front of a counter: 만 원, 만 명. Korean's number groups break every four digits, so this is a base unit, not a derived one.", example: { ko: "만 원짜리 있어요?", en: "Do you have a ten-thousand-won note?", form: "만 + 원 + 짜리 (worth); 있다 → 있어요 (question)" } },
    "잃다|verb": { korean: "잃다", note: "To lose something you had. For losing your way it is 길을 잃다, and 잃어버리다 adds the sense that it is gone for good.", example: { ko: "지갑을 잃었어요.", en: "I lost my wallet.", form: "지갑 + 을 (object); 잃다 → 잃었어요 (past, polite casual)" } },
    "라디오|noun": { korean: "라디오", note: "A radio. Listened to with 듣다: 라디오를 들어요. 텔레비전 takes 보다 instead.", example: { ko: "아침에 라디오를 들어요.", en: "I listen to the radio in the morning.", form: "라디오 + 를 (object); 듣다 → 들어요 (ㄷ-irregular, present)" } },
    "바람|dependent noun": { korean: "바람", note: "In -는 바람에 it means 'on account of', and only for unwanted results. It has nothing to do with 바람 meaning wind, despite the identical spelling.", example: { ko: "늦잠을 자는 바람에 늦었어요.", en: "I was late on account of oversleeping.", form: "자다 → 자는 (present modifier) + 바람에; 늦다 → 늦었어요" } },
    "번|counter": { korean: "번", note: "The counter for times or occurrences, with native Korean numbers: 한 번, 두 번, 세 번. Written 한번 solid it means 'give it a go' instead.", example: { ko: "세 번 시도했어요.", en: "I tried three times.", form: "세 (native number) + 번 (counter); 시도하다 → 시도했어요 (past)" } },
    "아이고|interjection": { korean: "아이고", note: "A versatile sigh — dismay, sympathy, physical effort, or mild exasperation. Very common from older speakers. Shortened to 아이구 or 아유.", example: { ko: "아이고, 힘들어요.", en: "Oh dear, this is hard.", form: "Interjection standing alone; 힘들다 → 힘들어요" } },
    "팔|numeral": { korean: "팔", note: "Sino-Korean 'eight', used in dates, money and phone numbers: 팔월 (August), 팔십 (eighty). Native 여덟 is used for objects and ages.", example: { ko: "팔월에 여행을 가요.", en: "I travel in August.", form: "팔 + 월 (Sino-Korean number before a Sino-Korean counter); 가다 → 가요" } },
    "마음대로 하세요|phrase": { korean: "마음대로 하세요", note: "'Do as you like.' Tone decides everything — warm it is genuine permission, flat it is a cold 'suit yourself'.", example: { ko: "편하실 대로 마음대로 하세요.", en: "Please do just as you like.", form: "마음 + 대로 (in accordance with); 하다 → 하세요 (polite request)" } },
    "남쪽|noun": { korean: "남쪽", note: "The south side. The compass set is 동쪽, 서쪽, 남쪽, 북쪽, all built with 쪽.", example: { ko: "남쪽으로 가세요.", en: "Please go south.", form: "남쪽 + 으로 (direction particle); 가다 → 가세요 (polite request)" } },
    "아 가다|expression": { korean: "아 가다", note: "The -아 form of -어 가다, after a stem whose last vowel is ㅏ or ㅗ: 살아 가다. Marks an action carrying on into the future.", example: { ko: "열심히 살아 가고 있어요.", en: "I am carrying on living diligently.", form: "살다 → 살아 (아-connector) + 가다 → 가고 있어요 (progressive)" } },
    "아 오다|expression": { korean: "아 오다", note: "The -아 form of -어 오다: an action continuing up to the present. 살아 왔어요 = 'I have lived up to now'.", example: { ko: "지금까지 참아 왔어요.", en: "I have endured up until now.", form: "참다 → 참아 (아-connector) + 오다 → 왔어요 (past)" } },
    "색깔|noun": { korean: "색깔", note: "Colour, the fuller spoken form of 색. 무슨 색깔이에요? is how you ask what colour something is.", example: { ko: "무슨 색깔을 좋아해요?", en: "What colour do you like?", form: "무슨 + 색깔 + 을 (object); 좋아하다 → 좋아해요 (question)" } },
    "사랑하다|verb": { korean: "사랑하다", note: "To love. It takes 을/를: 가족을 사랑해요. Koreans use it far more sparingly than English uses 'love' — for liking things, 좋아하다 is the word.", example: { ko: "가족을 사랑해요.", en: "I love my family.", form: "가족 + 을 (object); 사랑하다 → 사랑해요 (여-irregular, present)" } },
    "외국인|noun": { korean: "외국인", note: "A foreigner. 외국 사람 is the softer everyday equivalent; 외국인 is what appears on forms and signs.", example: { ko: "저는 외국인이에요.", en: "I am a foreigner.", form: "외국인 + 이에요 (이다 after a batchim; present, polite casual)" } },
    "부인|noun": { korean: "부인", note: "A polite word for someone else's wife, and a form of address for a married woman. For your own wife, 아내 is the word.", example: { ko: "사장님 부인을 만났어요.", en: "I met the president's wife.", form: "부인 + 을 (object); 만나다 → 만났어요 (past, polite casual)" } },
    "째|particle": { korean: "째", note: "Makes an ordinal or marks a run: 세 번째 (third time), 사흘째 (the third day running). Attaches directly to the number.", example: { ko: "이번이 세 번째예요.", en: "This is the third time.", form: "세 번 + 째 (ordinal); 이다 → 예요 (after a vowel)" } },
    "우산|noun": { korean: "우산", note: "An umbrella. You 쓰다 it, the same verb as wearing a hat — 우산을 써요, never 입다.", example: { ko: "우산을 가져오세요.", en: "Please bring an umbrella.", form: "우산 + 을 (object); 가져오다 → 가져오세요 (polite request)" } },
    "지난달|noun": { korean: "지난달", note: "Last month. The set runs 지난달 / 이번 달 / 다음 달. Written solid, unlike 이번 달 and 다음 달.", example: { ko: "지난달에 이사했어요.", en: "I moved house last month.", form: "지난달 + 에 (time particle); 이사하다 → 이사했어요 (past)" } },
    "반면에|conjunction": { korean: "반면에", note: "'On the other hand', opening a contrasting sentence. After a verb it becomes -는 반면에 inside one sentence.", example: { ko: "값은 싸요. 반면에 질은 나빠요.", en: "It is cheap. On the other hand, the quality is poor.", form: "반면에 opens the clause; 나쁘다 → 나빠요 (ㅡ drops)" } },
    "이쪽|pronoun": { korean: "이쪽", note: "'This side, this way', and a polite way to gesture at a person present: 이쪽은 제 친구예요.", example: { ko: "이쪽은 제 친구예요.", en: "This is my friend.", form: "이쪽 + 은 (topic); 친구 + 예요 (이다 after a vowel)" } },
    "어서 오세요|phrase": { korean: "어서 오세요", note: "'Welcome, come in' — what every Korean shop and restaurant says as you walk through the door. You are not expected to reply.", example: { ko: "어서 오세요! 몇 분이세요?", en: "Welcome! How many people?", form: "어서 + 오다 → 오세요 (polite request, fixed as a greeting)" } },
    "재활용 쓰레기|noun phrase": { korean: "재활용 쓰레기", note: "Recyclable waste. Korean rubbish separation is strict and appears in practical reading passages: 재활용 쓰레기를 분리해요.", example: { ko: "재활용 쓰레기를 분리해요.", en: "I separate the recyclable waste.", form: "재활용 쓰레기 + 를 (object); 분리하다 → 분리해요" } },
    "오늘|adverb": { korean: "오늘", note: "'Today', working bare before the verb with no particle: 오늘 만나요. The noun form takes particles and is a separate entry.", example: { ko: "오늘 만나요.", en: "Let us meet today.", form: "오늘 before the verb, no particle; 만나다 → 만나요 (suggestion)" } },
    "잎|noun": { korean: "잎", note: "A leaf. 나뭇잎 is a tree leaf, with the linking ㅅ. Pronounced [입], the same as 입 (mouth), so context separates them.", example: { ko: "가을에 잎이 떨어져요.", en: "Leaves fall in autumn.", form: "잎 + 이 (subject); 떨어지다 → 떨어져요 (present, polite casual)" } },

    // ================================================================ day 16
    "스포츠|noun": { korean: "스포츠", note: "Sport as a category, borrowed from English. 운동 is the native equivalent and is more common in speech.", example: { ko: "저는 스포츠를 좋아해요.", en: "I like sports.", form: "스포츠 + 를 (object); 좋아하다 → 좋아해요 (present, polite casual)" } },
    "회|counter": { korean: "회", note: "The counter for rounds or sessions, with Sino-Korean numbers: 일 회, 이 회. 번 with native numbers covers the same ground more casually.", example: { ko: "일주일에 삼 회 수업이 있어요.", en: "There are three sessions a week.", form: "삼 (Sino-Korean) + 회; 수업 + 이 (subject); 있다 → 있어요" } },
    "아휴|interjection": { korean: "아휴", note: "A sigh of tiredness or exasperation. Softer and more weary than 아이고.", example: { ko: "아휴, 오늘 정말 피곤해요.", en: "Ugh, I am really tired today.", form: "Interjection standing alone; 피곤하다 → 피곤해요" } },
    "교회|noun": { korean: "교회", note: "A church, Protestant by default. A Catholic church is 성당 and a Buddhist temple is 절. Attending takes 에 다니다.", example: { ko: "일요일에 교회에 가요.", en: "I go to church on Sunday.", form: "일요일 + 에 (time); 교회 + 에 (destination); 가다 → 가요" } },
    "에다가|particle": { korean: "에다가", note: "'Onto' or 'in addition to', marking where something is added: 종이에다가 쓰세요. Often shortened to 에다.", example: { ko: "여기에다가 쓰세요.", en: "Please write it on here.", form: "여기 + 에다가 (target of addition); 쓰다 → 쓰세요 (polite request)" } },
    "화|noun": { korean: "화", note: "Anger. It is produced, not felt — 화가 나다 ('anger arises') or 화를 내다 ('to let anger out'). 화나요 is the everyday 'I am angry'.", example: { ko: "화가 났어요.", en: "I got angry.", form: "화 + 가 (subject); 나다 → 났어요 (past, polite casual)" } },
    "내려오다|verb": { korean: "내려오다", note: "To come down, toward the speaker. The place descended takes 에서: 산에서 내려왔어요. Its mirror is 내려가다.", example: { ko: "산에서 내려왔어요.", en: "I came down from the mountain.", form: "산 + 에서 (source); 내려오다 → 내려왔어요 (past)" } },
    "내려가다|verb": { korean: "내려가다", note: "To go down, away from the speaker. Also used for travelling from Seoul to the provinces, since Seoul is treated as 'up'.", example: { ko: "일 층으로 내려가세요.", en: "Please go down to the first floor.", form: "일 층 + 으로 (direction); 내려가다 → 내려가세요 (polite request)" } },
    "주|dependent noun": { korean: "주", note: "The counter for weeks with Sino-Korean numbers: 일 주, 이 주. In practice 주일 and 일주일 are more common in speech.", example: { ko: "이 주 후에 만나요.", en: "Let us meet in two weeks.", form: "이 (Sino-Korean) + 주 + 후에 (after); 만나다 → 만나요" } },
    "안다|verb": { korean: "안다", note: "To hug or hold in your arms. Pronounced [안따]. Do not confuse it with 알다 (to know) — 안아요 versus 알아요.", example: { ko: "아기를 안았어요.", en: "I held the baby.", form: "아기 + 를 (object); 안다 → 안았어요 (past, polite casual)" } },
    "위험|noun": { korean: "위험", note: "Danger. 위험하다 is the adjective and is what you will meet most: 위험해요. 위험 alone appears on warning signs.", example: { ko: "여기는 위험해요.", en: "It is dangerous here.", form: "여기 + 는 (topic); 위험하다 → 위험해요 (present, polite casual)" } },
    "또 오세요|phrase": { korean: "또 오세요", note: "'Please come again' — said by shop and restaurant staff as you leave, the bookend to 어서 오세요.", example: { ko: "감사합니다. 또 오세요!", en: "Thank you. Please come again!", form: "또 + 오다 → 오세요 (polite request, fixed as a farewell)" } },
    "잊다|verb": { korean: "잊다", note: "To forget. 잊어버리다 adds the sense that it is gone for good, and is far more common in speech.", example: { ko: "약속을 잊었어요.", en: "I forgot the appointment.", form: "약속 + 을 (object); 잊다 → 잊었어요 (past, polite casual)" } },
    "저쪽|pronoun": { korean: "저쪽", note: "'That side over there', away from both speaker and listener. Completes 이쪽 / 그쪽 / 저쪽.", example: { ko: "화장실은 저쪽에 있어요.", en: "The restroom is over that way.", form: "저쪽 + 에 (location); 있다 → 있어요 (present, polite casual)" } },
    "으로서|particle": { korean: "으로서", note: "'As, in the role of': 학생으로서 열심히 공부해요. Do not confuse it with 으로써, which means 'by means of' — one letter, entirely different job.", example: { ko: "학생으로서 최선을 다해요.", en: "As a student, I do my best.", form: "학생 + 으로서 (role, after a batchim); 다하다 → 다해요" } },
    "으로써|particle": { korean: "으로써", note: "'By means of', marking a method: 대화로써 해결해요. Its lookalike 으로서 marks a role instead. Both are written register.", example: { ko: "대화로써 문제를 해결했어요.", en: "We solved the problem by means of dialogue.", form: "대화 + 로써 (means, after a vowel); 해결하다 → 해결했어요" } },
    "사무실|noun": { korean: "사무실", note: "An office room. 회사 is the company as an organisation, so 회사에 가요 means going to work while 사무실 names the room itself.", example: { ko: "사무실이 삼 층에 있어요.", en: "The office is on the third floor.", form: "사무실 + 이 (subject); 삼 층 + 에 (location); 있다 → 있어요" } },
    "스무|determiner": { korean: "스무", note: "'Twenty' in front of a counter: 스무 살, 스무 개. The standalone numeral is 스물, and the ㄹ drops before a counter.", example: { ko: "저는 스무 살이에요.", en: "I am twenty years old.", form: "스무 (from 스물) + 살 (counter) + 이에요" } },
    "관심을 갖다|expression": { korean: "관심을 갖다", note: "'To take an interest in.' What interests you takes 에: 음악에 관심을 갖다. 관심이 있다 is the more common everyday phrasing.", example: { ko: "한국 문화에 관심을 갖게 됐어요.", en: "I came to take an interest in Korean culture.", form: "문화 + 에; 갖다 → 갖게 되다 → 갖게 됐어요 (came to, past)" } },
    "그리하여|conjunction": { korean: "그리하여", note: "'And thus' — formal, literary, the register of written narrative and history. In speech, 그래서.", example: { ko: "그리하여 전쟁이 끝났어요.", en: "And thus the war ended.", form: "그리하여 opens the clause; 끝나다 → 끝났어요 (past)" } },
    "건강하다|adjective": { korean: "건강하다", note: "To be healthy. 건강하세요 is a common well-wish. Note it describes a person's state, so 건강한 사람 is 'a healthy person'.", example: { ko: "할아버지는 아주 건강하세요.", en: "My grandfather is very healthy.", form: "할아버지 + 는 (topic); 건강하다 + 시 → 건강하세요 (honorific present)" } },
    "강|noun": { korean: "강", note: "A river. Names attach directly: 한강, 낙동강. 바다 is the sea and 호수 a lake.", example: { ko: "강이 아주 넓어요.", en: "The river is very wide.", form: "강 + 이 (subject); 넓다 → 넓어요 (present, polite casual)" } },
    "놓다|auxiliary verb": { korean: "놓다", note: "-어 놓다 means doing something and leaving it in that state: 창문을 열어 놓았어요. Close to -어 두다, but 놓다 stresses the state and 두다 the preparation.", example: { ko: "창문을 열어 놓았어요.", en: "I left the window open.", form: "열다 → 열어 (connector) + 놓다 → 놓았어요 (resulting state, past)" } },
    "프랑스|proper noun": { korean: "프랑스", note: "France. The language is 프랑스어 and a French person is 프랑스 사람. Country names take 사람 for nationality.", example: { ko: "프랑스에 가고 싶어요.", en: "I want to go to France.", form: "프랑스 + 에 (destination); 가다 → 가고 싶어요 (-고 싶다)" } },
    "개인 정보|noun phrase": { korean: "개인 정보", note: "Personal information — a set phrase on forms and in privacy notices, and a frequent reading topic. 개인 is an individual.", example: { ko: "개인 정보를 보호해야 해요.", en: "Personal information must be protected.", form: "개인 정보 + 를 (object); 보호하다 → 보호해야 해요 (obligation)" } },
    "부|counter": { korean: "부", note: "The counter for copies of a printed document: 서류 두 부, 신문 한 부. Takes Sino-Korean numbers.", example: { ko: "서류 두 부를 복사했어요.", en: "I copied two sets of the documents.", form: "서류 + 두 부 + 를 (object); 복사하다 → 복사했어요 (past)" } },
    "에이|interjection": { korean: "에이", note: "'Come on, no way' — playful disbelief or dismissal. Casual, and usually said with a smile.", example: { ko: "에이, 설마요.", en: "Come on, no way.", form: "Interjection; 설마 + 요 (surely not, politeness particle)" } },
    "시간을 보내다|expression": { korean: "시간을 보내다", note: "'To spend time.' 보내다 is literally 'to send', and Korean sends time rather than spending it. With people, add 와/과 or 하고.", example: { ko: "가족과 시간을 보냈어요.", en: "I spent time with my family.", form: "가족 + 과 (with); 시간 + 을 (object); 보내다 → 보냈어요 (past)" } },
    "참|adverb": { korean: "참", note: "'Really, truly' before an adjective, and also 'oh, by the way' when something occurs to you mid-conversation: 아, 참! Both are common.", example: { ko: "아, 참! 그거 잊어버렸어요.", en: "Oh, by the way! I forgot that.", form: "참 as a discourse marker; 잊어버리다 → 잊어버렸어요 (past)" } },
    "잡지|noun": { korean: "잡지", note: "A magazine, counted with 권 like books. 신문 is a newspaper.", example: { ko: "잡지를 읽고 있어요.", en: "I am reading a magazine.", form: "잡지 + 를 (object); 읽다 → 읽고 있어요 (progressive, present)" } },
    "댁|noun": { korean: "댁", note: "The honorific of 집 — someone else's home: 선생님 댁. It also serves as a respectful 'you' in older speech.", example: { ko: "선생님 댁에 갔어요.", en: "I went to the teacher's home.", form: "댁 + 에 (destination); 가다 → 갔어요 (past, polite casual)" } },
    "조심히 가세요|phrase": { korean: "조심히 가세요", note: "'Get home safely' — said to someone leaving, especially at night or in bad weather. Warmer than a plain 안녕히 가세요.", example: { ko: "늦었어요. 조심히 가세요.", en: "It is late. Get home safely.", form: "조심히 + 가다 → 가세요 (polite request)" } },

    // ================================================================ day 17
    "비디오|noun": { korean: "비디오", note: "A video. Watched with 보다. Increasingly replaced by 영상 in current usage.", example: { ko: "비디오를 봤어요.", en: "I watched a video.", form: "비디오 + 를 (object); 보다 → 봤어요 (past, polite casual)" } },
    "싸우다|verb": { korean: "싸우다", note: "To fight or quarrel. The other party takes 와/과 or 하고: 친구하고 싸웠어요. It covers verbal arguments as much as physical fights.", example: { ko: "친구하고 싸웠어요.", en: "I had a fight with my friend.", form: "친구 + 하고 (with); 싸우다 → 싸웠어요 (past, polite casual)" } },
    "연습|noun": { korean: "연습", note: "Practice. 연습하다 is the verb, and what you practise takes 을/를: 발음을 연습해요.", example: { ko: "매일 발음을 연습해요.", en: "I practise pronunciation every day.", form: "발음 + 을 (object); 연습하다 → 연습해요 (present, polite casual)" } },
    "돈을 벌다|expression": { korean: "돈을 벌다", note: "'To earn money.' 벌다 is the dedicated verb — 돈을 받다 means merely receiving it, not earning it. ㄹ-irregular: 법니다.", example: { ko: "아르바이트로 돈을 벌어요.", en: "I earn money through a part-time job.", form: "아르바이트 + 로 (means); 돈 + 을 (object); 벌다 → 벌어요" } },
    "그분|pronoun": { korean: "그분", note: "'That person', honorific — the respectful form of 그 사람. 분 is the honorific counter for people, so this elevates whoever you mean.", example: { ko: "그분이 제 선생님이에요.", en: "That person is my teacher.", form: "그분 + 이 (subject); 선생님 + 이에요 (이다 after a batchim)" } },
    "때|dependent noun": { korean: "때", note: "The bound-noun 'when', always after a modifier: 어릴 때, 방학 때. It cannot start a phrase and takes 에 optionally: 그때에.", example: { ko: "학생 때 많이 놀았어요.", en: "I played a lot when I was a student.", form: "학생 + 때; 놀다 → 놀았어요 (past, polite casual)" } },
    "꿈을 꾸다|expression": { korean: "꿈을 꾸다", note: "'To have a dream.' Korean uses the dedicated verb 꾸다 rather than 'have' — 꿈을 가지다 would only work for an ambition.", example: { ko: "이상한 꿈을 꿨어요.", en: "I had a strange dream.", form: "꿈 + 을 (object); 꾸다 → 꿨어요 (past, polite casual)" } },
    "가져오다|verb": { korean: "가져오다", note: "To bring something here. Its mirror 가져가다 takes it away. For bringing a person, the verbs are 데려오다 and 데려가다 instead.", example: { ko: "책을 가져오세요.", en: "Please bring the book.", form: "책 + 을 (object); 가져오다 → 가져오세요 (polite request)" } },
    "대학생|noun": { korean: "대학생", note: "A university student. The set runs 초등학생 / 중학생 / 고등학생 / 대학생, all built with 학생.", example: { ko: "제 동생은 대학생이에요.", en: "My younger sibling is a university student.", form: "동생 + 은 (topic); 대학생 + 이에요 (이다 after a batchim)" } },
    "께서|particle": { korean: "께서", note: "The honorific subject marker, replacing 이/가 when the subject deserves respect: 선생님께서 오셨어요. It normally pairs with an honorific verb ending in 시.", example: { ko: "할머니께서 오셨어요.", en: "Grandmother has arrived.", form: "할머니 + 께서 (honorific subject); 오다 + 시 → 오셨어요 (honorific past)" } },
    "그러다가|conjunction": { korean: "그러다가", note: "'And then, in the middle of that' — one action interrupted by or leading into another. Common in storytelling.", example: { ko: "이야기하다가 그러다가 잠들었어요.", en: "We were talking and then I fell asleep.", form: "그러다가 opens the clause; 잠들다 → 잠들었어요 (past)" } },
    "잠시만요|phrase": { korean: "잠시만요", note: "'Just a moment' — asking someone to wait, and also 'excuse me' when squeezing past in a crowd. 잠깐만요 is interchangeable.", example: { ko: "잠시만요, 확인해 볼게요.", en: "Just a moment, I will check.", form: "잠시 + 만 (only) + 요 (politeness particle)" } },
    "잠깐만요|phrase": { korean: "잠깐만요", note: "'Hold on a second' — the same job as 잠시만요 and slightly more casual. Also used to stop someone mid-action.", example: { ko: "잠깐만요! 두고 가셨어요.", en: "Hold on! You left something behind.", form: "잠깐 + 만 (only) + 요 (politeness particle)" } },
    "대답하다|verb": { korean: "대답하다", note: "To answer a question. The person answered takes 에게/한테, and the question takes 에: 질문에 대답했어요. For answering a phone, use 받다.", example: { ko: "질문에 대답했어요.", en: "I answered the question.", form: "질문 + 에; 대답하다 → 대답했어요 (past, polite casual)" } },
    "사진을 찍다|expression": { korean: "사진을 찍다", note: "'To take a photo.' 찍다 is the dedicated verb — literally 'to stamp'. 사진을 만들다 or 하다 would both be wrong.", example: { ko: "여기서 사진을 찍었어요.", en: "I took a photo here.", form: "사진 + 을 (object); 찍다 → 찍었어요 (past, polite casual)" } },
    "편|counter": { korean: "편", note: "The counter for films, poems and other complete works: 영화 한 편, 시 두 편. Takes native Korean numbers.", example: { ko: "영화 두 편을 봤어요.", en: "I watched two films.", form: "영화 + 두 (native number) + 편 + 을 (object); 보다 → 봤어요" } },
    "저기요|interjection": { korean: "저기요", note: "'Excuse me' — the standard way to get a stranger's or a server's attention. 여기요 does the same job in a restaurant when calling staff over.", example: { ko: "저기요, 이것 좀 주세요.", en: "Excuse me, could I have this please.", form: "저기 + 요 (politeness particle), used as an attention-getter" } },
    "중학교|noun": { korean: "중학교", note: "Middle school, years 7 to 9. Between 초등학교 and 고등학교. A pupil there is a 중학생.", example: { ko: "중학교 때 친구예요.", en: "He is a friend from middle school.", form: "중학교 + 때 (bound noun); 친구 + 예요 (이다 after a vowel)" } },
    "생활 습관|noun phrase": { korean: "생활 습관", note: "Lifestyle habits — a set phrase in health and self-improvement reading. 습관 is a habit; 버릇 is a habit with a negative colouring.", example: { ko: "생활 습관을 바꿔야 해요.", en: "I need to change my lifestyle habits.", form: "생활 습관 + 을 (object); 바꾸다 → 바꿔야 해요 (obligation)" } },
    "벗다|verb": { korean: "벗다", note: "To take off clothing or shoes — the opposite of 입다 and 신다. Korean homes require 신발을 벗다 at the door.", example: { ko: "여기서 신발을 벗으세요.", en: "Please take off your shoes here.", form: "신발 + 을 (object); 벗다 → 벗으세요 (polite request after a batchim)" } },
    "뿐|dependent noun": { korean: "뿐", note: "'Only, nothing but', after a modifier or a noun: 그것뿐이에요. It builds -을 뿐만 아니라 ('not only'), which is where you will meet it most.", example: { ko: "그것뿐이에요.", en: "That is all there is.", form: "그것 + 뿐 + 이에요 (이다 after a batchim)" } },
    "그쪽|pronoun": { korean: "그쪽", note: "'That side', and a slightly distancing way to say 'you' when you do not know or want to use someone's name. Neutral in a shop, cool in an argument.", example: { ko: "그쪽은 어떻게 생각하세요?", en: "What do you think?", form: "그쪽 + 은 (topic); 생각하다 + 시 → 생각하세요 (honorific question)" } },
    "약속을 지키다|expression": { korean: "약속을 지키다", note: "'To keep a promise.' 지키다 is 'to guard or uphold' — the opposite is 약속을 어기다, to break one.", example: { ko: "약속을 꼭 지킬게요.", en: "I will definitely keep my promise.", form: "약속 + 을 (object); 지키다 → 지킬게요 (intention, polite casual)" } },
    "이라고|particle": { korean: "이라고", note: "The quoting particle after a noun: 제 이름은 민수라고 해요. 라고 after a vowel. It introduces what something is called or what was said.", example: { ko: "민수라고 해요.", en: "My name is Minsu.", form: "민수 ends in a vowel so it takes 라고; a batchim noun takes 이라고: 선생님이라고" } },
    "표|noun": { korean: "표", note: "A ticket, counted with 장 like other flat things: 표 두 장. It also means a chart or table in a document.", example: { ko: "기차표를 샀어요.", en: "I bought a train ticket.", form: "기차표 + 를 (object); 사다 → 샀어요 (past, polite casual)" } },
    // ================================================================ day 18
    "거울|noun": { korean: "거울", note: "A mirror. You look in one with 보다: 거울을 봐요. The idiom 거울로 삼다 means to take something as a model.", example: { ko: "거울을 보고 있어요.", en: "I am looking in the mirror.", form: "거울 + 을 (object); 보다 → 보고 있어요 (progressive, present)" } },
    "노력을 기울이다|expression": { korean: "노력을 기울이다", note: "'To put in effort.' 기울이다 is literally 'to tilt or pour', so the effort is poured into something. Written register; 노력하다 is the everyday verb.", example: { ko: "많은 노력을 기울였어요.", en: "They put in a great deal of effort.", form: "노력 + 을 (object); 기울이다 → 기울였어요 (past, polite casual)" } },
    "돕다|verb": { korean: "돕다", note: "To help. ㅂ-irregular, and unusually it becomes 도와요, not 도워요 — one of only two verbs (with 곱다) that take ㅗ here. The person helped takes 을/를.", example: { ko: "친구를 도왔어요.", en: "I helped my friend.", form: "친구 + 를 (object); 돕다 → 도왔어요 (ㅂ-irregular with ㅗ, past)" } },
    "똑같다|adjective": { korean: "똑같다", note: "To be exactly the same — 같다 intensified by 똑. What it matches takes 와/과 or 하고.", example: { ko: "두 개가 똑같아요.", en: "The two are exactly the same.", form: "두 개 + 가 (subject); 똑같다 → 똑같아요 (present, polite casual)" } },
    "부엌|noun": { korean: "부엌", note: "A kitchen. Pronounced [부억]. 주방 is the more formal word used for restaurant kitchens.", example: { ko: "어머니가 부엌에 계세요.", en: "Mother is in the kitchen.", form: "부엌 + 에 (location); 계시다 (honorific 있다) → 계세요" } },
    "북쪽|noun": { korean: "북쪽", note: "The north. Completes the compass set with 동쪽, 서쪽, 남쪽, all built on 쪽.", example: { ko: "북쪽으로 가면 산이 있어요.", en: "If you go north there is a mountain.", form: "북쪽 + 으로 (direction); 가다 → 가면 (conditional); 있다 → 있어요" } },
    "대로|dependent noun": { korean: "대로", note: "'As, in accordance with', after a noun or modifier: 계획대로, 말한 대로. After a noun it attaches directly with no space.", example: { ko: "계획대로 진행했어요.", en: "We proceeded according to plan.", form: "계획 + 대로; 진행하다 → 진행했어요 (past, polite casual)" } },
    "말다|auxiliary verb": { korean: "말다", note: "-지 말다 forms a prohibition: 가지 마세요 = do not go. It only works with commands and suggestions, never with a plain statement — for that you need 안 or -지 않다.", example: { ko: "여기서 담배를 피우지 마세요.", en: "Please do not smoke here.", form: "피우다 → 피우지 (connector) + 말다 → 마세요 (ㄹ drops; polite prohibition)" } },
    "쇠고기|noun": { korean: "쇠고기", note: "Beef. 소고기 is the equally correct and more common spelling. The set runs 소고기 / 돼지고기 / 닭고기.", example: { ko: "쇠고기를 사 왔어요.", en: "I bought some beef.", form: "쇠고기 + 를 (object); 사다 → 사 + 오다 → 왔어요 (past)" } },
    "결혼하다|verb": { korean: "결혼하다", note: "To get married. The spouse takes 와/과 or 하고, never 을/를: 친구와 결혼했어요. Saying 친구를 결혼했어요 is a common learner error.", example: { ko: "작년에 결혼했어요.", en: "I got married last year.", form: "작년 + 에 (time); 결혼하다 → 결혼했어요 (past, polite casual)" } },
    "그뿐만 아니라|conjunction": { korean: "그뿐만 아니라", note: "'Not only that', adding a further point across sentences. Inside one sentence, use -을 뿐만 아니라 instead.", example: { ko: "값이 싸요. 그뿐만 아니라 질도 좋아요.", en: "It is cheap. Not only that, the quality is good too.", form: "그뿐만 아니라 opens the clause; 좋다 → 좋아요" } },
    "스트레스를 받다|expression": { korean: "스트레스를 받다", note: "'To get stressed.' Korean receives stress rather than feeling it — 스트레스가 있다 is unidiomatic. Relieving it is 스트레스를 풀다.", example: { ko: "요즘 스트레스를 많이 받아요.", en: "I have been very stressed lately.", form: "스트레스 + 를 (object); 받다 → 받아요 (present, polite casual)" } },
    "주|noun": { korean: "주", note: "A week. 이번 주, 다음 주, 지난주 — note 지난주 is written solid while the others take a space.", example: { ko: "다음 주에 시험이 있어요.", en: "There is an exam next week.", form: "주 + 에 (time particle); 시험 + 이 (subject); 있다 → 있어요" } },
    "요|particle": { korean: "요", note: "The politeness particle, tacked onto almost anything to make it polite: 저는요, 왜요?, 네요. It is what separates casual 응 from polite 응요 in tone.", example: { ko: "저는요, 학생이에요.", en: "As for me, I am a student.", form: "저 + 는 + 요 (politeness particle attached to a phrase)" } },
    "곡|counter": { korean: "곡", note: "The counter for songs and musical pieces: 노래 한 곡, 두 곡. Takes native Korean numbers.", example: { ko: "노래 한 곡 불러 주세요.", en: "Please sing one song.", form: "노래 + 한 (native number) + 곡; 부르다 → 불러 + 주다 → 주세요" } },
    "여보|interjection": { korean: "여보", note: "'Honey, dear' — how married couples address each other. Only between spouses; using it otherwise is odd. 자기 is the equivalent for dating couples.", example: { ko: "여보, 어디에 있어요?", en: "Honey, where are you?", form: "Direct address; 있다 → 있어요 (question)" } },
    "단어|noun": { korean: "단어", note: "A word as a vocabulary item. 말 is speech or words in general; 단어 is what you look up in a dictionary.", example: { ko: "새 단어를 외웠어요.", en: "I memorised the new words.", form: "단어 + 를 (object); 외우다 → 외웠어요 (past, polite casual)" } },
    "계시다|verb": { korean: "계시다", note: "The honorific of 있다 for people you respect: 선생님이 계세요. For things, the honorific is 있으시다 instead — 시간이 있으세요, not 계세요.", example: { ko: "할아버지가 집에 계세요.", en: "Grandfather is at home.", form: "할아버지 + 가 (subject); 계시다 → 계세요 (honorific present)" } },
    "거|pronoun": { korean: "거", note: "'That thing', the spoken contraction of 것 used as a pronoun. It fuses with particles: 거 + 이 becomes 게.", example: { ko: "그거 좋네요.", en: "That is nice.", form: "그 + 거; 좋다 → 좋네요 (present, remarking, polite casual)" } },
    "신발|noun": { korean: "신발", note: "Shoes, counted with 켤레 for pairs. You put them on with 신다 and take them off with 벗다 — never 입다, which is for clothing on the body.", example: { ko: "신발을 신으세요.", en: "Please put on your shoes.", form: "신발 + 을 (object); 신다 → 신으세요 (polite request after a batchim)" } },
    "감기에 걸리다|expression": { korean: "감기에 걸리다", note: "'To catch a cold.' The illness takes 에 and the verb is 걸리다 — you are caught by it. 감기를 잡다 would be wrong.", example: { ko: "감기에 걸렸어요.", en: "I have caught a cold.", form: "감기 + 에; 걸리다 → 걸렸어요 (past, polite casual)" } },
    "이쪽으로 오세요|phrase": { korean: "이쪽으로 오세요", note: "'Please come this way' — what a host or server says while showing you to a seat. 이쪽 takes 으로 for direction.", example: { ko: "이쪽으로 오세요. 자리가 있어요.", en: "Please come this way. There is a seat.", form: "이쪽 + 으로 (direction); 오다 → 오세요 (polite request)" } },
    "식사 예절|noun phrase": { korean: "식사 예절", note: "Table manners — a common cultural reading topic. Korean etiquette expects elders to lift their spoon first and no one to leave before them.", example: { ko: "식사 예절을 배웠어요.", en: "I learned table manners.", form: "식사 예절 + 을 (object); 배우다 → 배웠어요 (past)" } },
    "어제|noun": { korean: "어제", note: "Yesterday, as a noun so it takes particles: 어제는, 어제까지. Like 오늘 it works bare as an adverb — 어제에 is wrong.", example: { ko: "어제는 아주 바빴어요.", en: "Yesterday I was very busy.", form: "어제 + 는 (topic); 바쁘다 → 바빴어요 (ㅡ drops, past)" } },
    "넷째|determiner": { korean: "넷째", note: "'Fourth' in front of a noun: 넷째 아이. Built regularly on 넷.", example: { ko: "넷째 주에 만나요.", en: "Let us meet in the fourth week.", form: "넷째 + 주 + 에 (time); 만나다 → 만나요 (suggestion)" } },
    "만큼|dependent noun": { korean: "만큼", note: "'As much as', after a noun or modifier: 저만큼, 생각한 만큼. After a noun it attaches with no space.", example: { ko: "생각한 만큼 어렵지 않아요.", en: "It is not as hard as I thought.", form: "생각하다 → 생각한 (past modifier) + 만큼; 어렵다 → 어렵지 않아요" } },
    "칼|noun": { korean: "칼", note: "A knife, counted with 자루. 칼로 자르다 is to cut with a knife, using the instrument particle 로.", example: { ko: "칼로 자르세요.", en: "Please cut it with a knife.", form: "칼 + 로 (instrument, after a batchim ㄹ); 자르다 → 자르세요" } },
    "잠시|adverb": { korean: "잠시", note: "'For a moment', slightly more formal than 잠깐. 잠시만 기다려 주세요 is the standard 'please wait a moment'.", example: { ko: "잠시 기다려 주세요.", en: "Please wait a moment.", form: "잠시 before the verb; 기다리다 → 기다려 + 주다 → 주세요" } },
    "이며|particle": { korean: "이며", note: "'And', listing nouns in a written or literary register: 책이며 공책이며. 며 after a vowel. In speech, 하고 or 랑.", example: { ko: "책이며 공책이며 다 샀어요.", en: "I bought books, notebooks, everything.", form: "책 + 이며 (after a batchim); 사다 → 샀어요 (past)" } },
    "시험을 보다|expression": { korean: "시험을 보다", note: "'To take an exam.' Korean uses 보다, not 하다 or 받다. Passing is 시험에 붙다 and failing 시험에 떨어지다.", example: { ko: "내일 시험을 봐요.", en: "I take an exam tomorrow.", form: "시험 + 을 (object); 보다 → 봐요 (present, polite casual)" } },
    "미안하다|adjective": { korean: "미안하다", note: "To be sorry, for something small among equals. 죄송하다 is the deferential version for elders and strangers, and is the safer default.", example: { ko: "늦어서 미안해요.", en: "I am sorry for being late.", form: "늦다 → 늦어서 (cause); 미안하다 → 미안해요 (present, polite casual)" } },
    "카메라|noun": { korean: "카메라", note: "A camera. Taking a photo with it is 카메라로 사진을 찍다, using the instrument particle 로.", example: { ko: "카메라로 사진을 찍었어요.", en: "I took a photo with the camera.", form: "카메라 + 로 (instrument); 사진 + 을 (object); 찍다 → 찍었어요" } },
    "경찰관|noun": { korean: "경찰관", note: "A police officer, the formal job title. 경찰 alone is the police as an institution, and is what people say in conversation.", example: { ko: "경찰관이 도와줬어요.", en: "A police officer helped me.", form: "경찰관 + 이 (subject); 도와주다 → 도와줬어요 (past)" } },
    "극장|noun": { korean: "극장", note: "A cinema or theatre. 영화관 is the more current word for a movie theatre; 극장 also covers stage venues.", example: { ko: "극장에서 영화를 봤어요.", en: "I watched a film at the cinema.", form: "극장 + 에서 (action-location); 보다 → 봤어요 (past)" } },
    "계획을 세우다|expression": { korean: "계획을 세우다", note: "'To make a plan.' 세우다 is 'to stand something up' — Korean erects a plan rather than making one. 계획을 만들다 is unidiomatic.", example: { ko: "여행 계획을 세웠어요.", en: "I made a travel plan.", form: "계획 + 을 (object); 세우다 → 세웠어요 (past, polite casual)" } },

    // ================================================================ day 19
    "오랜만|noun": { korean: "오랜만", note: "'After a long time', mostly in 오랜만이에요 and 오랜만에. 오랫동안 is the adverb for 'for a long time'.", example: { ko: "오랜만에 친구를 만났어요.", en: "I met a friend after a long time.", form: "오랜만 + 에 (time particle); 만나다 → 만났어요 (past)" } },
    "여기 있어요|phrase": { korean: "여기 있어요", note: "'Here it is' — handing something over. 여기요 is the shorter version, which doubles as a way to call a server.", example: { ko: "여기 있어요. 받으세요.", en: "Here it is. Please take it.", form: "여기 + 있다 → 있어요 (present, polite casual)" } },
    "저거|pronoun": { korean: "저거", note: "'That thing over there', the spoken contraction of 저것. It fuses with particles: 저거 + 이 becomes 저게.", example: { ko: "저거 주세요.", en: "Please give me that one over there.", form: "저거 with the object particle dropped, as is normal in speech; 주다 → 주세요" } },
    "층|counter": { korean: "층", note: "The counter for floors of a building, with Sino-Korean numbers: 삼 층, 오 층. It is also the noun 'floor' itself.", example: { ko: "이 건물은 오 층이에요.", en: "This building has five floors.", form: "오 (Sino-Korean) + 층 + 이에요 (이다 after a batchim)" } },
    "자|interjection": { korean: "자", note: "'Now then' — marking a transition, calling attention, or handing something over. Teachers and hosts use it constantly.", example: { ko: "자, 시작합시다.", en: "Now then, let us begin.", form: "Interjection; 시작하다 → 시작합시다 (formal suggestion)" } },
    "아줌마|noun": { korean: "아줌마", note: "The casual form of 아주머니, used to address a middle-aged woman. It can sound blunt or even rude depending on tone — 아주머니 or 사장님 is safer in a shop.", example: { ko: "아줌마, 여기 주문할게요.", en: "Excuse me, I would like to order.", form: "Direct address; 주문하다 → 주문할게요 (intention)" } },
    "다만|conjunction": { korean: "다만", note: "'But, only' — adding a single qualification to what you just said. Formal and written, softer than 하지만.", example: { ko: "좋아요. 다만 값이 조금 비싸요.", en: "It is good. Only, the price is a bit high.", form: "다만 opens the qualifying clause; 비싸다 → 비싸요" } },
    "도착하다|verb": { korean: "도착하다", note: "To arrive. The place takes 에: 서울에 도착했어요. Its opposite is 출발하다 (to depart).", example: { ko: "공항에 도착했어요.", en: "I arrived at the airport.", form: "공항 + 에 (destination); 도착하다 → 도착했어요 (past)" } },
    "유명하다|adjective": { korean: "유명하다", note: "To be famous. What it is famous for takes 로/으로: 김치로 유명해요.", example: { ko: "이 식당은 냉면으로 유명해요.", en: "This restaurant is famous for cold noodles.", form: "냉면 + 으로 (for, after a batchim); 유명하다 → 유명해요" } },
    "치고|particle": { korean: "치고", note: "'For a, considering' — setting an expectation the thing then defies: 겨울치고 따뜻해요. Often followed by a surprising judgement.", example: { ko: "겨울치고 따뜻해요.", en: "It is warm for winter.", form: "겨울 + 치고 (considering); 따뜻하다 → 따뜻해요" } },
    "군인|noun": { korean: "군인", note: "A soldier. Korean men do compulsory military service, so 군대에 가다 ('to go to the army') is a common life-stage topic.", example: { ko: "형은 지금 군인이에요.", en: "My older brother is a soldier now.", form: "형 + 은 (topic); 군인 + 이에요 (이다 after a batchim)" } },
    "결정을 내리다|expression": { korean: "결정을 내리다", note: "'To make a decision.' Korean brings a decision down rather than making it. 결정하다 is the simpler everyday verb.", example: { ko: "어려운 결정을 내렸어요.", en: "I made a difficult decision.", form: "결정 + 을 (object); 내리다 → 내렸어요 (past, polite casual)" } },
    "적다|verb": { korean: "적다", note: "To write down or jot. The same shape is also the adjective 'to be few', which is a separate entry — context and particles separate them.", example: { ko: "이름을 여기에 적으세요.", en: "Please write your name here.", form: "이름 + 을 (object); 적다 → 적으세요 (polite request after a batchim)" } },
    "다섯째|determiner": { korean: "다섯째", note: "'Fifth' in front of a noun: 다섯째 날. Built regularly on 다섯.", example: { ko: "다섯째 날에 도착했어요.", en: "We arrived on the fifth day.", form: "다섯째 + 날 + 에 (time); 도착하다 → 도착했어요" } },
    "교통 체증|noun phrase": { korean: "교통 체증", note: "Traffic congestion, the formal term. In speech Koreans say 길이 막히다 ('the road is blocked') instead.", example: { ko: "교통 체증이 심해요.", en: "The traffic congestion is severe.", form: "교통 체증 + 이 (subject); 심하다 → 심해요" } },
    "구름|noun": { korean: "구름", note: "A cloud. 구름이 끼다 is 'to become cloudy'; 흐리다 is the adjective for overcast weather.", example: { ko: "하늘에 구름이 많아요.", en: "There are many clouds in the sky.", form: "하늘 + 에 (location); 구름 + 이 (subject); 많다 → 많아요" } },
    "말씀하다|verb": { korean: "말씀하다", note: "The honorific of 말하다, for what a respected person says: 선생님이 말씀하셨어요. To humble your own speech, use 말씀드리다 instead.", example: { ko: "선생님이 말씀하셨어요.", en: "The teacher said so.", form: "말씀하다 + 시 → 말씀하셨어요 (honorific past, polite casual)" } },
    "얼마예요|phrase": { korean: "얼마예요", note: "'How much is it?' — the single most useful shopping phrase. 이거 얼마예요? points at the item.", example: { ko: "이거 얼마예요?", en: "How much is this?", form: "얼마 + 예요 (이다 after a vowel; question)" } },
    "동쪽|noun": { korean: "동쪽", note: "The east. Part of the compass set with 서쪽, 남쪽, 북쪽.", example: { ko: "해는 동쪽에서 떠요.", en: "The sun rises in the east.", form: "동쪽 + 에서 (source); 뜨다 → 떠요 (ㅡ drops before -어요)" } },
    "으로부터|particle": { korean: "으로부터", note: "'From', marking a source — a person, an organisation, or a starting point. 로부터 after a vowel. More formal than 에게서.", example: { ko: "회사로부터 연락을 받았어요.", en: "I received contact from the company.", form: "회사 + 로부터 (source, after a vowel); 받다 → 받았어요" } },
    "소개하다|verb": { korean: "소개하다", note: "To introduce. The person introduced takes 을/를 and the person they meet takes 에게/한테: 친구에게 동생을 소개했어요.", example: { ko: "친구를 소개할게요.", en: "I will introduce my friend.", form: "친구 + 를 (object); 소개하다 → 소개할게요 (intention)" } },
    "잠깐|noun": { korean: "잠깐", note: "A brief moment, used as a noun so it takes particles: 잠깐만요, 잠깐 동안. As an adverb it needs none.", example: { ko: "잠깐만 기다리세요.", en: "Please wait just a moment.", form: "잠깐 + 만 (only); 기다리다 → 기다리세요 (polite request)" } },
    "조금|adverb": { korean: "조금", note: "'A little', before the verb or adjective: 조금 비싸요. Contracts to 좀 in speech, where it also softens requests.", example: { ko: "조금 비싸요.", en: "It is a little expensive.", form: "조금 before the adjective; 비싸다 → 비싸요" } },
    "채|dependent noun": { korean: "채", note: "'As it is, still in that state', after a past modifier: 신발을 신은 채로 들어왔어요. It marks an unchanged condition during another action.", example: { ko: "신발을 신은 채로 들어왔어요.", en: "He came in still wearing his shoes.", form: "신다 → 신은 (past modifier) + 채로; 들어오다 → 들어왔어요" } },
    "내다|auxiliary verb": { korean: "내다", note: "-어 내다 means managing to do something through effort, seeing it through: 참아 냈어요. It stresses overcoming difficulty.", example: { ko: "결국 이겨 냈어요.", en: "In the end I managed to overcome it.", form: "이기다 → 이겨 (connector) + 내다 → 냈어요 (past)" } },
    "도움이 되다|expression": { korean: "도움이 되다", note: "'To be of help.' Note the subject particle — the help is what becomes, so 도움이, never 도움을.", example: { ko: "많은 도움이 됐어요.", en: "It was a great help.", form: "도움 + 이 (subject of 되다); 되다 → 됐어요 (past)" } },
    "한복|noun": { korean: "한복", note: "Hanbok, Korean traditional dress. Worn with 입다. It appears at 설날 and 추석 and in cultural reading passages.", example: { ko: "설날에 한복을 입어요.", en: "We wear hanbok at Lunar New Year.", form: "설날 + 에 (time); 한복 + 을 (object); 입다 → 입어요" } },
    "끝내다|verb": { korean: "끝내다", note: "To finish something — transitive, taking an object: 일을 끝냈어요. Its intransitive partner is 끝나다, for something that ends by itself.", example: { ko: "숙제를 끝냈어요.", en: "I finished my homework.", form: "숙제 + 를 (object); 끝내다 → 끝냈어요 (past, polite casual)" } },
    "칸|counter": { korean: "칸", note: "The counter for compartments, rooms and grid squares: 방 한 칸, 지하철 세 칸. Takes native Korean numbers.", example: { ko: "다음 칸으로 가세요.", en: "Please move to the next carriage.", form: "칸 + 으로 (direction); 가다 → 가세요 (polite request)" } },
    "글쎄|interjection": { korean: "글쎄", note: "'Well, I am not sure' — hedging or declining to commit. 글쎄요 is the polite form and is a very common way to avoid answering directly.", example: { ko: "글쎄요, 잘 모르겠어요.", en: "Well, I am not really sure.", form: "글쎄 + 요 (politeness particle)" } },
    "테이블|noun": { korean: "테이블", note: "A table, the borrowed word, used mostly for restaurant and café tables. 식탁 is a dining table at home and 책상 a desk.", example: { ko: "테이블 위에 놓으세요.", en: "Please put it on the table.", form: "테이블 위 + 에 (location); 놓다 → 놓으세요 (polite request)" } },
    "단|conjunction": { korean: "단", note: "'However, provided that' — attaching a condition to what was just granted. Formal, common in notices and rules.", example: { ko: "들어가도 돼요. 단, 조용히 하세요.", en: "You may go in. However, be quiet.", form: "단 opens the condition; 조용히 하다 → 하세요 (polite request)" } },

    // ================================================================ day 20
    "마음에 들다|expression": { korean: "마음에 들다", note: "'To like' something on sight — it suits your taste. The thing takes 이/가: 이 옷이 마음에 들어요. Different from 좋아하다, which is a settled preference.", example: { ko: "이 옷이 마음에 들어요.", en: "I like these clothes.", form: "옷 + 이 (subject); 마음 + 에; 들다 → 들어요 (present, polite casual)" } },
    "각|determiner": { korean: "각", note: "'Each', in front of a noun: 각 나라, 각 학생. Formal and written; in speech Koreans say 각각 or use 마다.", example: { ko: "각 나라마다 문화가 달라요.", en: "Each country has a different culture.", form: "각 + 나라 + 마다 (every); 다르다 → 달라요 (르-irregular)" } },
    "드리다|verb": { korean: "드리다", note: "The humble form of 주다, used when giving to someone you respect: 선생님께 드렸어요. It pairs with 께, not 에게.", example: { ko: "선생님께 선물을 드렸어요.", en: "I gave the teacher a present.", form: "선생님 + 께 (honorific recipient); 드리다 → 드렸어요 (humble, past)" } },
    "한자|noun": { korean: "한자", note: "Hanja, the Chinese characters used in Korean. Around 60% of Korean vocabulary is Sino-Korean, so knowing hanja roots helps guess new words.", example: { ko: "한자를 배우면 단어가 쉬워져요.", en: "If you learn hanja, words get easier.", form: "한자 + 를 (object); 배우다 → 배우면 (conditional); 쉬워지다 → 쉬워져요" } },
    "이야말로|particle": { korean: "이야말로", note: "'Indeed, precisely' — singling something out as the true example: 이것이야말로 진짜예요. 야말로 after a vowel. Emphatic and written.", example: { ko: "이것이야말로 진짜 한국 음식이에요.", en: "This is precisely real Korean food.", form: "이것 + 이야말로 (after a batchim); 이다 → 이에요" } },
    "시|noun": { korean: "시", note: "Two senses: a poem, and a city as an administrative unit (서울시). The clock-hour 시 and the honorific infix 시 are separate entries.", example: { ko: "이 시가 아주 아름다워요.", en: "This poem is very beautiful.", form: "시 + 가 (subject); 아름답다 → 아름다워요 (ㅂ-irregular)" } },
    "계산해 주세요|phrase": { korean: "계산해 주세요", note: "'The bill, please' — what you say to pay at a restaurant. 계산 is calculation, so you are asking them to tally it up.", example: { ko: "저기요, 계산해 주세요.", en: "Excuse me, the bill please.", form: "계산하다 → 계산해 + 주다 → 주세요 (request)" } },
    "물어보다|verb": { korean: "물어보다", note: "To ask, softer than plain 묻다 because of the -어 보다 'try' ending. The person asked takes 에게/한테. ㄷ-irregular: 물어봐요.", example: { ko: "선생님한테 물어봤어요.", en: "I asked the teacher.", form: "선생님 + 한테 (recipient); 물어보다 → 물어봤어요 (past)" } },
    "김|dependent noun": { korean: "김", note: "'The opportunity, while at it', in -는 김에: 나가는 김에. It never stands alone. The food 김 (seaweed) is a different word.", example: { ko: "나가는 김에 우유 좀 사 오세요.", en: "While you are out, please buy some milk.", form: "나가다 → 나가는 (modifier) + 김에; 사다 → 사 + 오다 → 오세요" } },
    "신경을 쓰다|expression": { korean: "신경을 쓰다", note: "'To pay attention to' or 'to fret over'. 신경 is a nerve, so you are spending nerves. 신경 쓰지 마세요 is 'never mind'.", example: { ko: "너무 신경을 쓰지 마세요.", en: "Do not fret about it too much.", form: "신경 + 을 (object); 쓰다 → 쓰지 마세요 (polite prohibition)" } },
    "주차 공간|noun phrase": { korean: "주차 공간", note: "A parking space. 주차하다 is to park and 주차장 is a car park — all built on 주차.", example: { ko: "주차 공간이 부족해요.", en: "There is not enough parking space.", form: "주차 공간 + 이 (subject); 부족하다 → 부족해요" } },
    "뛰다|verb": { korean: "뛰다", note: "To run, and also to jump. Korean does not separate them — 뛰어가다 clarifies running somewhere and 뛰어오르다 jumping up.", example: { ko: "학교까지 뛰어갔어요.", en: "I ran to school.", form: "학교 + 까지 (as far as); 뛰다 → 뛰어 + 가다 → 갔어요 (past)" } },
    "구경|noun": { korean: "구경", note: "Sightseeing or having a look round. 구경하다 is the verb, and what you look at takes 을/를: 시장을 구경했어요.", example: { ko: "시장을 구경했어요.", en: "I looked around the market.", form: "시장 + 을 (object); 구경하다 → 구경했어요 (past)" } },
    "이분|pronoun": { korean: "이분", note: "'This person', honorific. Use it when introducing someone present who deserves respect: 이분은 제 선생님이세요.", example: { ko: "이분은 제 선생님이세요.", en: "This is my teacher.", form: "이분 + 은 (topic); 이다 + 시 → 이세요 (honorific present)" } },
    "천|numeral": { korean: "천", note: "'Thousand', Sino-Korean. The next unit up is 만 (ten thousand), not 십천 — Korean groups digits in fours.", example: { ko: "천 원이에요.", en: "It is a thousand won.", form: "천 + 원 (counter); 이다 → 이에요 (after a batchim)" } },
    "눈치를 보다|expression": { korean: "눈치를 보다", note: "'To read the room' — watching someone's mood to judge what to do. 눈치 is social awareness, and 눈치가 없다 ('to lack it') is a real criticism in Korea.", example: { ko: "상사의 눈치를 봤어요.", en: "I was reading my boss's mood.", form: "상사 + 의 (possessive); 눈치 + 를 (object); 보다 → 봤어요" } },
    "닭|noun": { korean: "닭", note: "A chicken, the animal. Pronounced [닥]. The meat is 닭고기 and fried chicken is 치킨, a separate borrowed word.", example: { ko: "닭이 울어요.", en: "The chicken is crowing.", form: "닭 + 이 (subject); 울다 → 울어요 (present, polite casual)" } },
    "이나마|particle": { korean: "이나마", note: "'Even if only', accepting something inadequate with resignation: 조금이나마 도움이 됐어요. 나마 after a vowel.", example: { ko: "조금이나마 도움이 됐으면 좋겠어요.", en: "I hope it helped, even if only a little.", form: "조금 + 이나마; 되다 → 됐으면 좋겠어요 (wish)" } },
    "않다|verb": { korean: "않다", note: "As a main verb it is rare — you will meet it almost always as the auxiliary in -지 않다. Its independent use appears mainly in written Korean.", example: { ko: "그렇지 않아요.", en: "That is not so.", form: "그렇다 → 그렇지 (connector) + 않다 → 않아요 (negated present)" } },
    "그러니까|adverb": { korean: "그러니까", note: "'So, that is why', used adverbially inside a sentence to point at a reason already given. The same shape also opens a sentence as a conjunction.", example: { ko: "그러니까 제가 말했잖아요.", en: "That is why I told you.", form: "그러니까 before the clause; 말하다 → 말했잖아요 (reminding)" } },
    "알|counter": { korean: "알", note: "The counter for small round things: 알약 두 알, 사과 한 알. Takes native Korean numbers. 개 is the general fallback.", example: { ko: "약을 두 알 먹었어요.", en: "I took two pills.", form: "약 + 을 (object); 두 (native number) + 알; 먹다 → 먹었어요" } },
    "참|interjection": { korean: "참", note: "'Oh right!' — said when something suddenly comes to mind mid-conversation. Often 아, 참! It also works as an adverb meaning 'really'.", example: { ko: "아, 참! 그 얘기를 잊었어요.", en: "Oh right! I forgot to mention that.", form: "Interjection; 잊다 → 잊었어요 (past, polite casual)" } },
    "교과서|noun": { korean: "교과서", note: "A school textbook. 책 is any book and 참고서 a reference or study guide.", example: { ko: "교과서를 가져오세요.", en: "Please bring your textbook.", form: "교과서 + 를 (object); 가져오다 → 가져오세요 (polite request)" } },
    "포장해 주세요|phrase": { korean: "포장해 주세요", note: "'To go, please' — asking for takeaway, or for a gift to be wrapped. 포장 is packaging, so it covers both.", example: { ko: "이거 포장해 주세요.", en: "Please pack this to go.", form: "포장하다 → 포장해 + 주다 → 주세요 (request)" } },
    "온갖|determiner": { korean: "온갖", note: "'All sorts of', in front of a noun: 온갖 문제. It suggests variety and often a touch of exasperation.", example: { ko: "온갖 문제가 생겼어요.", en: "All sorts of problems came up.", form: "온갖 + 문제 + 가 (subject); 생기다 → 생겼어요 (past)" } },
    "돼지|noun": { korean: "돼지", note: "A pig, counted with 마리. The meat is 돼지고기. Calling someone 돼지 is an insult about weight, as in English.", example: { ko: "농장에 돼지가 많아요.", en: "There are many pigs on the farm.", form: "농장 + 에 (location); 돼지 + 가 (subject); 많다 → 많아요" } },
    "셈|dependent noun": { korean: "셈", note: "'Reckoning, as good as', in -는 셈이다: 다 한 셈이에요. It sums a situation up as effectively equivalent to something.", example: { ko: "이만하면 성공한 셈이에요.", en: "At this point it amounts to a success.", form: "성공하다 → 성공한 (past modifier) + 셈이다 → 셈이에요" } },
    "다녀오다|verb": { korean: "다녀오다", note: "To go somewhere and come back — a round trip. 학교에 다녀왔어요 means you went and are now back, which plain 갔어요 does not convey.", example: { ko: "병원에 다녀왔어요.", en: "I went to the hospital and came back.", form: "병원 + 에 (destination); 다녀오다 → 다녀왔어요 (past)" } },
    "정신을 차리다|expression": { korean: "정신을 차리다", note: "'To come to one's senses' — snap out of confusion, or regain consciousness. 정신 차려! is a sharp 'pull yourself together'.", example: { ko: "정신을 차리고 다시 시작했어요.", en: "I pulled myself together and started again.", form: "정신 + 을 (object); 차리다 → 차리고 (connector); 시작하다 → 시작했어요" } },
    "결국|conjunction": { korean: "결국", note: "'In the end, after all' — the final outcome after a process. It usually opens the clause and pairs with a past tense.", example: { ko: "결국 포기했어요.", en: "In the end I gave up.", form: "결국 opens the clause; 포기하다 → 포기했어요 (past)" } },
    "식탁|noun": { korean: "식탁", note: "A dining table at home. 테이블 is the borrowed word used in cafés and restaurants; 책상 is a desk.", example: { ko: "식탁에 밥을 차렸어요.", en: "I set the meal on the dining table.", form: "식탁 + 에 (location); 밥 + 을 (object); 차리다 → 차렸어요" } },
    "반갑다|adjective": { korean: "반갑다", note: "To be glad to meet someone. ㅂ-irregular: 반가워요. 만나서 반가워요 is the standard 'nice to meet you' — it is only for people, never for things.", example: { ko: "만나서 반가워요.", en: "Nice to meet you.", form: "만나다 → 만나서 (cause); 반갑다 → 반가워요 (ㅂ-irregular)" } },
    "손을 잡다|expression": { korean: "손을 잡다", note: "'To hold hands', and figuratively 'to join forces'. Both senses are common; context decides.", example: { ko: "아이의 손을 잡았어요.", en: "I held the child's hand.", form: "아이 + 의 (possessive); 손 + 을 (object); 잡다 → 잡았어요" } },

    // ================================================================ day 21
    "날짜|noun": { korean: "날짜", note: "A calendar date. 며칠 asks what date it is; 요일 is the day of the week. 날 is a day as an occasion.", example: { ko: "날짜를 정했어요?", en: "Have you decided the date?", form: "날짜 + 를 (object); 정하다 → 정했어요 (past, question)" } },
    "이야|particle": { korean: "이야", note: "'As for, at least' — singling something out casually: 너야 잘하지. 야 after a vowel. Informal and spoken.", example: { ko: "너야 당연히 잘하지.", en: "As for you, of course you are good at it.", form: "너 + 야 (after a vowel); 잘하다 → 잘하지 (casual, assumed agreement)" } },
    "샌드위치|noun": { korean: "샌드위치", note: "A sandwich, counted with 개. A borrowed word, written to match Korean syllable structure.", example: { ko: "아침에 샌드위치를 먹었어요.", en: "I ate a sandwich in the morning.", form: "샌드위치 + 를 (object); 먹다 → 먹었어요 (past)" } },
    "저곳|pronoun": { korean: "저곳", note: "'That place over there' — the written equivalent of 저기. Completes 이곳 / 그곳 / 저곳.", example: { ko: "저곳이 제일 유명해요.", en: "That place over there is the most famous.", form: "저곳 + 이 (subject); 제일 + 유명하다 → 유명해요 (superlative)" } },
    "걸어가다|verb": { korean: "걸어가다", note: "To walk there, away from the speaker. Built from 걷다 + 가다. Its mirror is 걸어오다. 걷다 alone is just the act of walking.", example: { ko: "학교까지 걸어갔어요.", en: "I walked to school.", form: "학교 + 까지 (as far as); 걸어가다 → 걸어갔어요 (past)" } },
    "언제나|adverb": { korean: "언제나", note: "'Always, every time' — a warmer and slightly more literary 항상. Both sit before the verb.", example: { ko: "언제나 응원할게요.", en: "I will always support you.", form: "언제나 before the verb; 응원하다 → 응원할게요 (intention)" } },
    "서쪽|noun": { korean: "서쪽", note: "The west. Completes the compass set with 동쪽, 남쪽, 북쪽.", example: { ko: "해가 서쪽으로 져요.", en: "The sun sets in the west.", form: "서쪽 + 으로 (direction); 지다 → 져요 (present, polite casual)" } },
    "경찰서|noun": { korean: "경찰서", note: "A police station. 서 is the suffix for such offices — 소방서 is a fire station. 경찰 alone is the police.", example: { ko: "경찰서에 신고했어요.", en: "I reported it to the police station.", form: "경찰서 + 에 (destination); 신고하다 → 신고했어요 (past)" } },
    "길을 잃다|expression": { korean: "길을 잃다", note: "'To lose one's way.' Korean loses the road, not itself. 길을 잃어버리다 adds finality and is more common in speech.", example: { ko: "산에서 길을 잃었어요.", en: "I lost my way on the mountain.", form: "산 + 에서 (location); 길 + 을 (object); 잃다 → 잃었어요" } },
    "길을 잃었어요|phrase": { korean: "길을 잃었어요", note: "'I am lost' — the sentence to have ready when travelling. Follow it with 여기가 어디예요? to ask where you are.", example: { ko: "죄송해요, 길을 잃었어요.", en: "Sorry, I am lost.", form: "길 + 을 (object); 잃다 → 잃었어요 (past, polite casual)" } },
    "도와주세요|phrase": { korean: "도와주세요", note: "'Please help me' — the -어 주다 ending is what makes it a request rather than an order. Without it, 도우세요 sounds like a command.", example: { ko: "좀 도와주세요.", en: "Please help me.", form: "돕다 → 도와 (ㅂ-irregular) + 주다 → 주세요 (request)" } },
    "듯|dependent noun": { korean: "듯", note: "'As if, seemingly', after a modifier: 아는 듯해요. It hedges an observation and is often extended to 듯하다 or 듯이.", example: { ko: "비가 올 듯해요.", en: "It seems like it will rain.", form: "오다 → 올 (modifier) + 듯하다 → 듯해요 (supposition)" } },
    "근무 환경|noun phrase": { korean: "근무 환경", note: "Working conditions — a set phrase in reading about employment. 근무 is duty or service at work; 직장 is the workplace itself.", example: { ko: "근무 환경이 좋아졌어요.", en: "The working conditions have improved.", form: "근무 환경 + 이 (subject); 좋아지다 → 좋아졌어요 (past)" } },
    "안녕하다|adjective": { korean: "안녕하다", note: "'To be well, at peace' — the root of 안녕하세요 and 안녕히 가세요. As a standalone adjective it is rare; you meet it inside those fixed greetings.", example: { ko: "그동안 안녕하셨어요?", en: "Have you been well?", form: "안녕하다 + 시 → 안녕하셨어요 (honorific past, question)" } },
    "여학생|noun": { korean: "여학생", note: "A female student. Its pair is 남학생. Built from 여 (female) + 학생, the same way as 여자 and 남자.", example: { ko: "여학생이 세 명 있어요.", en: "There are three female students.", form: "여학생 + 이 (subject); 세 명 (native number + counter); 있다 → 있어요" } },
    "옛|determiner": { korean: "옛", note: "'Old, former', in front of a noun: 옛 친구, 옛 기억. It only modifies — the noun 옛날 covers 'the old days'.", example: { ko: "옛 친구를 만났어요.", en: "I met an old friend.", form: "옛 + 친구 + 를 (object); 만나다 → 만났어요 (past)" } },
    "자리|counter": { korean: "자리", note: "The counter for seats and places: 한 자리, 두 자리. Takes native Korean numbers. It is also the noun 'seat'.", example: { ko: "두 자리 있어요?", en: "Are there two seats?", form: "두 (native number) + 자리; 있다 → 있어요 (question)" } },
    "어라|interjection": { korean: "어라", note: "'Huh?' — surprise at something unexpected or not working as it should. Casual and spontaneous.", example: { ko: "어라, 문이 안 열려요.", en: "Huh, the door will not open.", form: "Interjection; 열리다 → 안 열려요 (negated present)" } },
    "졸업하다|verb": { korean: "졸업하다", note: "To graduate. The school takes 을/를, not 에서: 대학교를 졸업했어요. Its opposite is 입학하다 (to enrol).", example: { ko: "작년에 대학교를 졸업했어요.", en: "I graduated from university last year.", form: "대학교 + 를 (object); 졸업하다 → 졸업했어요 (past)" } },
    "이든가|particle": { korean: "이든가", note: "'Or, whichever', offering options: 커피든가 차든가. 든가 after a vowel. Close to 이든지 and equally casual.", example: { ko: "커피든가 차든가 주세요.", en: "Give me coffee or tea, either one.", form: "커피 + 든가 (after a vowel); 주다 → 주세요" } },
    "기회를 잡다|expression": { korean: "기회를 잡다", note: "'To seize an opportunity.' Korean grabs the chance, as English does. Missing one is 기회를 놓치다.", example: { ko: "좋은 기회를 잡았어요.", en: "I seized a good opportunity.", form: "기회 + 를 (object); 잡다 → 잡았어요 (past, polite casual)" } },
    "육십|numeral": { korean: "육십", note: "Sixty, Sino-Korean. Its native partner 예순 is used for ages and counting objects.", example: { ko: "육십 명이 왔어요.", en: "Sixty people came.", form: "육십 + 명 (counter) + 이 (subject); 오다 → 왔어요" } },
    "팔십|numeral": { korean: "팔십", note: "Eighty, Sino-Korean. Its native partner is 여든.", example: { ko: "할아버지는 팔십 세이세요.", en: "Grandfather is eighty years old.", form: "팔십 (Sino-Korean) + 세 (formal age counter); 이다 + 시 → 이세요" } },
    "결혼식|noun": { korean: "결혼식", note: "A wedding ceremony. 식 is the suffix for formal ceremonies — 졸업식 is a graduation, 입학식 an entrance ceremony.", example: { ko: "친구 결혼식에 갔어요.", en: "I went to a friend's wedding.", form: "결혼식 + 에 (destination); 가다 → 갔어요 (past)" } },
    "아니|adverb": { korean: "아니", note: "'No, not', used adverbially before a verb in written Korean: 아니 가다. In speech you will meet 안 instead.", example: { ko: "아니 갈 수도 없어요.", en: "Nor can I not go.", form: "아니 before the verb; 가다 → 갈 수도 없어요 (impossibility)" } },
    "대신에|conjunction": { korean: "대신에", note: "'Instead', offering a replacement: 커피 대신에 차를 마셨어요. After a noun it attaches directly; after a verb it is -는 대신에.", example: { ko: "커피 대신에 차를 마셨어요.", en: "I drank tea instead of coffee.", form: "커피 + 대신에; 차 + 를 (object); 마시다 → 마셨어요" } },
    "목숨을 걸다|expression": { korean: "목숨을 걸다", note: "'To risk one's life.' 걸다 is 'to stake or wager', so the life is put on the line. Strong, and used figuratively for total commitment.", example: { ko: "목숨을 걸고 싸웠어요.", en: "They fought risking their lives.", form: "목숨 + 을 (object); 걸다 → 걸고 (connector); 싸우다 → 싸웠어요" } },
    "바|dependent noun": { korean: "바", note: "'The thing, what', after a modifier — formal and written: 아는 바가 없어요. In speech, 것 fills the same slot.", example: { ko: "제가 아는 바가 없어요.", en: "There is nothing that I know of.", form: "알다 → 아는 (modifier) + 바 + 가 (subject); 없다 → 없어요" } },
    "목욕|noun": { korean: "목욕", note: "A bath. 목욕하다 is to bathe and 목욕탕 is a public bathhouse, a Korean institution worth knowing about.", example: { ko: "목욕을 하고 잤어요.", en: "I took a bath and slept.", form: "목욕 + 을 (object); 하다 → 하고 (connector); 자다 → 잤어요" } },
    "날다|verb": { korean: "날다", note: "To fly. ㄹ-irregular: 납니다, 나세요. Do not confuse it with 날 (day) or 나다 (to occur).", example: { ko: "새가 하늘을 날아요.", en: "A bird flies through the sky.", form: "새 + 가 (subject); 하늘 + 을 (path); 날다 → 날아요" } },
    "지갑|noun": { korean: "지갑", note: "A wallet or purse. 동전 지갑 is a coin purse. Losing one is 지갑을 잃어버리다.", example: { ko: "지갑을 잃어버렸어요.", en: "I lost my wallet.", form: "지갑 + 을 (object); 잃어버리다 → 잃어버렸어요 (past)" } },
    "하며|particle": { korean: "하며", note: "'And', listing nouns in speech: 책하며 공책하며. It carries a slight sense of 'and all that'. 이며 is its written equivalent.", example: { ko: "책하며 공책하며 다 필요해요.", en: "Books, notebooks, I need all of it.", form: "책 + 하며 (listing); 필요하다 → 필요해요" } },
    "자리를 잡다|expression": { korean: "자리를 잡다", note: "'To secure a spot', and figuratively 'to settle in' somewhere new. Both senses are common.", example: { ko: "좋은 자리를 잡았어요.", en: "I got a good spot.", form: "자리 + 를 (object); 잡다 → 잡았어요 (past, polite casual)" } },
    "소파|noun": { korean: "소파", note: "A sofa, counted with 개. You sit on it with 에 앉다: 소파에 앉아요.", example: { ko: "소파에 앉으세요.", en: "Please sit on the sofa.", form: "소파 + 에 (location); 앉다 → 앉으세요 (polite request)" } },

    // ================================================================ day 22
    "헌|determiner": { korean: "헌", note: "'Worn, used, old', in front of a noun: 헌 옷, 헌 책. Its opposite is 새. Only for objects — for a person's age, use 나이 든.", example: { ko: "헌 책을 팔았어요.", en: "I sold my used books.", form: "헌 + 책 + 을 (object); 팔다 → 팔았어요 (past)" } },
    "취업 준비|noun phrase": { korean: "취업 준비", note: "Job hunting preparation — a heavy topic in Korean society and a frequent reading subject. 취업 is getting employed, 준비 preparation.", example: { ko: "요즘 취업 준비를 하고 있어요.", en: "I am preparing for job hunting these days.", form: "취업 준비 + 를 (object); 하다 → 하고 있어요 (progressive)" } },
    "열쇠|noun": { korean: "열쇠", note: "A key, from 열다 (to open) + 쇠 (metal). It also means 'the key' to a problem, as in English. A lock is 자물쇠.", example: { ko: "열쇠를 잃어버렸어요.", en: "I lost my key.", form: "열쇠 + 를 (object); 잃어버리다 → 잃어버렸어요 (past)" } },
    "켜다|verb": { korean: "켜다", note: "To turn on a light or device. Its opposite is 끄다. For water and gas, the verbs are 틀다 and 잠그다 instead.", example: { ko: "불을 켜 주세요.", en: "Please turn on the light.", form: "불 + 을 (object); 켜다 → 켜 + 주다 → 주세요 (request)" } },
    "끄다|verb": { korean: "끄다", note: "To turn off a light or device. ㅡ-irregular: 꺼요. Its opposite is 켜다.", example: { ko: "텔레비전을 껐어요.", en: "I turned off the television.", form: "텔레비전 + 을 (object); 끄다 → 껐어요 (ㅡ drops, past)" } },
    "그릇|counter": { korean: "그릇", note: "The counter for bowls of food: 밥 한 그릇, 국수 두 그릇. Takes native Korean numbers.", example: { ko: "국수 두 그릇 주세요.", en: "Two bowls of noodles, please.", form: "국수 + 두 (native number) + 그릇; 주다 → 주세요" } },
    "아차|interjection": { korean: "아차", note: "'Oops' — the sound of realising you have forgotten or made a slip, right as it happens.", example: { ko: "아차, 지갑을 두고 왔어요.", en: "Oops, I left my wallet behind.", form: "Interjection; 두다 → 두고 (connector); 오다 → 왔어요" } },
    "화를 내다|expression": { korean: "화를 내다", note: "'To get angry', actively showing it. 화가 나다 is anger arising in you, without the outburst — the difference matters.", example: { ko: "아버지가 화를 내셨어요.", en: "Father got angry.", form: "화 + 를 (object); 내다 + 시 → 내셨어요 (honorific past)" } },
    "데|dependent noun": { korean: "데", note: "'Place' or 'situation', after a modifier: 갈 데가 없어요. It is the spoken counterpart of 곳 and appears in -는데 endings.", example: { ko: "갈 데가 없어요.", en: "There is nowhere to go.", form: "가다 → 갈 (modifier) + 데 + 가 (subject); 없다 → 없어요" } },
    "다|noun": { korean: "다", note: "'All' as a noun, taking particles: 다가 아니에요 ('that is not everything'). Its adverb use before a verb is far more common.", example: { ko: "이게 다가 아니에요.", en: "This is not all of it.", form: "이거 + 가 → 이게; 다 + 가 (subject); 아니다 → 아니에요" } },
    "배가 고파요|phrase": { korean: "배가 고파요", note: "'I am hungry.' Korean says the stomach is hungry, so 배 takes 가. Saying 저는 고파요 is wrong.", example: { ko: "배가 고파요. 밥 먹어요.", en: "I am hungry. Let us eat.", form: "배 + 가 (subject); 고프다 → 고파요 (ㅡ drops before -아요)" } },
    "배가 불러요|phrase": { korean: "배가 불러요", note: "'I am full.' The counterpart to 배가 고파요, built the same way. 부르다 is ㄹ-irregular here: 불러요.", example: { ko: "배가 불러요. 더 못 먹겠어요.", en: "I am full. I cannot eat any more.", form: "배 + 가 (subject); 부르다 → 불러요 (르-irregular)" } },
    "깎다|verb": { korean: "깎다", note: "To cut, peel or trim — hair, fruit skin, and prices. 값을 깎다 is to haggle, which is expected at markets but not in shops.", example: { ko: "사과를 깎아 주세요.", en: "Please peel the apple.", form: "사과 + 를 (object); 깎다 → 깎아 + 주다 → 주세요 (request)" } },
    "마는|particle": { korean: "마는", note: "'But', tacked onto a finished clause in writing: 좋다마는. Contracted to 만 in speech. Formal and somewhat literary.", example: { ko: "가고 싶다마는 시간이 없어요.", en: "I would like to go, but there is no time.", form: "싶다 + 마는 (concessive); 없다 → 없어요" } },
    "내|pronoun": { korean: "내", note: "'My', casual — the possessive of 나. Its polite counterpart is 제, from 저. Use 내 only with people you would address as 너.", example: { ko: "내 친구야.", en: "He is my friend.", form: "내 + 친구; 이다 → 야 (casual, after a vowel)" } },
    "과자|noun": { korean: "과자", note: "A snack, biscuit or cookie — anything in that category. Counted with 개 or by the packet, 봉지.", example: { ko: "과자를 한 봉지 샀어요.", en: "I bought a packet of snacks.", form: "과자 + 를 (object); 한 봉지 (native number + counter); 사다 → 샀어요" } },
    "살을 빼다|expression": { korean: "살을 빼다", note: "'To lose weight.' 살 here is flesh, and 빼다 is to remove. Gaining weight is 살이 찌다, where the weight is the subject.", example: { ko: "살을 빼려고 운동해요.", en: "I exercise in order to lose weight.", form: "살 + 을 (object); 빼다 → 빼려고 (purpose); 운동하다 → 운동해요" } },
    "대학교|noun": { korean: "대학교", note: "A university as an institution — what people say in conversation. 대학 is a college within one, or the concept in compounds.", example: { ko: "대학교에 다녀요.", en: "I attend university.", form: "대학교 + 에 (destination); 다니다 → 다녀요 (present)" } },
    "예를 들어|conjunction": { korean: "예를 들어", note: "'For example', introducing an illustration. 예를 들면 is an equally common variant. Very frequent in TOPIK writing.", example: { ko: "예를 들어 김치가 있어요.", en: "For example, there is kimchi.", form: "예 + 를 (object); 들다 → 들어 (connector); 있다 → 있어요" } },
    "걱정하다|verb": { korean: "걱정하다", note: "To worry. What worries you takes 을/를: 시험을 걱정해요. 걱정하지 마세요 is the standard reassurance.", example: { ko: "너무 걱정하지 마세요.", en: "Please do not worry too much.", form: "걱정하다 → 걱정하지 마세요 (polite prohibition)" } },
    "돼지고기|noun": { korean: "돼지고기", note: "Pork. The set runs 소고기 / 돼지고기 / 닭고기, all built with 고기 (meat). 삼겹살 is the pork belly cut Koreans grill.", example: { ko: "돼지고기를 좋아해요.", en: "I like pork.", form: "돼지고기 + 를 (object); 좋아하다 → 좋아해요" } },
    "수건|noun": { korean: "수건", note: "A towel. 손수건 is a handkerchief, built from 손 + 수건. Counted with 장 or 개.", example: { ko: "수건 좀 주세요.", en: "Please give me a towel.", form: "수건 + 좀 (softener, object particle dropped); 주다 → 주세요" } },
    "양복|noun": { korean: "양복", note: "A western-style suit, worn with 입다. 정장 is the more current word; 한복 is the traditional counterpart.", example: { ko: "양복을 입고 갔어요.", en: "I went wearing a suit.", form: "양복 + 을 (object); 입다 → 입고 (connector); 가다 → 갔어요" } },
    "잠이 들다|expression": { korean: "잠이 들다", note: "'To fall asleep.' The sleep enters you, so 잠 takes 이. 자다 is the ongoing act of sleeping; this is the moment of dropping off.", example: { ko: "금방 잠이 들었어요.", en: "I fell asleep quickly.", form: "잠 + 이 (subject); 들다 → 들었어요 (past, polite casual)" } },
    "젓가락|noun": { korean: "젓가락", note: "Chopsticks — grammatically a single item in Korean, counted with 벌 as a set with a spoon. Korean ones are metal and flat.", example: { ko: "젓가락으로 먹어요.", en: "I eat with chopsticks.", form: "젓가락 + 으로 (instrument, after a batchim); 먹다 → 먹어요" } },
    "리|dependent noun": { korean: "리", note: "'Reason, likelihood', only in -을 리가 없다: 그럴 리가 없어요. It never appears alone.", example: { ko: "그럴 리가 없어요.", en: "There is no way that is so.", form: "그렇다 → 그럴 (modifier) + 리 + 가; 없다 → 없어요" } },
    "조용하다|adjective": { korean: "조용하다", note: "To be quiet. 조용히 하세요 is 'please be quiet' — the adverb form, since you are telling someone how to act.", example: { ko: "도서관은 조용해요.", en: "The library is quiet.", form: "도서관 + 은 (topic); 조용하다 → 조용해요 (present, polite casual)" } },
    "첫|determiner": { korean: "첫", note: "'First', in front of a noun: 첫 사랑, 첫 번째. It is irregular — built on 첫, not 하나 or 한.", example: { ko: "첫 번째 문제가 어려워요.", en: "The first question is difficult.", form: "첫 + 번째 + 문제 + 가 (subject); 어렵다 → 어려워요 (ㅂ-irregular)" } },
    "더러|particle": { korean: "더러", note: "'To a person', colloquial and somewhat dated: 나더러 가라고 했어요. 에게 and 한테 have largely replaced it.", example: { ko: "저더러 가라고 했어요.", en: "They told me to go.", form: "저 + 더러 (recipient, colloquial); 가다 → 가라고 (reported command)" } },
    "잃어버리다|verb": { korean: "잃어버리다", note: "To lose something for good. The -어 버리다 ending adds finality and regret that plain 잃다 lacks, which is why speech prefers it.", example: { ko: "휴대폰을 잃어버렸어요.", en: "I lost my mobile phone.", form: "잃다 → 잃어 (connector) + 버리다 → 버렸어요 (completion, past)" } },
    "문제를 일으키다|expression": { korean: "문제를 일으키다", note: "'To cause a problem.' 일으키다 is 'to raise or set off'. Its intransitive partner is 문제가 생기다, where the problem simply arises.", example: { ko: "그 일이 문제를 일으켰어요.", en: "That matter caused a problem.", form: "문제 + 를 (object); 일으키다 → 일으켰어요 (past)" } },
    "병|counter": { korean: "병", note: "The counter for bottles: 맥주 한 병, 물 두 병. Takes native Korean numbers. It is also the noun 'bottle' and, separately, 'illness'.", example: { ko: "맥주 두 병 주세요.", en: "Two bottles of beer, please.", form: "맥주 + 두 (native number) + 병; 주다 → 주세요" } },
    "흠|interjection": { korean: "흠", note: "'Hmm' — sceptical or considering, with more doubt in it than 음. Often precedes a polite disagreement.", example: { ko: "흠, 글쎄요.", en: "Hmm, I am not sure.", form: "Interjection; 글쎄 + 요 (politeness particle)" } },
    "주소|noun": { korean: "주소", note: "An address. Korean addresses run largest to smallest — province, city, district, street, building — the reverse of English order.", example: { ko: "주소를 알려 주세요.", en: "Please tell me the address.", form: "주소 + 를 (object); 알리다 → 알려 + 주다 → 주세요 (request)" } },
    // ================================================================ day 23
    "언제|adverb": { korean: "언제", note: "'Whenever', in statements rather than questions: 언제 봐도 좋아요. The question-word use is a separate entry.", example: { ko: "언제 봐도 예뻐요.", en: "She looks lovely whenever I see her.", form: "언제 + 보다 → 봐도 (concessive); 예쁘다 → 예뻐요 (ㅡ drops)" } },
    "태국|proper noun": { korean: "태국", note: "Thailand. The language is 태국어 and a Thai person 태국 사람. A very common travel destination in Korean dialogues.", example: { ko: "태국에 여행 갔어요.", en: "I travelled to Thailand.", form: "태국 + 에 (destination); 여행 가다 → 갔어요 (past)" } },
    "필리핀|proper noun": { korean: "필리핀", note: "The Philippines. Country names take 사람 for nationality: 필리핀 사람.", example: { ko: "필리핀에서 왔어요.", en: "I am from the Philippines.", form: "필리핀 + 에서 (source); 오다 → 왔어요 (past, polite casual)" } },
    "자기 계발|noun phrase": { korean: "자기 계발", note: "Self-development — a standing theme in Korean workplace and study culture, and common in reading passages. 계발 is developing potential.", example: { ko: "자기 계발에 시간을 써요.", en: "I spend time on self-development.", form: "자기 계발 + 에; 시간 + 을 (object); 쓰다 → 써요 (ㅡ drops)" } },
    "저희|pronoun": { korean: "저희", note: "'We, our' — humble, the polite form of 우리. Note Koreans say 우리나라, never 저희 나라, because humbling the country itself is felt to be wrong.", example: { ko: "저희 회사는 서울에 있어요.", en: "Our company is in Seoul.", form: "저희 + 회사 + 는 (topic); 있다 → 있어요" } },
    "메뉴|noun": { korean: "메뉴", note: "A menu, and also a dish on it. 메뉴판 is the physical menu card. Asking 메뉴 좀 주세요 gets you one.", example: { ko: "메뉴 좀 주세요.", en: "May I have the menu please.", form: "메뉴 + 좀 (softener); 주다 → 주세요 (polite request)" } },
    "발이 넓다|expression": { korean: "발이 넓다", note: "'To know a lot of people' — literally 'the feet are wide'. A compliment about someone's social reach, not about their shoe size.", example: { ko: "그 사람은 발이 넓어요.", en: "That person knows everyone.", form: "발 + 이 (subject); 넓다 → 넓어요 (present, polite casual)" } },
    "손이 크다|expression": { korean: "손이 크다", note: "'To be generous' — literally 'the hand is big'. Said of someone who cooks too much food or gives freely.", example: { ko: "어머니는 손이 크세요.", en: "My mother is very generous with food.", form: "손 + 이 (subject); 크다 + 시 → 크세요 (honorific present)" } },
    "귀가 얇다|expression": { korean: "귀가 얇다", note: "'To be easily persuaded' — literally 'thin ears'. Mildly critical: the person believes whatever they are told.", example: { ko: "저는 귀가 얇아요.", en: "I am easily swayed.", form: "귀 + 가 (subject); 얇다 → 얇아요 (present, polite casual)" } },
    "입이 무겁다|expression": { korean: "입이 무겁다", note: "'To keep a secret well' — literally 'a heavy mouth'. Its opposite, 입이 가볍다, means someone who talks too freely.", example: { ko: "그 친구는 입이 무거워요.", en: "That friend keeps secrets well.", form: "입 + 이 (subject); 무겁다 → 무거워요 (ㅂ-irregular)" } },
    "중|dependent noun": { korean: "중", note: "'In the middle of' after a noun (수업 중), and 'among' when picking from a group (이 중에서). It never stands alone.", example: { ko: "지금 회의 중이에요.", en: "I am in a meeting right now.", form: "회의 + 중 + 이에요 (이다 after a batchim)" } },
    "약속하다|verb": { korean: "약속하다", note: "To promise, and to make an appointment — Korean uses one word for both. The person takes 와/과 or 하고.", example: { ko: "친구와 약속했어요.", en: "I made plans with a friend.", form: "친구 + 와 (with); 약속하다 → 약속했어요 (past)" } },
    "깨나|particle": { korean: "깨나", note: "'Quite a bit of', attached to a noun with a slightly sarcastic edge: 돈깨나 있나 봐요. Informal and a little pointed.", example: { ko: "돈깨나 있나 봐요.", en: "They seem to have quite a bit of money.", form: "돈 + 깨나; 있다 → 있나 봐요 (supposition)" } },
    "자장면|noun": { korean: "자장면", note: "Jajangmyeon, noodles in black bean sauce — the default Korean takeaway. 짜장면 is the equally accepted spelling.", example: { ko: "자장면을 시켰어요.", en: "I ordered jajangmyeon.", form: "자장면 + 을 (object); 시키다 → 시켰어요 (past, polite casual)" } },
    "중학생|noun": { korean: "중학생", note: "A middle school student, years 7 to 9. The set runs 초등학생 / 중학생 / 고등학생 / 대학생.", example: { ko: "제 동생은 중학생이에요.", en: "My younger sibling is a middle school student.", form: "동생 + 은 (topic); 중학생 + 이에요 (이다 after a batchim)" } },
    "무엇보다|conjunction": { korean: "무엇보다", note: "'Above all', ranking one point over the rest. 무엇보다도 adds emphasis. Common in written argument.", example: { ko: "무엇보다 건강이 중요해요.", en: "Above all, health is important.", form: "무엇보다 opens the clause; 건강 + 이 (subject); 중요하다 → 중요해요" } },
    "휴일|noun": { korean: "휴일", note: "A day off or a holiday. 공휴일 is a public holiday specifically, and 방학 is a school vacation.", example: { ko: "휴일에 푹 쉬었어요.", en: "I rested well on my day off.", form: "휴일 + 에 (time); 쉬다 → 쉬었어요 (past, polite casual)" } },
    "목이 말라요|phrase": { korean: "목이 말라요", note: "'I am thirsty.' Korean says the throat is dry, so 목 takes 이. 마르다 is 르-irregular: 말라요.", example: { ko: "목이 말라요. 물 좀 주세요.", en: "I am thirsty. Some water, please.", form: "목 + 이 (subject); 마르다 → 말라요 (르-irregular)" } },
    "피곤해요|phrase": { korean: "피곤해요", note: "'I am tired.' 피곤하다 describes your state directly, unlike 배고프다 which needs a body-part subject.", example: { ko: "오늘 정말 피곤해요.", en: "I am really tired today.", form: "피곤하다 → 피곤해요 (present, polite casual)" } },
    "신다|verb": { korean: "신다", note: "To put on footwear and socks — the dedicated verb. 입다 is for clothing on the body and 쓰다 for hats. Its opposite is 벗다.", example: { ko: "양말을 신었어요.", en: "I put on my socks.", form: "양말 + 을 (object); 신다 → 신었어요 (past, polite casual)" } },
    "달력|noun": { korean: "달력", note: "A calendar. Built from 달 (month) + 력 (record). 날짜 is a date and 요일 a day of the week.", example: { ko: "달력에 표시했어요.", en: "I marked it on the calendar.", form: "달력 + 에 (location); 표시하다 → 표시했어요 (past)" } },
    "소풍|noun": { korean: "소풍", note: "A picnic or a school outing. 소풍을 가다 is to go on one. It is a fixture of Korean school life in spring and autumn.", example: { ko: "내일 소풍을 가요.", en: "We go on a picnic tomorrow.", form: "소풍 + 을 (object); 가다 → 가요 (present used for a fixed future)" } },
    "오래|adverb": { korean: "오래", note: "'For a long time', before the verb: 오래 기다렸어요. 오랫동안 is the fuller noun phrase and slightly more formal.", example: { ko: "오래 기다렸어요.", en: "I waited a long time.", form: "오래 before the verb; 기다리다 → 기다렸어요 (past)" } },
    "매|determiner": { korean: "매", note: "'Every', in front of a noun: 매일, 매주, 매년. It fuses into those compounds and rarely stands before an ordinary noun.", example: { ko: "매주 토요일에 만나요.", en: "We meet every Saturday.", form: "매 + 주 + 토요일 + 에 (time); 만나다 → 만나요" } },
    "크다|verb": { korean: "크다", note: "To grow — the verb sense, of children and plants: 아이가 컸어요. The adjective 크다 ('to be big') is a separate entry. ㅡ-irregular either way.", example: { ko: "아이가 많이 컸어요.", en: "The child has grown a lot.", form: "아이 + 가 (subject); 크다 → 컸어요 (ㅡ drops, past)" } },
    "당신|pronoun": { korean: "당신", note: "'You' — but handle with care. Between spouses it is affectionate; toward a stranger it is confrontational, close to 'you there'. Songs and ads use it freely, conversation does not.", example: { ko: "당신을 사랑해요.", en: "I love you.", form: "당신 + 을 (object); 사랑하다 → 사랑해요 (to a spouse)" } },
    "양말|noun": { korean: "양말", note: "Socks, counted with 켤레 for pairs. Put on with 신다, like shoes.", example: { ko: "양말 한 켤레를 샀어요.", en: "I bought a pair of socks.", form: "양말 + 한 켤레 + 를 (object); 사다 → 샀어요 (past)" } },
    "이라든지|particle": { korean: "이라든지", note: "'Or such', listing examples loosely: 커피라든지 차라든지. 라든지 after a vowel. Informal.", example: { ko: "커피라든지 차라든지 아무거나 좋아요.", en: "Coffee or tea, anything is fine.", form: "커피 + 라든지 (after a vowel); 좋다 → 좋아요" } },
    "겸|dependent noun": { korean: "겸", note: "'Serving as both', joining two roles: 아침 겸 점심. After a verb it becomes -을 겸.", example: { ko: "아침 겸 점심을 먹었어요.", en: "I ate a meal that was both breakfast and lunch.", form: "아침 + 겸 + 점심 + 을 (object); 먹다 → 먹었어요" } },
    "줄기|counter": { korean: "줄기", note: "The counter for stems and streams: 꽃 한 줄기, 빛 한 줄기. Takes native Korean numbers.", example: { ko: "빛 한 줄기가 들어왔어요.", en: "A ray of light came in.", form: "빛 + 한 (native number) + 줄기 + 가 (subject); 들어오다 → 들어왔어요" } },
    "헉|interjection": { korean: "헉", note: "A sharp gasp — shock or alarm. Very common in text messages and comics.", example: { ko: "헉, 벌써 여덟 시예요?", en: "Whoa, is it eight o'clock already?", form: "Interjection; 이다 → 예요 (question)" } },
    "경치|noun": { korean: "경치", note: "Scenery or a view. 경치가 좋다 is 'the view is lovely'. 풍경 is the more literary equivalent.", example: { ko: "여기 경치가 좋아요.", en: "The scenery here is lovely.", form: "경치 + 가 (subject); 좋다 → 좋아요 (present, polite casual)" } },
    "지우다|verb": { korean: "지우다", note: "To erase or delete. 지우개 is an eraser, built from it. For deleting files, 삭제하다 is the technical word.", example: { ko: "칠판을 지웠어요.", en: "I wiped the blackboard.", form: "칠판 + 을 (object); 지우다 → 지웠어요 (past, polite casual)" } },
    "발음|noun": { korean: "발음", note: "Pronunciation. 발음하다 is to pronounce, and 발음이 좋다 is a compliment learners hear often.", example: { ko: "발음이 어려워요.", en: "The pronunciation is difficult.", form: "발음 + 이 (subject); 어렵다 → 어려워요 (ㅂ-irregular)" } },
    "여가 활동|noun phrase": { korean: "여가 활동", note: "Leisure activity — a set phrase in surveys and reading passages about lifestyle. 여가 is free time.", example: { ko: "여가 활동으로 등산을 해요.", en: "I hike as a leisure activity.", form: "여가 활동 + 으로 (as); 등산 + 을 (object); 하다 → 해요" } },

    // ================================================================ day 24
    "잊어버리다|verb": { korean: "잊어버리다", note: "To forget completely. The -어 버리다 ending adds finality that plain 잊다 lacks, which is why speech prefers it.", example: { ko: "이름을 잊어버렸어요.", en: "I completely forgot the name.", form: "잊다 → 잊어 (connector) + 버리다 → 버렸어요 (completion, past)" } },
    "남학생|noun": { korean: "남학생", note: "A male student, the pair of 여학생. Built from 남 (male) + 학생.", example: { ko: "남학생이 더 많아요.", en: "There are more male students.", form: "남학생 + 이 (subject); 더 + 많다 → 많아요 (comparative)" } },
    "십만|numeral": { korean: "십만", note: "A hundred thousand — literally 'ten ten-thousands'. Korean groups digits in fours, so this is where English and Korean number-reading diverge hardest.", example: { ko: "십만 원이에요.", en: "It is a hundred thousand won.", form: "십만 + 원 (counter); 이다 → 이에요 (after a batchim)" } },
    "백만|numeral": { korean: "백만", note: "A million — 'a hundred ten-thousands'. Again the four-digit grouping: 백만, not 천천.", example: { ko: "백만 명이 참가했어요.", en: "A million people took part.", form: "백만 + 명 (counter) + 이 (subject); 참가하다 → 참가했어요" } },
    "대사관|noun": { korean: "대사관", note: "An embassy. 영사관 is a consulate. A practical word for travel and visa dialogues.", example: { ko: "대사관에 가야 해요.", en: "I have to go to the embassy.", form: "대사관 + 에 (destination); 가다 → 가야 해요 (obligation)" } },
    "안되다|verb": { korean: "안되다", note: "Written solid it means 'to not work out' or 'must not': 그러면 안 돼요. Written apart as 안 되다 it is simply the negation of 되다. The spacing carries the meaning.", example: { ko: "여기서 사진을 찍으면 안 돼요.", en: "You must not take photos here.", form: "찍다 → 찍으면 (conditional) + 안 되다 → 안 돼요 (prohibition)" } },
    "이라든가|particle": { korean: "이라든가", note: "'Or something like', listing loose examples: 책이라든가 잡지라든가. 라든가 after a vowel.", example: { ko: "책이라든가 잡지라든가 읽어요.", en: "I read books or magazines or something.", form: "책 + 이라든가 (after a batchim); 읽다 → 읽어요" } },
    "웬|determiner": { korean: "웬", note: "'What sort of', with a note of surprise at something unexpected: 웬 일이에요? Distinct from 왠 in 왠지 ('somehow'), which is spelled differently.", example: { ko: "웬 일이에요?", en: "What brings you here?", form: "웬 + 일 + 이에요 (이다 after a batchim; question)" } },
    "눈이 높다|expression": { korean: "눈이 높다", note: "'To have high standards' — literally 'high eyes'. Usually about taste in partners or possessions, and mildly teasing.", example: { ko: "그 사람은 눈이 높아요.", en: "That person has high standards.", form: "눈 + 이 (subject); 높다 → 높아요 (present, polite casual)" } },
    "첫째로|conjunction": { korean: "첫째로", note: "'Firstly', opening a numbered list of points. It runs 첫째로, 둘째로, 셋째로 and is the register of essays and presentations.", example: { ko: "첫째로 시간이 부족해요.", en: "Firstly, there is not enough time.", form: "첫째 + 로 (adverbial); 부족하다 → 부족해요" } },
    "감사하다|adjective": { korean: "감사하다", note: "To be thankful, as a state: 정말 감사해요. It also works as a verb ('to thank'), which is a separate entry here.", example: { ko: "도와주셔서 감사해요.", en: "I am thankful that you helped.", form: "돕다 → 도와주셔서 (honorific cause); 감사하다 → 감사해요" } },
    "감사하다|verb": { korean: "감사하다", note: "To thank. 감사합니다 is its formal-polite form and the most common way to say thank you in Korea.", example: { ko: "진심으로 감사합니다.", en: "I thank you sincerely.", form: "감사하다 → 감사합니다 (present, formal polite)" } },
    "등|dependent noun": { korean: "등", note: "'Et cetera, and so on', closing a list: 사과, 배, 포도 등. Written register; in speech Koreans trail off with 같은 거 instead.", example: { ko: "사과, 배 등을 샀어요.", en: "I bought apples, pears and so on.", form: "등 + 을 (object particle); 사다 → 샀어요 (past)" } },
    "드리다|auxiliary verb": { korean: "드리다", note: "-어 드리다 is the humble form of -어 주다: doing something for someone you respect. 도와 드릴게요, not 도와 줄게요, when speaking to an elder.", example: { ko: "제가 도와 드릴게요.", en: "I will help you.", form: "돕다 → 도와 (ㅂ-irregular) + 드리다 → 드릴게요 (humble intention)" } },
    "오래간만|noun": { korean: "오래간만", note: "'After a long time', the fuller form of 오랜만. 오래간만이에요 is interchangeable with 오랜만이에요.", example: { ko: "오래간만이에요!", en: "It has been a long time!", form: "오래간만 + 이에요 (이다 after a batchim)" } },
    "점심시간|noun": { korean: "점심시간", note: "Lunchtime. Built from 점심 + 시간, written solid. 점심 alone is both midday and the meal.", example: { ko: "점심시간이 한 시예요.", en: "Lunchtime is at one o'clock.", form: "점심시간 + 이 (subject); 한 시 + 예요 (native number + 시)" } },
    "그녀|pronoun": { korean: "그녀", note: "'She' — a written pronoun coined for translation. It appears in novels and news, almost never in speech, where Koreans use the name or 그 사람.", example: { ko: "그녀는 의사예요.", en: "She is a doctor.", form: "그녀 + 는 (topic); 의사 + 예요 (이다 after a vowel)" } },
    "휴지|noun": { korean: "휴지", note: "Tissue or toilet paper. 화장지 is the more polite word for the bathroom kind; 휴지통 is a wastebasket.", example: { ko: "휴지 좀 주세요.", en: "Please pass me a tissue.", form: "휴지 + 좀 (softener); 주다 → 주세요 (polite request)" } },
    "머리가 아프다|expression": { korean: "머리가 아프다", note: "'To have a headache', and figuratively 'to be a headache' — a problem that will not resolve. Both senses are common.", example: { ko: "그 문제 때문에 머리가 아파요.", en: "That problem is giving me a headache.", form: "문제 + 때문에 (cause); 머리 + 가 (subject); 아프다 → 아파요" } },
    "배가 아프다|expression": { korean: "배가 아프다", note: "'To have a stomachache', and idiomatically 'to be envious' of someone's good fortune. Context decides which.", example: { ko: "친구가 잘돼서 배가 아파요.", en: "I am envious that my friend is doing well.", form: "잘되다 → 잘돼서 (cause); 배 + 가 (subject); 아프다 → 아파요" } },
    "매일|adverb": { korean: "매일", note: "'Every day', before the verb with no particle: 매일 운동해요. The noun form takes particles and is a separate entry.", example: { ko: "매일 한국어를 공부해요.", en: "I study Korean every day.", form: "매일 before the verb; 공부하다 → 공부해요" } },
    "매일|noun": { korean: "매일", note: "'Every day' as a noun, so it can take particles: 매일이 바빠요. Less common than the adverb use.", example: { ko: "매일이 바빠요.", en: "Every day is busy.", form: "매일 + 이 (subject); 바쁘다 → 바빠요 (ㅡ drops)" } },
    "재미있었어요|phrase": { korean: "재미있었어요", note: "'It was fun' — the standard verdict on a film, trip or evening. Its opposite is 재미없었어요.", example: { ko: "영화가 정말 재미있었어요.", en: "The film was really fun.", form: "재미있다 → 재미있었어요 (past, polite casual)" } },
    "늦다|verb": { korean: "늦다", note: "To be late or run late, as an action: 학교에 늦었어요. The adjective sense ('to be late' as a state of time) is a separate entry.", example: { ko: "버스를 놓쳐서 늦었어요.", en: "I missed the bus and was late.", form: "놓치다 → 놓쳐서 (cause); 늦다 → 늦었어요 (past)" } },
    "다발|counter": { korean: "다발", note: "The counter for bundles and bouquets: 꽃 한 다발. Takes native Korean numbers.", example: { ko: "꽃 한 다발을 샀어요.", en: "I bought a bouquet of flowers.", form: "꽃 + 한 (native number) + 다발 + 을 (object); 사다 → 샀어요" } },
    "쯧쯧|interjection": { korean: "쯧쯧", note: "'Tsk tsk' — a clicking sound of disapproval or pity. Older speakers use it; it is openly judgemental.", example: { ko: "쯧쯧, 안됐네요.", en: "Tsk tsk, what a shame.", form: "Interjection; 안되다 → 안됐네요 (remarking, polite casual)" } },
    "감사|noun": { korean: "감사", note: "Thanks or gratitude as a noun: 감사의 마음. It underlies 감사하다 and 감사합니다.", example: { ko: "감사의 마음을 전했어요.", en: "I conveyed my gratitude.", form: "감사 + 의 (possessive); 마음 + 을 (object); 전하다 → 전했어요" } },
    "친절하다|adjective": { korean: "친절하다", note: "To be kind, especially in service or manner. 착하다 describes a good-hearted nature instead; the two are not interchangeable.", example: { ko: "직원이 아주 친절해요.", en: "The staff are very kind.", form: "직원 + 이 (subject); 친절하다 → 친절해요 (present, polite casual)" } },
    "슈퍼마켓|noun": { korean: "슈퍼마켓", note: "A supermarket, usually shortened to 슈퍼 or 마트 in speech. 시장 is a traditional market.", example: { ko: "슈퍼마켓에서 우유를 샀어요.", en: "I bought milk at the supermarket.", form: "슈퍼마켓 + 에서 (action-location); 사다 → 샀어요 (past)" } },
    "서|particle": { korean: "서", note: "The contracted form of 에서, common in speech: 여기서, 어디서. Same job — where an action happens, or where movement starts.", example: { ko: "어디서 만날까요?", en: "Where shall we meet?", form: "어디 + 서 (contracted 에서); 만나다 → 만날까요 (suggestion, question)" } },
    "비누|noun": { korean: "비누", note: "Soap. Washing with it takes 로: 비누로 씻어요. 세제 is detergent.", example: { ko: "비누로 손을 씻으세요.", en: "Please wash your hands with soap.", form: "비누 + 로 (instrument); 손 + 을 (object); 씻다 → 씻으세요" } },
    "걸어오다|verb": { korean: "걸어오다", note: "To walk here, toward the speaker. Its mirror 걸어가다 walks away. Built from 걷다 + 오다.", example: { ko: "집에서 걸어왔어요.", en: "I walked here from home.", form: "집 + 에서 (source); 걸어오다 → 걸어왔어요 (past)" } },
    "세수|noun": { korean: "세수", note: "Washing one's face specifically. 세수하다 is the verb. For the whole body it is 샤워하다 or 목욕하다.", example: { ko: "아침에 세수를 해요.", en: "I wash my face in the morning.", form: "세수 + 를 (object); 하다 → 해요 (present, polite casual)" } },
    "따위|dependent noun": { korean: "따위", note: "'And such, that sort of thing' — but dismissive, close to 'the likes of'. Not a neutral 등; it belittles what it lists.", example: { ko: "그런 것 따위는 필요 없어요.", en: "I have no need for the likes of that.", form: "것 + 따위 + 는 (topic); 필요 없다 → 없어요" } },
    "찌개|noun": { korean: "찌개", note: "A thick Korean stew, served bubbling and shared from the pot: 김치찌개, 된장찌개. 국 is a thinner soup served in individual bowls.", example: { ko: "김치찌개를 끓였어요.", en: "I made kimchi stew.", form: "김치찌개 + 를 (object); 끓이다 → 끓였어요 (past)" } },
    "넥타이|noun": { korean: "넥타이", note: "A necktie. Worn with 매다 ('to tie'), not 입다: 넥타이를 매요.", example: { ko: "넥타이를 맸어요.", en: "I put on a tie.", form: "넥타이 + 를 (object); 매다 → 맸어요 (past, polite casual)" } },
    "한글|proper noun": { korean: "한글", note: "Hangeul as a name — the alphabet created under King Sejong in 1443. 한글날 on 9 October is a public holiday marking it.", example: { ko: "한글은 세종대왕이 만들었어요.", en: "Hangeul was created by King Sejong.", form: "한글 + 은 (topic); 세종대왕 + 이 (subject); 만들다 → 만들었어요" } },
    "건강 검진|noun phrase": { korean: "건강 검진", note: "A health checkup. Annual checkups are standard in Korean workplaces, so this appears in practical reading passages.", example: { ko: "매년 건강 검진을 받아요.", en: "I get a health checkup every year.", form: "건강 검진 + 을 (object); 받다 → 받아요 (present, polite casual)" } },
    "인사하다|verb": { korean: "인사하다", note: "To greet, including the bow. The person greeted takes 에게/한테 or, respectfully, 께.", example: { ko: "선생님께 인사했어요.", en: "I greeted the teacher.", form: "선생님 + 께 (honorific recipient); 인사하다 → 인사했어요" } },
    "별|determiner": { korean: "별", note: "'Particular, unusual', in front of a noun and normally with a negative: 별 문제 없어요. It underlies 별로 ('not particularly').", example: { ko: "별 문제 없어요.", en: "There is no particular problem.", form: "별 + 문제; 없다 → 없어요 (negative existence)" } },
    "얼굴이 두껍다|expression": { korean: "얼굴이 두껍다", note: "'To be shameless' — literally 'a thick face', the same image as English 'thick-skinned' but sharper. 뻔뻔하다 is the plain adjective.", example: { ko: "정말 얼굴이 두꺼워요.", en: "He is really shameless.", form: "얼굴 + 이 (subject); 두껍다 → 두꺼워요 (ㅂ-irregular)" } },
    "한국말|noun": { korean: "한국말", note: "Korean as a spoken language — the colloquial counterpart of 한국어. 한글 is only the alphabet, never the language.", example: { ko: "한국말을 조금 해요.", en: "I speak a little Korean.", form: "한국말 + 을 (object); 하다 → 해요 (present, polite casual)" } },
    "못하다|adjective": { korean: "못하다", note: "To be worse or not as good, as a state: 이것보다 못해요. Its comparison partner takes 보다.", example: { ko: "이 식당은 저기보다 못해요.", en: "This restaurant is worse than that one.", form: "저기 + 보다 (comparison); 못하다 → 못해요" } },
    "계란|noun": { korean: "계란", note: "An egg. 달걀 is the native Korean equivalent and equally common. Counted with 개 or by the carton, 판.", example: { ko: "계란 두 개를 삶았어요.", en: "I boiled two eggs.", form: "계란 + 두 개 + 를 (object); 삶다 → 삶았어요 (past)" } },
    "정말이에요|phrase": { korean: "정말이에요", note: "'It is true, really.' With rising intonation, 정말이에요? asks 'is that so?'. 진짜예요 is its casual twin.", example: { ko: "정말이에요? 믿을 수 없어요.", en: "Really? I cannot believe it.", form: "정말 + 이에요 (이다 after a batchim; question by intonation)" } },

    // ================================================================ day 25
    "그들|pronoun": { korean: "그들", note: "'They' — written Korean, formed with the plural 들. In speech Koreans say 그 사람들 or 그분들 instead.", example: { ko: "그들은 친구예요.", en: "They are friends.", form: "그들 + 은 (topic); 친구 + 예요 (이다 after a vowel)" } },
    "에어컨|noun": { korean: "에어컨", note: "An air conditioner, shortened from the English. Turned on with 켜다 and off with 끄다.", example: { ko: "에어컨을 켰어요.", en: "I turned on the air conditioner.", form: "에어컨 + 을 (object); 켜다 → 켰어요 (past, polite casual)" } },
    "마지막으로|conjunction": { korean: "마지막으로", note: "'Lastly', closing a list of points. It pairs with 첫째로 and 둘째로 in presentations and essays.", example: { ko: "마지막으로 한 가지 더 있어요.", en: "Lastly, there is one more thing.", form: "마지막 + 으로 (adverbial); 있다 → 있어요" } },
    "끝으로|conjunction": { korean: "끝으로", note: "'In closing' — the final remark of a speech or letter. More formal than 마지막으로.", example: { ko: "끝으로 감사드립니다.", en: "In closing, thank you.", form: "끝 + 으로 (adverbial); 감사드리다 → 감사드립니다 (humble, formal)" } },
    "에게로|particle": { korean: "에게로", note: "'Toward a person', adding direction to 에게. Literary; plain 에게 covers most cases.", example: { ko: "그는 나에게로 다가왔어요.", en: "He came toward me.", form: "나 + 에게로 (direction toward a person); 다가오다 → 다가왔어요" } },
    "억|numeral": { korean: "억", note: "A hundred million — the next four-digit unit after 만. Korean money talk uses it constantly: 일억 원.", example: { ko: "집값이 삼억 원이에요.", en: "The house costs three hundred million won.", form: "삼억 + 원 (counter); 이다 → 이에요 (after a batchim)" } },
    "조|numeral": { korean: "조", note: "A trillion — the unit above 억. Appears in national budget and economic reading.", example: { ko: "예산이 일 조 원이에요.", en: "The budget is one trillion won.", form: "일 조 + 원 (counter); 이다 → 이에요" } },
    "목이 빠지다|expression": { korean: "목이 빠지다", note: "'To wait impatiently' — literally 'the neck falls off', from craning to look for someone. Always about waiting.", example: { ko: "목이 빠지게 기다렸어요.", en: "I waited and waited.", form: "목 + 이 (subject); 빠지다 → 빠지게 (adverbial); 기다리다 → 기다렸어요" } },
    "실례|noun": { korean: "실례", note: "A discourtesy. You will meet it in 실례합니다 ('excuse me') and 실례지만 ('excuse me, but'), which opens a polite question to a stranger.", example: { ko: "실례지만 길 좀 여쭤볼게요.", en: "Excuse me, but may I ask for directions.", form: "실례 + 지만 (but); 여쭤보다 → 여쭤볼게요 (humble intention)" } },
    "잠자다|verb": { korean: "잠자다", note: "To sleep, written solid — a slightly more deliberate form of 자다. 잠을 자다 with the object particle is equally common.", example: { ko: "아기가 잠자고 있어요.", en: "The baby is sleeping.", form: "아기 + 가 (subject); 잠자다 → 잠자고 있어요 (progressive)" } },
    "나름|dependent noun": { korean: "나름", note: "'Depending on' or 'in one's own way': 사람 나름이에요. It resists a single rule and points at variation.", example: { ko: "그건 사람 나름이에요.", en: "That depends on the person.", form: "사람 + 나름 + 이에요 (이다 after a batchim)" } },
    "달다|adjective": { korean: "달다", note: "To be sweet. ㄹ-irregular: 답니다, 다세요. The taste set runs 달다 / 짜다 / 맵다 / 시다 / 쓰다.", example: { ko: "이 과자가 너무 달아요.", en: "This snack is too sweet.", form: "과자 + 가 (subject); 달다 → 달아요 (present, polite casual)" } },
    "짜다|adjective": { korean: "짜다", note: "To be salty. It also describes someone stingy with money, the same way English says 'tight'.", example: { ko: "국이 좀 짜요.", en: "The soup is a bit salty.", form: "국 + 이 (subject); 짜다 → 짜요 (identical ㅏ merges)" } },
    "포기|counter": { korean: "포기", note: "The counter for heads of cabbage and similar leafy vegetables: 배추 한 포기. Essential at kimchi-making time.", example: { ko: "배추 두 포기를 샀어요.", en: "I bought two heads of cabbage.", form: "배추 + 두 (native number) + 포기 + 를 (object); 사다 → 샀어요" } },
    "만세|interjection": { korean: "만세", note: "'Hurrah' — literally 'ten thousand years'. Shouted in celebration, and historically at independence rallies.", example: { ko: "만세! 우리가 이겼어요!", en: "Hurrah! We won!", form: "Interjection; 이기다 → 이겼어요 (past, polite casual)" } },
    "지난주|noun": { korean: "지난주", note: "Last week, written solid. Its partners 이번 주 and 다음 주 take a space — an inconsistency worth memorising.", example: { ko: "지난주에 만났어요.", en: "We met last week.", form: "지난주 + 에 (time particle); 만나다 → 만났어요 (past)" } },
    "발 벗고 나서다|expression": { korean: "발 벗고 나서다", note: "'To jump in and help' — literally 'to take off one's shoes and step forward'. Wholehearted, unasked-for help.", example: { ko: "친구가 발 벗고 나서 줬어요.", en: "My friend jumped in to help.", form: "나서다 → 나서 (connector) + 주다 → 줬어요 (for someone's benefit, past)" } },
    "고등학생|noun": { korean: "고등학생", note: "A high school student, years 10 to 12 — the years of intense exam preparation for 수능.", example: { ko: "고등학생 때 아주 바빴어요.", en: "I was very busy when I was a high school student.", form: "고등학생 + 때 (bound noun); 바쁘다 → 바빴어요 (past)" } },
    "닭고기|noun": { korean: "닭고기", note: "Chicken meat. Built from 닭 + 고기, like 소고기 and 돼지고기. Fried chicken is the borrowed 치킨.", example: { ko: "닭고기를 구웠어요.", en: "I grilled the chicken.", form: "닭고기 + 를 (object); 굽다 → 구웠어요 (ㅂ-irregular, past)" } },
    "이라야|particle": { korean: "이라야", note: "'Only if it is', setting a necessary condition: 한국 사람이라야 알아요. 라야 after a vowel. Formal.", example: { ko: "회원이라야 들어갈 수 있어요.", en: "Only members can go in.", form: "회원 + 이라야 (after a batchim); 들어가다 → 들어갈 수 있어요" } },
    "숟가락|noun": { korean: "숟가락", note: "A spoon. Paired with 젓가락 as 수저, the set. Korean rice is eaten with the spoon, not chopsticks.", example: { ko: "숟가락으로 국을 먹어요.", en: "I eat soup with a spoon.", form: "숟가락 + 으로 (instrument); 국 + 을 (object); 먹다 → 먹어요" } },
    "진짜예요|phrase": { korean: "진짜예요", note: "'It is real' or 'seriously'. 진짜예요? asks 'really?'. Casual twin of 정말이에요.", example: { ko: "진짜예요? 못 믿겠어요.", en: "Seriously? I cannot believe it.", form: "진짜 + 예요 (이다 after a vowel; question by intonation)" } },
    "총|determiner": { korean: "총", note: "'Total', in front of a quantity: 총 열 명. Formal, used in counts and reports.", example: { ko: "총 열 명이 왔어요.", en: "A total of ten people came.", form: "총 + 열 명 + 이 (subject); 오다 → 왔어요 (past)" } },
    "요일|noun": { korean: "요일", note: "A day of the week. The set runs 월화수목금토일 + 요일. Asking 무슨 요일이에요? gets you the day.", example: { ko: "오늘 무슨 요일이에요?", en: "What day of the week is it today?", form: "무슨 + 요일 + 이에요 (이다 after a batchim; question)" } },
    "치약|noun": { korean: "치약", note: "Toothpaste, from 치 (tooth) + 약 (medicine). Its partner is 칫솔, a toothbrush.", example: { ko: "치약이 다 떨어졌어요.", en: "We have run out of toothpaste.", form: "치약 + 이 (subject); 떨어지다 → 떨어졌어요 (past)" } },
    "시치미를 떼다|expression": { korean: "시치미를 떼다", note: "'To play innocent' — pretending you know nothing when you clearly do. From a falconry term for removing an owner's name tag.", example: { ko: "그 사람이 시치미를 뗐어요.", en: "He played innocent.", form: "시치미 + 를 (object); 떼다 → 뗐어요 (past, polite casual)" } },
    "자신|pronoun": { korean: "자신", note: "'Oneself', reflexive: 자기 자신을 믿으세요. It also means self-confidence in 자신이 있다.", example: { ko: "자신을 믿으세요.", en: "Believe in yourself.", form: "자신 + 을 (object); 믿다 → 믿으세요 (polite request after a batchim)" } },
    "터|dependent noun": { korean: "터", note: "'Intention' or 'situation', in -을 터이다, usually contracted to -을 테다 or -을 텐데. Rarely seen alone.", example: { ko: "곧 도착할 텐데요.", en: "They should be arriving soon.", form: "도착하다 → 도착할 (modifier) + 터 + 인데 → 텐데요 (supposition)" } },
    "계시다|auxiliary verb": { korean: "계시다", note: "-고 계시다 is the honorific of -고 있다: 선생님이 오고 계세요. Use it whenever the person doing the ongoing action deserves respect.", example: { ko: "할아버지가 주무시고 계세요.", en: "Grandfather is sleeping.", form: "주무시다 → 주무시고 (connector) + 계시다 → 계세요 (honorific progressive)" } },
    "세종대왕|proper noun": { korean: "세종대왕", note: "King Sejong the Great, who commissioned Hangeul in 1443. He is on the 10,000-won note and turns up constantly in cultural reading.", example: { ko: "세종대왕이 한글을 만드셨어요.", en: "King Sejong created Hangeul.", form: "세종대왕 + 이 (subject); 만들다 + 시 → 만드셨어요 (honorific past)" } },
    "이순신|proper noun": { korean: "이순신", note: "Admiral Yi Sun-sin, who defeated the Japanese navy in the 1590s. A national hero, on the 100-won coin and in Gwanghwamun square.", example: { ko: "이순신 장군은 영웅이에요.", en: "Admiral Yi Sun-sin is a hero.", form: "이순신 장군 + 은 (topic); 영웅 + 이에요 (이다 after a batchim)" } },
    "예방 접종|noun phrase": { korean: "예방 접종", note: "Vaccination. 예방 is prevention and 접종 an inoculation. A practical phrase in health and travel reading.", example: { ko: "예방 접종을 받았어요.", en: "I got a vaccination.", form: "예방 접종 + 을 (object); 받다 → 받았어요 (past)" } },
    "어제|adverb": { korean: "어제", note: "'Yesterday', bare before the verb with no particle: 어제 만났어요. The noun form takes particles and is a separate entry.", example: { ko: "어제 친구를 만났어요.", en: "I met a friend yesterday.", form: "어제 before the verb, no particle; 만나다 → 만났어요 (past)" } },
    "미역국을 먹다|expression": { korean: "미역국을 먹다", note: "'To fail an exam' — literally 'to eat seaweed soup', because seaweed is slippery and you slip up. Students avoid the soup before exams for this reason.", example: { ko: "시험에서 미역국을 먹었어요.", en: "I failed the exam.", form: "미역국 + 을 (object); 먹다 → 먹었어요 (past, polite casual)" } },
    "노트|noun": { korean: "노트", note: "A notebook, from the English. 공책 is the native equivalent and is what schools say. 노트하다 also means to take notes.", example: { ko: "노트에 적었어요.", en: "I wrote it in my notebook.", form: "노트 + 에 (location); 적다 → 적었어요 (past, polite casual)" } },
    "만치|particle": { korean: "만치", note: "'As much as' — a variant of 만큼, slightly dated and dialectal. 만큼 is the standard choice.", example: { ko: "생각한 만치 어렵지 않아요.", en: "It is not as hard as I thought.", form: "생각하다 → 생각한 (past modifier) + 만치; 어렵다 → 어렵지 않아요" } },

    // ================================================================ day 26
    "초콜릿|noun": { korean: "초콜릿", note: "Chocolate, counted with 개. 초콜렛 is a common alternative spelling, though 초콜릿 is standard.", example: { ko: "초콜릿을 선물했어요.", en: "I gave chocolate as a gift.", form: "초콜릿 + 을 (object); 선물하다 → 선물했어요 (past)" } },
    "접시|counter": { korean: "접시", note: "The counter for plates of food: 만두 한 접시. Takes native Korean numbers. It is also the noun 'plate'.", example: { ko: "만두 한 접시 주세요.", en: "One plate of dumplings, please.", form: "만두 + 한 (native number) + 접시; 주다 → 주세요" } },
    "얘|interjection": { korean: "얘", note: "'Hey' — to a child or a close friend, contracted from 이 아이. Only downward or among intimates; never to an elder.", example: { ko: "얘, 이리 와 봐.", en: "Hey, come here.", form: "Direct address; 오다 → 와 + 보다 → 봐 (casual request)" } },
    "그렇군요|phrase": { korean: "그렇군요", note: "'I see' — acknowledging new information. The 군요 ending marks fresh realisation, which is exactly the job here.", example: { ko: "아, 그렇군요.", en: "Ah, I see.", form: "그렇다 → 그렇군요 (realisation, polite casual)" } },
    "알겠습니다|phrase": { korean: "알겠습니다", note: "'Understood' — formal acknowledgement of an instruction. The 겠 softens it; plain 압니다 would sound like a boast.", example: { ko: "네, 알겠습니다.", en: "Yes, understood.", form: "알다 + 겠 + 습니다 (present, formal polite)" } },
    "바가지를 쓰다|expression": { korean: "바가지를 쓰다", note: "'To be overcharged' — literally 'to wear a gourd bowl'. Said of tourist prices. Overcharging someone is 바가지를 씌우다.", example: { ko: "시장에서 바가지를 썼어요.", en: "I got overcharged at the market.", form: "바가지 + 를 (object); 쓰다 → 썼어요 (ㅡ drops, past)" } },
    "영|numeral": { korean: "영", note: "Zero, Sino-Korean. 공 is the alternative used when reading phone numbers and digits aloud.", example: { ko: "영 점 오예요.", en: "It is zero point five.", form: "영 + 점 (point) + 오; 이다 → 예요 (after a vowel)" } },
    "반|numeral": { korean: "반", note: "'Half' as a number: 한 시간 반, 반 개. It follows the whole quantity, as in English.", example: { ko: "두 시간 반 걸렸어요.", en: "It took two and a half hours.", form: "두 시간 + 반; 걸리다 → 걸렸어요 (past, polite casual)" } },
    "달러|noun": { korean: "달러", note: "The dollar as a noun. Used as a counter it follows Sino-Korean numbers: 십 달러.", example: { ko: "달러로 계산할게요.", en: "I will pay in dollars.", form: "달러 + 로 (means); 계산하다 → 계산할게요 (intention)" } },
    "무렵|dependent noun": { korean: "무렵", note: "'Around the time of', after a noun or modifier: 저녁 무렵, 해 질 무렵. Literary and evocative.", example: { ko: "해 질 무렵에 도착했어요.", en: "I arrived around sunset.", form: "지다 → 질 (modifier) + 무렵 + 에 (time); 도착하다 → 도착했어요" } },
    "칫솔|noun": { korean: "칫솔", note: "A toothbrush, from 치 (tooth) + 솔 (brush), with the linking ㅅ. Its partner is 치약, toothpaste.", example: { ko: "새 칫솔을 샀어요.", en: "I bought a new toothbrush.", form: "새 + 칫솔 + 을 (object); 사다 → 샀어요 (past)" } },
    "본|determiner": { korean: "본", note: "'This, the present', in front of a noun in formal documents: 본 계약, 본 사건. The register of contracts and notices.", example: { ko: "본 계약은 일 년간 유효해요.", en: "This contract is valid for one year.", form: "본 + 계약 + 은 (topic); 유효하다 → 유효해요" } },
    "잠깐|adverb": { korean: "잠깐", note: "'For a moment', before the verb: 잠깐 기다리세요. The noun form takes particles and is a separate entry.", example: { ko: "잠깐 쉬었다 가요.", en: "Let us rest a moment before going.", form: "잠깐 before the verb; 쉬다 → 쉬었다 (connector); 가다 → 가요" } },
    "아무것|pronoun": { korean: "아무것", note: "'Anything' in a positive sentence, 'nothing' with a negative: 아무것도 없어요. It is nearly always 아무것도 in practice.", example: { ko: "아무것도 없어요.", en: "There is nothing at all.", form: "아무것 + 도 (with a negative); 없다 → 없어요" } },
    "공중전화|noun": { korean: "공중전화", note: "A public telephone. 공중 means public in the sense of shared — 공중화장실 is a public restroom.", example: { ko: "공중전화가 어디에 있어요?", en: "Where is a public telephone?", form: "공중전화 + 가 (subject); 어디 + 에 (location); 있다 → 있어요" } },
    "배고프다|adjective": { korean: "배고프다", note: "To be hungry, written solid. Its subject is the person, unlike the phrase 배가 고파요 where 배 takes the particle. ㅡ-irregular: 배고파요.", example: { ko: "저는 배고파요.", en: "I am hungry.", form: "배고프다 → 배고파요 (ㅡ drops before -아요)" } },
    "배부르다|adjective": { korean: "배부르다", note: "To be full after eating, written solid. 르-irregular: 배불러요. Its opposite is 배고프다.", example: { ko: "너무 많이 먹어서 배불러요.", en: "I ate too much and I am full.", form: "먹다 → 먹어서 (cause); 배부르다 → 배불러요 (르-irregular)" } },
    "국수를 먹다|expression": { korean: "국수를 먹다", note: "'To attend a wedding' — literally 'to eat noodles', because noodles were served at Korean weddings. 언제 국수 먹여 줄 거예요? teases someone about when they will marry.", example: { ko: "언제 국수 먹여 줄 거예요?", en: "When are you going to get married?", form: "먹이다 → 먹여 (causative connector) + 주다 → 줄 거예요 (future)" } },
    "인들|particle": { korean: "인들", note: "'Even if it were', conceding a hypothetical: 왕인들 어쩌겠어요. Literary and rhetorical.", example: { ko: "부자인들 행복할까요?", en: "Even if one were rich, would one be happy?", form: "부자 + 인들; 행복하다 → 행복할까요 (rhetorical question)" } },
    "샤워|noun": { korean: "샤워", note: "A shower. 샤워하다 is the verb. 목욕 is a bath and 세수 washing the face only.", example: { ko: "샤워를 하고 나갔어요.", en: "I showered and went out.", form: "샤워 + 를 (object); 하다 → 하고 (connector); 나가다 → 나갔어요" } },
    "연습하다|verb": { korean: "연습하다", note: "To practise. What you practise takes 을/를: 발음을 연습해요. 연습 alone is the noun.", example: { ko: "매일 발음을 연습해요.", en: "I practise pronunciation every day.", form: "발음 + 을 (object); 연습하다 → 연습해요" } },
    "세탁기|noun": { korean: "세탁기", note: "A washing machine. 세탁 is laundry and 기 the machine suffix — 청소기 is a vacuum cleaner, built the same way.", example: { ko: "세탁기가 고장 났어요.", en: "The washing machine broke down.", form: "세탁기 + 가 (subject); 고장 나다 → 났어요 (past)" } },
    "도착|noun": { korean: "도착", note: "Arrival. 도착하다 is the verb and 도착 시간 is arrival time. Its opposite is 출발.", example: { ko: "도착 시간이 언제예요?", en: "What is the arrival time?", form: "도착 시간 + 이 (subject); 언제 + 예요 (question)" } },
    "손을 떼다|expression": { korean: "손을 떼다", note: "'To wash one's hands of' something — to withdraw from an involvement. Literally 'to take the hand off'.", example: { ko: "그 일에서 손을 뗐어요.", en: "I washed my hands of that matter.", form: "일 + 에서 (source); 손 + 을 (object); 떼다 → 뗐어요 (past)" } },
    "어깨가 무겁다|expression": { korean: "어깨가 무겁다", note: "'To feel a heavy burden' of responsibility — the same image as English 'weight on one's shoulders'.", example: { ko: "책임 때문에 어깨가 무거워요.", en: "The responsibility weighs on me.", form: "책임 + 때문에 (cause); 어깨 + 가 (subject); 무겁다 → 무거워요" } },
    "응급 상황|noun phrase": { korean: "응급 상황", note: "An emergency situation. 응급실 is the emergency room. A practical phrase for safety reading.", example: { ko: "응급 상황에는 119에 전화하세요.", en: "In an emergency, call 119.", form: "응급 상황 + 에는; 119 + 에 (recipient); 전화하다 → 전화하세요" } },
    "식사하다|verb": { korean: "식사하다", note: "To have a meal, more formal than 밥을 먹다. 식사하셨어요? ('have you eaten?') is a standard Korean greeting, closer to 'how are you' than a literal question.", example: { ko: "식사하셨어요?", en: "Have you eaten?", form: "식사하다 + 시 → 식사하셨어요 (honorific past, question)" } },
    "요컨대|conjunction": { korean: "요컨대", note: "'In short' — summing up an argument. Formal and written, the register of essays.", example: { ko: "요컨대 시간이 부족해요.", en: "In short, there is not enough time.", form: "요컨대 opens the summary; 부족하다 → 부족해요" } },
    "잔|dependent noun": { korean: "잔", note: "The bound-noun counter for cups and glasses of a drink: 커피 한 잔, 맥주 두 잔. Takes native Korean numbers.", example: { ko: "맥주 두 잔 주세요.", en: "Two glasses of beer, please.", form: "맥주 + 두 (native number) + 잔; 주다 → 주세요" } },
    "초등학교|noun": { korean: "초등학교", note: "Elementary school, years 1 to 6. It opens the set 초등학교 / 중학교 / 고등학교.", example: { ko: "초등학교 때 친구예요.", en: "She is a friend from elementary school.", form: "초등학교 + 때 (bound noun); 친구 + 예요 (이다 after a vowel)" } },
    "내일|adverb": { korean: "내일", note: "'Tomorrow', bare before the verb with no particle: 내일 봐요. The noun form takes particles and is a separate entry.", example: { ko: "내일 다시 올게요.", en: "I will come again tomorrow.", form: "내일 before the verb, no particle; 오다 → 올게요 (intention)" } },
    "상|counter": { korean: "상", note: "The counter for tables of food and for awards: 한 상 차리다 (to set a full table), 상을 받다 (to receive a prize).", example: { ko: "한 상 가득 차렸어요.", en: "I set out a full table of food.", form: "한 (native number) + 상 + 가득; 차리다 → 차렸어요 (past)" } },
    "옳지|interjection": { korean: "옳지", note: "'That's it, good' — approval as someone gets something right. Said to children and learners.", example: { ko: "옳지, 잘했어요!", en: "That's it, well done!", form: "Interjection; 잘하다 → 잘했어요 (past, polite casual)" } },
    "공휴일|noun": { korean: "공휴일", note: "A public holiday specifically. 휴일 is any day off and 방학 a school vacation.", example: { ko: "내일은 공휴일이에요.", en: "Tomorrow is a public holiday.", form: "내일 + 은 (topic); 공휴일 + 이에요 (이다 after a batchim)" } },
    "이란|particle": { korean: "이란", note: "'As for, the thing called', introducing a definition: 사랑이란 무엇일까요? 란 after a vowel. Used to open a topic for discussion.", example: { ko: "사랑이란 무엇일까요?", en: "What is this thing called love?", form: "사랑 + 이란 (after a batchim); 무엇 + 이다 → 일까요 (musing question)" } },
    "볼펜|noun": { korean: "볼펜", note: "A ballpoint pen, counted with 자루. 연필 is a pencil and 펜 the generic borrowed word.", example: { ko: "볼펜으로 쓰세요.", en: "Please write with a ballpoint pen.", form: "볼펜 + 으로 (instrument); 쓰다 → 쓰세요 (polite request)" } },
    "갖은|determiner": { korean: "갖은", note: "'All kinds of', in front of a noun: 갖은 고생. It suggests an exhausting variety, usually of hardship.", example: { ko: "갖은 고생을 했어요.", en: "I went through all kinds of hardship.", form: "갖은 + 고생 + 을 (object); 하다 → 했어요 (past)" } },

    // ================================================================ day 27
    "서로|pronoun": { korean: "서로", note: "'Each other' used as a noun, so it takes particles: 서로를 이해해요, 서로의 생각. The adverb form is more common.", example: { ko: "서로를 이해해야 해요.", en: "We must understand each other.", form: "서로 + 를 (object); 이해하다 → 이해해야 해요 (obligation)" } },
    "잡수시다|verb": { korean: "잡수시다", note: "The honorific of 먹다, for an elder eating: 할아버지가 잡수세요. 드시다 is the more common everyday honorific.", example: { ko: "할아버지, 많이 잡수세요.", en: "Grandfather, please eat plenty.", form: "잡수시다 → 잡수세요 (honorific polite request)" } },
    "핸드폰|noun": { korean: "핸드폰", note: "A mobile phone, the Korean-coined English. 휴대폰 and 휴대 전화 are the more standard alternatives; all three are used.", example: { ko: "핸드폰을 집에 두고 왔어요.", en: "I left my phone at home.", form: "핸드폰 + 을 (object); 두다 → 두고 (connector); 오다 → 왔어요" } },
    "코가 높다|expression": { korean: "코가 높다", note: "'To be arrogant' — literally 'a high nose', the image of looking down at people. 콧대가 높다 is the fuller version.", example: { ko: "그 사람은 코가 높아요.", en: "That person is arrogant.", form: "코 + 가 (subject); 높다 → 높아요 (present, polite casual)" } },
    "간이 크다|expression": { korean: "간이 크다", note: "'To be bold, fearless' — literally 'a big liver', where Korean locates courage. Its opposite, 간이 작다, means timid.", example: { ko: "간이 큰 사람이에요.", en: "He is a fearless person.", form: "간 + 이 (subject); 크다 → 큰 (modifier) + 사람; 이다 → 이에요" } },
    "낯이 익다|expression": { korean: "낯이 익다", note: "'To look familiar' — literally 'the face is ripe'. Said of someone you half-recognise. Its opposite is 낯설다.", example: { ko: "저 사람 낯이 익어요.", en: "That person looks familiar.", form: "낯 + 이 (subject); 익다 → 익어요 (present, polite casual)" } },
    "속이 타다|expression": { korean: "속이 타다", note: "'To be worried sick' — literally 'the insides burn'. Anxiety while waiting for news you cannot influence.", example: { ko: "연락이 없어서 속이 타요.", en: "I am worried sick because there is no word.", form: "없다 → 없어서 (cause); 속 + 이 (subject); 타다 → 타요" } },
    "휴지통|noun": { korean: "휴지통", note: "A wastebasket. 통 is the container suffix — 쓰레기통 is the general rubbish bin. Also the desktop recycle bin.", example: { ko: "휴지통에 버리세요.", en: "Please throw it in the bin.", form: "휴지통 + 에 (destination); 버리다 → 버리세요 (polite request)" } },
    "모르겠습니다|phrase": { korean: "모르겠습니다", note: "'I do not know', formal. The 겠 softens the refusal — 모릅니다 is blunt to the point of curt.", example: { ko: "죄송하지만 모르겠습니다.", en: "I am sorry, but I do not know.", form: "모르다 + 겠 + 습니다 (present, formal polite)" } },
    "이해했어요|phrase": { korean: "이해했어요", note: "'I understood it.' For acknowledging an instruction in the moment, Koreans say 알겠어요 instead — this one reports comprehension of content.", example: { ko: "설명을 다 이해했어요.", en: "I understood the whole explanation.", form: "설명 + 을 (object); 이해하다 → 이해했어요 (past)" } },
    "질문하다|verb": { korean: "질문하다", note: "To ask a question. The person asked takes 에게/한테: 선생님한테 질문했어요. 물어보다 is the softer everyday choice.", example: { ko: "선생님한테 질문했어요.", en: "I asked the teacher a question.", form: "선생님 + 한테 (recipient); 질문하다 → 질문했어요 (past)" } },
    "몇몇|numeral": { korean: "몇몇", note: "'A few, some' — 몇 doubled for a vague small number: 몇몇 사람. It stands before a noun without a counter.", example: { ko: "몇몇 사람만 왔어요.", en: "Only a few people came.", form: "몇몇 + 사람 + 만 (only); 오다 → 왔어요 (past)" } },
    "여럿|numeral": { korean: "여럿", note: "'Several people or things', standing alone as a noun: 여럿이 모였어요. 여러 is its determiner form and needs a noun after it.", example: { ko: "여럿이 함께 갔어요.", en: "Several of us went together.", form: "여럿 + 이 (subject); 함께 + 가다 → 갔어요 (past)" } },
    "님|dependent noun": { korean: "님", note: "The honorific suffix for a person: 선생님, 사장님, 고객님. Online it also attaches to usernames. It never stands alone.", example: { ko: "고객님, 잠시만 기다려 주세요.", en: "Sir/Madam, please wait a moment.", form: "고객 + 님 (honorific suffix); 기다리다 → 기다려 + 주다 → 주세요" } },
    "크리스마스|noun": { korean: "크리스마스", note: "Christmas, a public holiday in Korea and treated largely as a couples' occasion rather than a family one.", example: { ko: "크리스마스에 뭐 해요?", en: "What are you doing at Christmas?", form: "크리스마스 + 에 (time); 하다 → 해요 (present, question)" } },
    "야|particle": { korean: "야", note: "The vocative particle after a vowel — calling a friend by name: 민수야! Its consonant partner is 아: 지훈아! Only for people you address casually.", example: { ko: "민수야, 어디 가?", en: "Minsu, where are you going?", form: "민수 ends in a vowel so it takes 야; a batchim name takes 아: 지훈아" } },
    "아|particle": { korean: "아", note: "The vocative particle after a consonant: 지훈아! Its vowel partner is 야. Casual address only — never with a title or an elder.", example: { ko: "지훈아, 밥 먹었어?", en: "Jihun, have you eaten?", form: "지훈 ends in a batchim so it takes 아; a vowel name takes 야: 민수야" } },
    "갈비|noun": { korean: "갈비", note: "Ribs, and the grilled short-rib dish. 갈비탕 is the soup version and 갈비찜 the braised one.", example: { ko: "갈비를 먹으러 갔어요.", en: "We went to eat galbi.", form: "갈비 + 를 (object); 먹다 → 먹으러 (purpose); 가다 → 갔어요" } },
    "냉면|noun": { korean: "냉면", note: "Cold buckwheat noodles, eaten in summer and after grilled meat. 물냉면 comes in broth, 비빔냉면 mixed with sauce.", example: { ko: "여름에는 냉면이 최고예요.", en: "In summer, cold noodles are the best.", form: "여름 + 에는 (time, topic-marked); 냉면 + 이 (subject); 이다 → 예요" } },
    "아이스크림|noun": { korean: "아이스크림", note: "Ice cream, counted with 개. Eaten with 먹다, not 마시다.", example: { ko: "아이스크림을 먹고 싶어요.", en: "I want to eat ice cream.", form: "아이스크림 + 을 (object); 먹다 → 먹고 싶어요 (-고 싶다)" } },
    "추석|proper noun": { korean: "추석", note: "Chuseok, the autumn harvest festival — Korea's biggest holiday alongside 설날. Families travel home and share 송편.", example: { ko: "추석에 고향에 가요.", en: "I go to my hometown at Chuseok.", form: "추석 + 에 (time); 고향 + 에 (destination); 가다 → 가요" } },
    "안전 사고|noun phrase": { korean: "안전 사고", note: "A safety accident — the phrase used in workplace and public-safety notices. 안전 is safety, 사고 an accident.", example: { ko: "안전 사고를 예방해야 해요.", en: "Safety accidents must be prevented.", form: "안전 사고 + 를 (object); 예방하다 → 예방해야 해요 (obligation)" } },
    "선물하다|verb": { korean: "선물하다", note: "To give a gift. The recipient takes 에게/한테 and the gift takes 을/를: 친구한테 책을 선물했어요.", example: { ko: "친구한테 책을 선물했어요.", en: "I gave my friend a book as a gift.", form: "친구 + 한테 (recipient); 책 + 을 (object); 선물하다 → 선물했어요" } },
    "이처럼|conjunction": { korean: "이처럼", note: "'Like this, in this way' — pointing back at what was just described, usually to draw a conclusion. Written register.", example: { ko: "이처럼 한국은 빠르게 변했어요.", en: "In this way Korea changed rapidly.", form: "이처럼 opens the clause; 변하다 → 변했어요 (past)" } },
    "토막|counter": { korean: "토막", note: "The counter for chunks and cut segments, especially of fish: 생선 두 토막. Takes native Korean numbers.", example: { ko: "생선 한 토막을 구웠어요.", en: "I grilled a piece of fish.", form: "생선 + 한 (native number) + 토막 + 을 (object); 굽다 → 구웠어요" } },
    "어이|interjection": { korean: "어이", note: "'Hey' — calling out to someone at a distance. Blunt, and rude to a senior. 저기요 is the polite alternative.", example: { ko: "어이, 거기 잠깐만!", en: "Hey, hold on there!", form: "Interjection; 잠깐 + 만 (just a moment)" } },
    "딴|determiner": { korean: "딴", note: "'Other, another', in front of a noun: 딴 사람, 딴 데. Casual and slightly dismissive; 다른 is the neutral choice.", example: { ko: "딴 데로 갈까요?", en: "Shall we go somewhere else?", form: "딴 + 데 + 로 (direction); 가다 → 갈까요 (suggestion, question)" } },
    "남|pronoun": { korean: "남", note: "'Other people, a stranger' — someone outside your circle. 남의 일 is 'someone else's business', and 남남 means two people are unrelated.", example: { ko: "남의 일에 신경 쓰지 마세요.", en: "Do not concern yourself with other people's business.", form: "남 + 의 (possessive); 일 + 에; 신경 쓰다 → 쓰지 마세요 (prohibition)" } },
    "나위|dependent noun": { korean: "나위", note: "'Room for, need for', only in -을 나위 없다: 더할 나위 없어요 ('it could not be better'). It never appears alone.", example: { ko: "더할 나위 없이 좋아요.", en: "It could not be better.", form: "더하다 → 더할 (modifier) + 나위 없이; 좋다 → 좋아요" } },
    "실례하다|verb": { korean: "실례하다", note: "To excuse oneself, or to commit a small discourtesy. You will meet it as 실례합니다 and 실례지만.", example: { ko: "잠깐 실례하겠습니다.", en: "Please excuse me for a moment.", form: "실례하다 + 겠 + 습니다 (intention, formal polite)" } },
    "중국어|noun": { korean: "중국어", note: "The Chinese language. Languages take 어: 한국어, 영어, 일본어. 중국말 is the colloquial equivalent.", example: { ko: "중국어를 배우고 있어요.", en: "I am learning Chinese.", form: "중국어 + 를 (object); 배우다 → 배우고 있어요 (progressive)" } }
  };

  return { NOTES: NOTES };
});
